const o={1:[{kind:"Portrait",title:"Vial of glowing ultrapure hydrogen",text:"Physical form — High-pressure pure hydrogen gas in a discharge vial glowing with a characteristic violet-pink color. (glowing gas)",image:"images/elements/001_H/02_Vial_of_glowing_ultrapure_hydrogen.jpg",priority:"core",display_context:"orbital",tags:["portrait","H","1"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Vial_of_glowing_ultrapure_hydrogen.jpg"}]},{kind:"Science",title:"Hydrogen discharge-tube experiment",text:"Physical form — Close-up of a low-pressure hydrogen gas discharge tube glowing with a red-to-violet light. (close crop)",image:"images/elements/001_H/03_Hydrogen_discharge_tube_cropped.jpg",priority:"core",display_context:"orbital",tags:["science","H","1"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hydrogen_discharge_tube_cropped.jpg"}]},{kind:"Science",title:"Hydrogen isotopes schematic",text:"Isotopes — The three isotopes of hydrogen: protium (no neutrons, ~99.98%), deuterium (1 neutron, stable), and tritium (2 neutrons, radioactive). (isotopes)",image:"images/elements/001_H/05_Hydrogen_Deuterium_Tritium_scheme_without_text.png",priority:"core",display_context:"orbital",tags:["science","H","1"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hydrogen_Deuterium_Tritium_scheme_without_text.png"}]},{kind:"Uses",title:"Modern hydrogen fuel cell transit bus",text:"Practical application — Hydrogen fuel cells are commercialized in public transit buses, offering zero emissions, long range, and fast refueling. (transport)",image:"images/elements/001_H/10_Hydrogen_fuel_cell_bus.jpg",priority:"core",display_context:"orbital",tags:["uses","H","1"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hydrogen_fuel_cell_bus.jpg"}]},{kind:"Uses",title:"Industrial alkaline water electrolyzer",text:"Practical application — Reactor schematic of alkaline water electrolysis, producing high-purity hydrogen and oxygen as a foundation for green hydrogen energy. (electrolysis diagram)",image:"images/elements/001_H/01_Alkaline_water_electrolyser.png",priority:"core",display_context:"orbital",tags:["uses","H","1"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Alkaline_water_electrolyser.png"}]},{kind:"Uses",title:"Hydrogen fuel cell electrochemical principles",text:"Practical application — Schematic of a hydrogen fuel cell, converting hydrogen and oxygen to electricity and water with zero emissions. (fuel cell diagram)",image:"images/elements/001_H/09_Hydrogen_fuel_cell_schematic.jpg",priority:"core",display_context:"orbital",tags:["uses","H","1"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hydrogen_fuel_cell_schematic.jpg"}]},{kind:"Safety",title:"Hydrogen explosion hazard",text:"[Safety Warning] Hydrogen is an extremely flammable and explosive gas with a very wide flammability limit in air (4.0% - 75.0%). Mixtures with air or oxygen ignite easily from sparks, causing violent explosions. Gas leak detection systems, proper grounding, and ventilation are mandatory. (reaction hazard)",image:"images/elements/001_H/06_Hydrogen_explosion.jpg",priority:"core",display_context:"orbital",tags:["safety","H","1"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hydrogen_explosion.jpg"}]},{kind:"History",title:"Hydrogen discovery timeline",text:"Milestones of hydrogen: from gas preparation and combustion products to isotopes and modern green energy.",image:"images/elements/001_H/14_Cavendish_Henry.jpg",priority:"core",display_context:"orbital",tags:["history","H","1"],panel:{type:"timeline",items:[{year:"1766",title:"Henry Cavendish isolates 'inflammable air'",text:"English chemist Henry Cavendish isolates hydrogen by reacting metals with acids, measuring its density and combustion products.",image:"images/elements/001_H/14_Cavendish_Henry.jpg"},{year:"1783",title:"Lavoisier names Hydrogen",text:"French chemist Antoine Lavoisier confirms hydrogen combustion yields water, naming it 'hydrogen'.",image:"images/elements/001_H/11_David_-_Portrait_of_Monsieur_Lavoisier__cropped_.jpg"},{year:"1931",title:"Harold Urey discovers deuterium",text:"Harold Urey isolates deuterium through low-temperature distillation of liquid hydrogen, laying the groundwork for nuclear physics.",image:"images/elements/001_H/18_Harold_Urey_1934.jpg"}]},sources:[{label:"Wikimedia Commons — Harold Urey, 1934",url:"https://commons.wikimedia.org/wiki/File:Harold_Urey,_1934.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Hydrogen emission spectrum",text:"Emission spectrum — Spectral lines of Hydrogen (H) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/001_H/22_1_(H_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","h","1"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:1_%28H_I%29_NIST_ASD_emission_spectrum.png"}]}],2:[{kind:"Portrait",title:"Low-pressure pure helium gas discharge tube close-up",text:"Physical form — A low-pressure helium gas discharge tube glowing with a pale peach-orange light under high voltage. (discharge crop)",image:"images/elements/002_He/02_Helium_discharge_tube__cropped_.jpg",priority:"core",display_context:"orbital",tags:["portrait","He","2"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Helium_discharge_tube__cropped_.jpg"}]},{kind:"Science",title:"Fountain effect in superfluid liquid helium",text:"Physical form — Liquid helium-4 transitioning into a superfluid (Helium II) below 2.17 K, exhibiting zero viscosity and the fountain effect. (superfluid)",image:"images/elements/002_He/03_Helium_fountain_01.png",priority:"core",display_context:"orbital",tags:["science","He","2"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Helium_fountain_01.png"}]},{kind:"Science",title:"Rollin film wall creeping in superfluid liquid helium",text:"Physical form — Superfluid liquid helium (Helium II) creeps up container walls in a thin Rollin film due to its zero viscosity. (liquid helium)",image:"images/elements/002_He/13_Liquid_helium_Rollin_film.jpg",priority:"core",display_context:"orbital",tags:["science","He","2"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Liquid_helium_Rollin_film.jpg"}]},{kind:"Science",title:"Helium quantum atomic orbital model",text:"Scientific structure — Helium (Z=2) has the most stable 1s² closed-shell electron configuration, giving it the highest ionization energy and extreme chemical inertness. (atom)",image:"images/elements/002_He/05_Helium_atom_QM.svg",priority:"core",display_context:"orbital",tags:["science","He","2"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Helium_atom_QM.svg"}]},{kind:"Uses",title:"Filling weather balloons and airships",text:"Practical application — Due to helium's low density and non-flammable nature, it is widely used in airships, weather balloons, and party balloons. (balloons)",image:"images/elements/002_He/11_Helium_balloons.jpg",priority:"core",display_context:"orbital",tags:["uses","He","2"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Helium_balloons.jpg"}]},{kind:"Safety",title:"Compressed gas cylinder and asphyxiation risk",text:"Safety symbol — This GHS gas-cylinder pictogram is not an incident photograph. Helium is non-toxic and inert, but a large release in a confined space can displace oxygen and pressurized cylinders require mechanical safety controls.",image:"images/elements/002_He/04_GHS-pictogram-bottle.svg",priority:"core",display_context:"orbital",tags:["safety","He","2"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-bottle.svg"}]},{kind:"History",title:"Helium discovery timeline",text:"Milestones of helium: from solar spectrum lines and terrestrial ores to liquid state and superfluidity.",image:"images/elements/002_He/14_Jules_Janssen.jpg",priority:"core",display_context:"orbital",tags:["history","He","2"],panel:{type:"timeline",items:[{year:"1868",title:"Helium spectrum detected during solar eclipse",text:"Janssen and Lockyer detect a bright yellow spectral line during the 1868 eclipse, naming the element Helium.",image:"images/elements/002_He/14_Jules_Janssen.jpg"},{year:"1895",title:"Ramsay isolates terrestrial helium",text:"Sir William Ramsay treats cleveite mineral with acid, successfully isolating gaseous helium on Earth.",image:"images/elements/002_He/17_Portrait_of_William_Ramsay.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Helium emission spectrum",text:"Emission spectrum — Spectral lines of Helium (He) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/002_He/25_2_(He_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","he","2"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:2_%28He_I%29_NIST_ASD_emission_spectrum.png"}]}],3:[{kind:"Portrait",title:"Freshly cut shiny lithium surface",text:"Physical form — Lithium is the lightest solid alkali metal. Its freshly cut surface shows a bright metallic silvery-white luster, which rapidly oxidizes and darkens in moist air. (fresh metal)",image:"images/elements/003_Li/01_Lithiumcut_cropped.jpg",priority:"core",display_context:"orbital",tags:["portrait","Li","3"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Lithiumcut_cropped.jpg"}]},{kind:"Safety",title:"Lithium metal stored under protective oil",text:"Physical properties — Pure lithium metal pieces floating on the surface of mineral oil. With a density of only 0.534 g/cm³, it is the least dense solid element and floats on oil. (metal in oil)",image:"images/elements/003_Li/10_Lithium_element.jpg",priority:"core",display_context:"orbital",tags:["safety","Li","3"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Lithium_element.jpg"}]},{kind:"Uses",title:"High-purity lithium pellets for synthesis",text:"Industrial form — High-purity lithium metal pellets coated with a protective wax layer, commonly used in organic synthesis and pharmaceutical manufacture. (pellets)",image:"images/elements/003_Li/09_LithiumPelletsUSGOV.jpg",priority:"core",display_context:"orbital",tags:["uses","Li","3"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:LithiumPelletsUSGOV.jpg"}]},{kind:"Origin",title:"Petalite lithium-bearing mineral",text:"Mineral source — Petalite crystal, a lithium-bearing mineral from which the element lithium was first discovered. (mineral)",image:"images/elements/003_Li/15_Petalite.jpg",priority:"core",display_context:"orbital",tags:["origin","Li","3"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Petalite.jpg"}]},{kind:"Origin",title:"Spodumene lithium mineral specimen",text:"Mineral source — Spodumene crystals, an important lithium aluminium silicate mineral mined as a primary lithium source. (mineral)",image:"images/elements/003_Li/16_Spodumene__GeoDIL_number_-_401_.jpg",priority:"core",display_context:"orbital",tags:["origin","Li","3"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Spodumene_(GeoDIL_number_-_401).jpg"}]},{kind:"Science",title:"Characteristic crimson flame test of lithium",text:"Flame test — Lithium compounds burned in a flame produce a brilliant, characteristic crimson/magenta emission. (flame test)",image:"images/elements/003_Li/04_FlammenfärbungLi.png",priority:"core",display_context:"orbital",tags:["science","Li","3"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Flammenf%C3%A4rbungLi.png"}]},{kind:"Uses",title:"High energy density lithium-ion batteries",text:"Practical application — High energy density lithium-ion batteries are standard in mobile devices, electric vehicles, and grid storage due to lithium's low reduction potential and high specific capacity. (battery pack)",image:"images/elements/003_Li/12_NASA_Lithium_Ion_Polymer_Battery.jpg",priority:"core",display_context:"orbital",tags:["uses","Li","3"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:NASA_Lithium_Ion_Polymer_Battery.jpg"}]},{kind:"Safety",title:"Reactions with moisture and paraffin oil storage",text:"[Safety Warning] Lithium metal is highly reactive. It reacts vigorously with water or atmospheric moisture to release flammable hydrogen gas and produce highly corrosive lithium hydroxide. It must be stored fully submerged in anhydrous mineral oil, paraffin, or under dry argon, and handled with extreme care to prevent fire or chemical burns. (storage)",image:"images/elements/003_Li/05_Lithium_paraffin.jpg",priority:"core",display_context:"orbital",tags:["safety","Li","3"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Lithium_paraffin.jpg"}]},{kind:"History",title:"Lithium discovery and commercial evolution",text:"Historical record — Johan August Arfwedson recognized lithium as a distinct substance while analyzing petalite in 1817.",image:"images/elements/003_Li/13_Arfwedson_Johan_A.jpg",priority:"core",display_context:"orbital",tags:["history","Li","3"],panel:{type:"timeline",items:[{year:"1817",title:"Arfwedson discovers lithium in petalite mineral",text:"Swedish chemist Arfwedson analyzes petalite and discovers a new alkali metal oxide, naming it 'Lithium' (stone-alkali).",image:"images/elements/003_Li/13_Arfwedson_Johan_A.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Lithium emission spectrum (NIST ASD)",text:"Emission spectrum — The characteristic spectral lines of Lithium (Li), recorded by the NIST Atomic Spectra Database. Each line corresponds to a specific electron transition unique to Li. These lines are used for spectroscopic identification and stellar abundance measurements. (NIST ASD)",image:"images/elements/003_Li/23_3_(Li_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","spectroscopy","li","3"],sources:[{label:"NIST Atomic Spectra Database",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:3_%28Li_I%29_NIST_ASD_emission_spectrum.png"}]}],4:[{kind:"Portrait",title:"High-purity crystalline beryllium block",text:"Physical form — A crystalline block of beryllium metal. Despite its light weight, its structural stiffness and tensile strength are superior to titanium alloys in aerospace applications. (black background)",image:"images/elements/004_Be/09_Beryllium-in-Black.jpg",priority:"core",display_context:"orbital",tags:["portrait","Be","4"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Beryllium-in-Black.jpg"}]},{kind:"Uses",title:"Beryllium foil X-ray window",text:"Physical properties — Ultra-thin beryllium metal foil. Due to its low atomic number, it is highly transparent to X-rays and is widely used as vacuum windows in X-ray detectors. (foils)",image:"images/elements/004_Be/03_Be_foils.jpg",priority:"core",display_context:"orbital",tags:["uses","Be","4"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Be_foils.jpg"}]},{kind:"Origin",title:"Aquamarine beryl crystal specimen",text:"Mineral resource — Aquamarine, a blue-green gemstone variety of beryl (Be₃Al₂Si₆O₁₈). Beryl is the most important natural mineral source of beryllium. (mineral)",image:"images/elements/004_Be/12_Aquamarine_and_Muskovite.jpg",priority:"core",display_context:"orbital",tags:["origin","Be","4"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Aquamarine_and_Muskovite.jpg"}]},{kind:"Origin",title:"Rare red beryl gemstone specimen",text:"Mineral resource — Red beryl (bixbite) is an extremely rare manganese-bearing beryllium silicate gemstone formed under highly specific geological conditions. (mineral)",image:"images/elements/004_Be/16_Red_Beryl.jpg",priority:"core",display_context:"orbital",tags:["origin","Be","4"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Red_Beryl.jpg"}]},{kind:"Origin",title:"Industrial bertrandite ore specimen",text:"Mineral resource — Bertrandite is a hydrated beryllium silicate mineral, serving as the primary commercial ore mined and processed for beryllium extraction in modern industry. (mineral)",image:"images/elements/004_Be/13_Bertrandite.jpg",priority:"core",display_context:"orbital",tags:["origin","Be","4"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Bertrandite.jpg"}]},{kind:"Uses",title:"JWST gold-coated beryllium primary mirror",text:"Core application — The primary mirror of the James Webb Space Telescope consists of 18 gold-coated beryllium segments, chosen for beryllium's light weight, extreme rigidity, and thermal stability in deep space. (space mirror)",image:"images/elements/004_Be/10_James_Webb_Space_Telescope_Mirrors_Will_Piece_Together_Cosmic_Puzzles__30108124923_.jpg",priority:"core",display_context:"orbital",tags:["uses","Be","4"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:James_Webb_Space_Telescope_Mirrors_Will_Piece_Together_Cosmic_Puzzles_(30108124923).jpg"}]},{kind:"Safety",title:"Demon core criticality accident reflection",text:"[Safety & History] In the 1946 Los Alamos criticality accident, a hemisphere of pure beryllium was used as a neutron reflector. A screwdriver slip caused the reflector to close fully, triggering a lethal burst of radiation. (criticality accident)",image:"images/elements/004_Be/07_Tickling_the_Dragons_Tail.jpg",priority:"core",display_context:"orbital",tags:["safety","Be","4"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Tickling_the_Dragons_Tail.jpg"}]},{kind:"History",title:"Beryllium discovery and scientific archives",text:"Historical records — Beryllium was first identified as an oxide in emeralds by Vauquelin in 1798, named 'glucinum' due to its sweet salts, and isolated as a metal in 1828.",image:"images/elements/004_Be/15_Vauquelin__membre_de_l_Institut.jpg",priority:"core",display_context:"orbital",tags:["history","Be","4"],panel:{type:"timeline",items:[{year:"1798",title:"Vauquelin identifies beryllium oxide in beryl",text:"French chemist Vauquelin analyzes beryl and emeralds, discovering a new oxide that forms sweet-tasting salts.",image:"images/elements/004_Be/15_Vauquelin__membre_de_l_Institut.jpg"},{year:"1828",title:"Wöhler and Bussy isolate pure beryllium",text:"German chemist Wöhler and French chemist Bussy independently reduce anhydrous beryllium chloride with potassium to isolate pure metallic beryllium powder.",image:"images/elements/004_Be/24_Friedrich_Woehler_portrait.jpg"},{year:"2021",title:"JWST launches with 18 gold-coated beryllium mirror segments",text:"The James Webb Space Telescope, representing the pinnacle of aerospace-grade beryllium mirror fabrication, was successfully launched by an Ariane 5 rocket to the Sun-Earth L2 Lagrangian point.",image:"images/elements/004_Be/25_JWST_launch_2021.jpg"}]},sources:[{label:"Nicolas-Louis Vauquelin portrait — Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Vauquelin,_membre_de_l%27Institut.jpg"},{label:"Portrait of Friedrich Wöhler — Science History Institute via Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Portrait_of_Friedrich_W%C3%B6hler_-_DPLA_-_6c0ff4bba3b2237cecb2af31dc8fd0bc.jpg"},{label:"James Webb Space Telescope launch, 25 December 2021 — NASA via Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:James_Webb_Space_Telescope_Launch_(NHQ202112250010).jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Beryllium emission spectrum",text:"Emission spectrum — Spectral lines of Beryllium (Be) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/004_Be/22_4_(Be_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","be","4"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:4_%28Be_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Beryllium window in a sealed X-ray tube",text:"Scientific instrumentation — An annotated sealed-anode X-ray tube. The cutaway identifies its thin beryllium window, which lets X-rays leave the evacuated tube while maintaining the vacuum.",image:"images/elements/004_Be/11_Used_sealed_anode_x-ray_tube_in_Finnish.jpg",priority:"standard",display_context:"orbital",tags:["science","instrumentation","Be","4"],sources:[{label:"Wikimedia Commons — Used sealed anode X-ray tube in Finnish",url:"https://commons.wikimedia.org/wiki/File:Used_sealed_anode_x-ray_tube_in_Finnish.jpg"}]}],5:[{kind:"Portrait",title:"High-purity crystalline metalloid boron",text:"Physical form — 99.7% pure crystalline boron granules, showing a dark grey metallic luster. Crystalline boron is extremely hard (Mohs hardness ~9.3), second only to diamond. (purity sample)",image:"images/elements/005_B/01_Boron_99.7_percent.jpg",priority:"core",display_context:"orbital",tags:["portrait","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Boron_99.7_percent.jpg"}]},{kind:"Science",title:"Amorphous boron compared with crystalline boron",text:"Physical form — Amorphous boron powder, appearing as a fine, dark brown to black powder, which is chemically much more reactive than the crystalline form. (sample)",image:"images/elements/005_B/08_Boron.jpg",priority:"core",display_context:"orbital",tags:["science","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Boron.jpg"}]},{kind:"Science",title:"Beta-rhombohedral boron structure model",text:"Physical form — Crystalline boron (beta-rhombohedral), showing a stable icosahedral framework of boron atoms. (crystal structure)",image:"images/elements/005_B/02_Betaboron.jpg",priority:"core",display_context:"orbital",tags:["science","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Betaboron.jpg"}]},{kind:"Origin",title:"Natural monoclinic borax mineral crystals",text:"Mineral source — Natural borax crystals (sodium tetraborate decahydrate), the most abundant and historically important borate mineral mined globally. (mineral)",image:"images/elements/005_B/14_Borax_crystals.jpg",priority:"core",display_context:"orbital",tags:["origin","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Borax_crystals.jpg"}]},{kind:"Origin",title:"Fibrous optical TV rock (Ulexite)",text:"Mineral source — Fibrous ulexite, popularly known as 'TV Rock'. Its natural parallel crystalline fibers act like natural fiber-optic cables, projecting images from below directly to the top surface. (mineral)",image:"images/elements/005_B/20_Ulexita_br.jpg",priority:"core",display_context:"orbital",tags:["origin","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Ulexita_br.jpg"}]},{kind:"Origin",title:"Colemanite borate mineral specimen",text:"Mineral source — Colemanite is a hydrated calcium borate mineral, prized as an important industrial source for producing boric acid and borax derivatives. (mineral)",image:"images/elements/005_B/16_Colemanite_-_USGS_Mineral_Specimens_096.jpg",priority:"core",display_context:"orbital",tags:["origin","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Colemanite_-_USGS_Mineral_Specimens_096.jpg"}]},{kind:"Science",title:"Characteristic bright green flame test",text:"Flame test — Combustion of boron compounds (such as trimethyl borate) produces a brilliant, characteristic green flame due to outer electron transitions. (flame test)",image:"images/elements/005_B/05_FlammenfärbungB.png",priority:"core",display_context:"orbital",tags:["science","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Flammenf%C3%A4rbungB.png"}]},{kind:"Uses",title:"Thermal shock resistant borosilicate glass",text:"Practical application — Lab beaker made of borosilicate glass. The addition of boron trioxide (B₂O₃) drastically reduces the thermal expansion coefficient, providing superior thermal shock resistance. (borosilicate glass)",image:"images/elements/005_B/10_Schott_Duran_glassware.jpg",priority:"core",display_context:"orbital",tags:["uses","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Schott_Duran_glassware.jpg"}]},{kind:"Uses",title:"Ultralight rigid boron nitride aerogel on hair",text:"Practical application — Boron nitride aerogel is an ultralight, porous graphene-like material with a density close to air, exhibiting excellent thermal insulation and oxidation resistance. (advanced material)",image:"images/elements/005_B/06_BN_aerogel_on_hair.jpg",priority:"core",display_context:"orbital",tags:["uses","B","5"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:BN_aerogel_on_hair.jpg"}]},{kind:"History",title:"Boron discovery and nomenclature",text:"Historical record — Gay-Lussac and Thénard reported boron isolation from boric acid in 1808; the name derives from borax.",image:"images/elements/005_B/18_Joseph_Louis_Gay-Lussac.jpg",priority:"core",display_context:"orbital",tags:["history","B","5"],panel:{type:"timeline",items:[{year:"1808",title:"Gay-Lussac reduces boron with potassium",text:"French chemists Gay-Lussac and Thénard, and English chemist Davy, independently reduce molten boric acid with potassium to isolate boron powder.",image:"images/elements/005_B/18_Joseph_Louis_Gay-Lussac.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Boron emission spectrum (NIST ASD)",text:"Emission spectrum — The characteristic spectral lines of Boron (B), recorded by the NIST Atomic Spectra Database. Each line corresponds to a specific electron transition unique to B. These lines are used for spectroscopic identification and stellar abundance measurements. (NIST ASD)",image:"images/elements/005_B/24_5_(B_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","spectroscopy","b","5"],sources:[{label:"NIST Atomic Spectra Database",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:5_%28B_I%29_NIST_ASD_emission_spectrum.png"}]}],6:[{kind:"Portrait",title:"Glassy carbon and a 1 cm3 high-purity graphite cube",text:"Physical form — Glassy carbon (left), a highly disordered carbon allotrope, alongside a 1 cm3 high-purity graphite cube (right).",image:"images/elements/006_C/11_Glassy_carbon_and_a_1cm3_graphite_cube_HP68-79.jpg",priority:"standard",display_context:"orbital",tags:["portrait","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Glassy_carbon_and_a_1cm3_graphite_cube_HP68-79.jpg"}]},{kind:"Science",title:"Diamond and graphite carbon allotropes",text:"Physical form — Two allotropes of carbon: hard, transparent diamond with a tetrahedral network, and soft, conductive graphite with layered sheets.",image:"images/elements/006_C/01_Diamond_and_graphite2.jpg",priority:"core",display_context:"orbital",tags:["science","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Diamond_and_graphite2.jpg"}]},{kind:"Science",title:"Diamond and graphite specimens with scale",text:"Physical form — Diamond and graphite specimens displayed with a scale for physical and crystallographic study.",image:"images/elements/006_C/02_Diamond-and-graphite-with-scale.jpg",priority:"core",display_context:"orbital",tags:["science","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Diamond-and-graphite-with-scale.jpg"}]},{kind:"Origin",title:"Adirondack graphite skarn deposit, New York",text:"Natural occurrence — Graphite skarn rock from New York, containing flaky crystalline graphite formed by metamorphism of organic carbon.",image:"images/elements/006_C/03_Graphite-pyroxene-scapolite_skarn__Lead_Hill_Mines__Adirondack_Mountains__New_York_State__USA__3.jpg",priority:"standard",display_context:"orbital",tags:["origin","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Graphite-pyroxene-scapolite_skarn_(Lead_Hill_Mines,_Adirondack_Mountains,_New_York_State,_USA)_3.jpg"}]},{kind:"Origin",title:"Allende carbonaceous chondrite meteorite specimen",text:"Natural occurrence — Allende carbonaceous chondrite meteorite, containing presolar organic carbon and nanodiamonds.",image:"images/elements/006_C/06_Carbonaceous_chondrite__Allende_Meteorite___4.560-4.568_Ga__7__17383518955_.jpg",priority:"core",display_context:"orbital",tags:["origin","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Carbonaceous_chondrite__Allende_Meteorite___4.560-4.568_Ga__7__17383518955_.jpg"}]},{kind:"Origin",title:"Kimberlite rough diamond from Siberia",text:"Natural occurrence — Rough diamond crystal from Siberian kimberlite pipes, formed at high pressure in the mantle and brought to the surface.",image:"images/elements/006_C/07_Diamond_in_kimberlite__Mir_Kimberlite_Pipe__Malo-Botuoba_Kimberlite_Field___354-360_Ma__Mir_Diamond_Mine__Siberia__Russia___17440851983_.jpg",priority:"standard",display_context:"orbital",tags:["origin","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Diamond_in_kimberlite__Mir_Kimberlite_Pipe__Malo-Botuoba_Kimberlite_Field___354-360_Ma__Mir_Diamond_Mine__Siberia__Russia___17440851983_.jpg"}]},{kind:"Uses",title:"Lightweight carbon fiber clipless pedals",text:"Practical application — Carbon fiber reinforcement in high-precision structural components, offering extreme strength-to-weight ratios.",image:"images/elements/006_C/13_LOOK_Keo_Blade_Carbon_clipless_pedals.jpg",priority:"standard",display_context:"orbital",tags:["uses","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:LOOK_Keo_Blade_Carbon_clipless_pedals.jpg"}]},{kind:"Uses",title:"Industrial high-strength carbon fiber sheet",text:"Practical application — High-performance carbon fiber reinforced polymer composites used in aerospace, automotive, and sports equipment.",image:"images/elements/006_C/09_Carbon_fiber_woven_fabric.jpg",priority:"standard",display_context:"orbital",tags:["uses","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Carbon_fiber_woven_fabric.jpg"}]},{kind:"Safety",title:"Carbon monoxide inhalation toxicity warning",text:"[Safety Warning] Incomplete combustion of carbon produces carbon monoxide (CO), an odorless, tasteless, and non-irritating gas. CO binds to hemoglobin with affinity 200 times higher than oxygen, causing rapid asphyxiation.",image:"images/elements/006_C/05_GHS-pictogram-skull.svg",priority:"standard",display_context:"orbital",tags:["safety","C","6"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-skull.svg"}]},{kind:"Science",display_hint:"spectrum",title:"Carbon emission spectrum",text:"Emission spectrum — Spectral lines of Carbon (C) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/006_C/22_6_(C_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","c","6"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:6_%28C_I%29_NIST_ASD_emission_spectrum.png"}]}],7:[{kind:"Science",title:"Nitrogen discharge-tube observation",text:"Physical form — Nitrogen (N₂) is a colorless, odorless diatomic gas with an extremely strong triple bond (N≡N), making it chemically inert under standard conditions.",image:"images/elements/007_N/03_Nitrogen__7_N_.jpg",priority:"core",display_context:"orbital",tags:["science","N","7"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Nitrogen_(7_N).jpg"}]},{kind:"Portrait",title:"Nitrogen discharge tube violet-blue glow",text:"Physical form — Nitrogen gas discharge tube glowing with a violet-blue light under high voltage.",image:"images/elements/007_N/02_Nitrogen_discharge_tube.jpg",priority:"core",display_context:"orbital",tags:["portrait","N","7"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Nitrogen_discharge_tube.jpg"}]},{kind:"Safety",title:"Cryogenic liquid-nitrogen handling",text:"Physical form — Cryogenic liquid nitrogen (LN2) at -196°C, creating a thick white fog of condensed moisture as it is poured.",image:"images/elements/007_N/12_Fluessiger_Stickstoff.jpg",priority:"core",display_context:"orbital",tags:["safety","N","7"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Fluessiger_Stickstoff.jpg"}]},{kind:"Science",title:"Liquid nitrogen cryogenic physical state",text:"Physical state — Nitrogen condenses to a colorless liquid at −196 °C. The cryogenic sample shown here is a laboratory form of atmospheric nitrogen, not its natural setting.",image:"images/elements/007_N/01_Liquid_nitrogen.jpg",priority:"core",display_context:"orbital",tags:["science","N","7"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Liquid_nitrogen.jpg"}]},{kind:"Origin",title:"Nitrogen's atmospheric home",text:"Natural occurrence — Nitrogen (N₂) makes up 78.08% of Earth's atmosphere by volume. This view of Earth's layered atmosphere shows the vast natural reservoir from which nitrogen is obtained.",image:"images/elements/007_N/19_Earth_atmosphere_nitrogen_origin.jpg",priority:"standard",display_context:"orbital",tags:["origin","N","7"],sources:[{label:"NASA Earth Observatory · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hovering_on_the_Horizon_-_NASA_Earth_Observatory.jpg"}]},{kind:"Uses",title:"Haber-Bosch industrial ammonia synthesis process",text:"Practical application — The Haber-Bosch process synthesizes ammonia (NH₃) to manufacture fertilizers that support global agriculture.",image:"images/elements/007_N/09_Haber-Bosch.svg",priority:"standard",display_context:"orbital",tags:["uses","N","7"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Haber-Bosch.svg"}]},{kind:"Safety",title:"Asphyxiation hazards from compressed gas leaks",text:"[Safety Warning] Nitrogen is odorless and tasteless. In confined spaces, large leaks rapidly displace oxygen. Because humans lack physiological sensors to detect nitrogen, victims asphyxiate without warning.",image:"images/elements/007_N/07_Nitrogen_cylinder.jpg",priority:"standard",display_context:"orbital",tags:["safety","N","7"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Nitrogen_cylinder.jpg"}]},{kind:"History",title:"Nitrogen discovery and industrial application history",text:"Milestones of nitrogen: from Rutherford's noxious air to the Haber-Bosch process transforming agriculture.",image:"images/elements/007_N/22_Daniel_Rutherford_Wellcome_M0008095.jpg",priority:"core",display_context:"orbital",tags:["history","N","7"],panel:{type:"timeline",items:[{year:"1772",title:"Daniel Rutherford isolates 'noxious air'",text:"Scottish chemist Daniel Rutherford isolates nitrogen from air using candle and mouse experiments.",image:"images/elements/007_N/22_Daniel_Rutherford_Wellcome_M0008095.jpg"},{year:"1790",title:"Chaptal names the element Nitrogène",text:"French chemist Jean-Antoine Chaptal names nitrogen based on its presence in nitre.",image:"images/elements/007_N/20_Jean-Antoine_Chaptal.jpg"},{year:"1909",title:"Haber successfully synthesizes ammonia",text:"German chemist Fritz Haber first synthesizes ammonia from nitrogen and hydrogen in the laboratory, launching industrial nitrogen fixation.",image:"images/elements/007_N/21_Fritz_Haber_etching.jpg"}]},sources:[{label:"Wellcome Collection via Wikimedia Commons · Daniel Rutherford portrait (CC BY 4.0)",url:"https://commons.wikimedia.org/wiki/File:Portrait_of_Daniel_Rutherford_Wellcome_M0008095.jpg"},{label:"Cleveland Museum of Art · Jean-Antoine Chaptal portrait (CC0)",url:"https://commons.wikimedia.org/wiki/File:Clevelandart_1964.54.jpg"},{label:"Digital Public Library of America · Fritz Haber etching (public domain)",url:"https://commons.wikimedia.org/wiki/File:Autographed_etching_of_Fritz_Haber_-_DPLA_-_6e2889b98aad264ed25931f79c5dbad8.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Nitrogen emission spectrum",text:"Emission spectrum — Spectral lines of Nitrogen (N) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/007_N/15_7_(N_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","n","7"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:7_%28N_I%29_NIST_ASD_emission_spectrum.png"}]}],8:[{kind:"Portrait",title:"Pure oxygen gas discharge tube",text:"Physical form — Low-pressure pure oxygen gas glowing with a pale violet-pink light under an electric field, showing its atomic emission lines.",image:"images/elements/008_O/03_Oxygen_discharge_tube.jpg",priority:"core",display_context:"orbital",tags:["portrait","O","8"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Oxygen_discharge_tube.jpg"}]},{kind:"Origin",title:"Primary oxygen-containing mineral in Earth's crust: pure quartz",text:"Natural occurrence — Pure quartz crystal (SiO₂). Oxygen is the most abundant element in Earth's crust by mass (~46%), mostly bound in silicates.",image:"images/elements/008_O/09_Quartz__Tibet.jpg",priority:"standard",display_context:"orbital",tags:["origin","O","8"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Quartz,_Tibet.jpg"}]},{kind:"Origin",title:"Modern living stromatolites in Shark Bay, Australia",text:"Natural occurrence — Stromatolites formed by cyanobacteria. During the Great Oxidation Event, photosynthetic blue-green algae released free oxygen.",image:"images/elements/008_O/08_Stromatolites_in_Shark_Bay.jpg",priority:"core",display_context:"orbital",tags:["origin","O","8"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Stromatolites_in_Shark_Bay.jpg"}]},{kind:"Science",title:"Photosynthetic water-splitting oxygen release mechanism",text:"Biological mechanism — Photosynthesis in green plants and algae uses chlorophyll to split water and release oxygen, maintaining atmospheric levels at 21%.",image:"images/elements/008_O/04_Photosynthesis_en.svg",priority:"standard",display_context:"orbital",tags:["science","O","8"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Photosynthesis_en.svg"}]},{kind:"Uses",title:"Medical high-pressure oxygen cylinders and life support",text:"Practical application — Medical oxygen cylinders used for respiratory therapy, surgical anesthesia, and emergency resuscitation.",image:"images/elements/008_O/01_Medical_oxygen_cylinder.png",priority:"core",display_context:"orbital",tags:["uses","O","8"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Medical_oxygen_cylinder.jpg"}]},{kind:"Uses",title:"NASA liquid oxygen transport barge and rocket oxidizer",text:"Practical application — A liquid oxygen (LOX) barge at a launch test facility. Liquid oxygen serves as a high-density rocket oxidizer.",image:"images/elements/008_O/02_NASA_liquid_oxygen_barges_at_Stennis_Space_Center__77-123-8_.jpg",priority:"standard",display_context:"orbital",tags:["uses","O","8"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:NASA_liquid_oxygen_barges_at_Stennis_Space_Center_(77-123-8).jpg"}]},{kind:"Uses",title:"Pressure swing adsorption (PSA) oxygen generator principle",text:"Practical application — Pressure swing adsorption (PSA) oxygen generator separating high-purity oxygen from air using zeolite molecular sieves.",image:"images/elements/008_O/10_Operating_Principles_for_a_PSA_Oxygen_Generator.jpg",priority:"standard",display_context:"orbital",tags:["uses","O","8"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Operating_Principles_for_a_PSA_Oxygen_Generator.jpg"}]},{kind:"Safety",title:"Apollo 14 command-service-module oxygen-tank redesign",text:"Safety engineering — NASA's annotated Apollo 14 command-service-module oxygen-tank redesign documents post-Apollo 13 changes, including removal of heater circuits and rerouting wiring. It is an engineering safety record, not a photograph of the Apollo 1 fire.",image:"images/elements/008_O/07_Apollo_14_redesigned_oxygen_tank__S71-16745_.jpg",priority:"standard",display_context:"orbital",tags:["safety","O","8"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Apollo_14_redesigned_oxygen_tank_(S71-16745).jpg"}]},{kind:"History",title:"Oxygen discovery history",text:"The experimental discovery, publication, and naming of oxygen through the work of Scheele, Priestley, and Lavoisier.",image:"images/elements/008_O/18_Carl_Wilhelm_Scheele_portrait.png",priority:"core",display_context:"orbital",tags:["history","O","8"],panel:{type:"timeline",items:[{year:"1771",title:"Scheele discovers fire air",text:"Swedish chemist Scheele prepares pure oxygen by heating nitrates and manganese dioxide, though publication was delayed until 1777.",image:"images/elements/008_O/18_Carl_Wilhelm_Scheele_portrait.png"},{year:"1774",title:"Priestley independently discovers oxygen",text:"English chemist Joseph Priestley isolates oxygen by heating mercuric oxide and publishes his findings.",image:"images/elements/008_O/19_Joseph_Priestley_portrait.jpg"}]},sources:[{label:"Carl Wilhelm Scheele portrait · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Carl_Wilhelm_Scheele_by_Johann_Gottfried_Scheffner.png"},{label:"Joseph Priestley portrait · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Joseph_Priestley_(NPG).jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Oxygen emission spectrum",text:"Emission spectrum — Spectral lines of Oxygen (O) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/008_O/16_8_(O_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","o","8"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:8_%28O_I%29_NIST_ASD_emission_spectrum.png"}]}],9:[{kind:"Portrait",title:"Liquid fluorine at −196 °C",text:"Physical form — Pale-yellow liquid fluorine (F₂) held in a sealed ampoule at −196 °C. This is below fluorine’s −188 °C boiling point; at room temperature it is a highly toxic, reactive diatomic gas.",image:"images/elements/009_F/19_Liquid_fluorine_196C.jpg",priority:"core",display_context:"orbital",tags:["portrait","F","9"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Fluoro_liquido_a_-196%C2%B0C_1.jpg"}]},{kind:"Origin",title:"Natural cubic purple fluorite crystal",text:"Physical form — A classic cubic purple fluorite crystal (CaF2), the main fluoride mineral found in nature.",image:"images/elements/009_F/06_Fluorite-209416.jpg",priority:"standard",display_context:"orbital",tags:["origin","F","9"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Fluorite-209416.jpg"}]},{kind:"Origin",title:"Bicolor fluorite specimen from Pierre-Perthuis",text:"Natural occurrence — Bicolor fluorite crystals from hydrothermal veins in Pierre-Perthuis, France.",image:"images/elements/009_F/11_Fluorine_Peyrebrun.jpg",priority:"standard",display_context:"orbital",tags:["origin","F","9"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Fluorine_Peyrebrun.jpg"}]},{kind:"Origin",title:"Daylight fluorescent green fluorite from Rogerley Mine",text:"Natural occurrence — Green fluorite from Rogerley Mine, UK, exhibiting intense blue fluorescence under sunlight due to rare-earth impurities.",image:"images/elements/009_F/07_Fluorite__Rogerley_Mine__Rogerley_Quarry__Stanhope__Weardale__North_Pennines__County_Durham__England__1.jpg",priority:"standard",display_context:"orbital",tags:["origin","F","9"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Fluorite__Rogerley_Mine__Rogerley_Quarry__Stanhope__Weardale__North_Pennines__County_Durham__England__1.jpg"}]},{kind:"Uses",title:"Hexafluorouranium (UF6) for nuclear fuel enrichment",text:"Practical application — Uranium hexafluoride (UF₆) gas used for uranium-235 enrichment. Fluorine's single isotope F-19 ensures mass differences depend solely on uranium isotopes.",image:"images/elements/009_F/10_Uranium_hexafluoride_cylinder.jpg",priority:"standard",display_context:"orbital",tags:["uses","F","9"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Uranium_hexafluoride_cylinder.jpg"}]},{kind:"Safety",title:"GHS corrosive-hazard symbol for fluorine handling",text:"[Safety Warning] Elemental fluorine is an exceptionally reactive, toxic oxidizing gas. This GHS corrosive-hazard symbol is used here because no verified safety photograph is available; it is not a photograph of a fluorine incident.",image:"images/elements/009_F/05_GHS-pictogram-acid.svg",priority:"standard",display_context:"orbital",tags:["safety","F","9"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-acid.svg"}]},{kind:"History",title:"Fluorine isolation and discovery history",text:"The conquest of fluorine: from early mineral fluxes to poisoned pioneer chemists, ending with Moissan's successful electrolysis.",image:"images/elements/009_F/08_Henri_Moissan.jpg",priority:"core",display_context:"orbital",tags:["history","F","9"],panel:{type:"timeline",items:[{year:"1529",title:"Agricola records fluorite's flux properties",text:"German mineralogist Georgius Agricola records fluorite's ability to lower ore melting points, laying the foundation for naming fluorine.",image:"images/elements/009_F/17_Georgius_Agricola_Wellcome.jpg"},{year:"1886",title:"Moissan successfully isolates fluorine gas via low-temperature electrolysis",text:"French chemist Henri Moissan, after many failures and poisonings, successfully isolates fluorine gas using low-temperature platinum electrolysis, winning the 1906 Nobel Prize.",image:"images/elements/009_F/08_Henri_Moissan.jpg"}]},sources:[{label:"Wellcome Collection via Wikimedia Commons — Georgius Agricola woodcut",url:"https://commons.wikimedia.org/wiki/File:Georgius_Agricola._Reproduction_of_woodcut._Wellcome_V0000051.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Fluorine emission spectrum",text:"Emission spectrum — Spectral lines of Fluorine (F) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/009_F/16_9_(F_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","f","9"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:9_%28F_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Fluorine-gas reaction apparatus",text:"Experimental apparatus — A purpose-built fume-hood rig for reactions with elemental fluorine gas. The enclosed cylinder at left supplies fluorine; nickel or Monel piping, remotely operated controls, and the sealed reaction train make its exceptional reactivity manageable.",image:"images/elements/009_F/18_Fluorine_gas_reaction_apparatus.jpg",priority:"standard",display_context:"orbital",tags:["science","experiment","fluorine","9"],sources:[{label:"Wikimedia Commons — Laboratory apparatus for reactions with fluorine gas",url:"https://commons.wikimedia.org/wiki/File:Laboratory_apparatus_for_reactions_with_fluorine_gas.jpg"}]}],10:[{kind:"Portrait",title:"Neon gas discharge tube orange glow",text:"Physical state — A neon gas discharge tube glowing with a brilliant, intense reddish-orange light under high voltage, representing the classic emission of neon gas.",image:"images/elements/010_Ne/08_Neon_discharge_tube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ne","10"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Neon_discharge_tube.jpg"}]},{kind:"Uses",title:"Neon sign tube",text:"Practical application — A neon sign tube uses an electric discharge through neon gas to produce its characteristic orange-red light.",image:"images/elements/010_Ne/12_Neon.JPG",priority:"standard",display_context:"orbital",tags:["uses","Ne","10"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Neon.JPG"}]},{kind:"Science",title:"Neon-containing boron-cyanide cage model",text:"Scientific structure — A model of a reported neon-containing boron-cyanide cage. Such specialized structures illustrate the unusual conditions required to bind an otherwise very inert noble gas.",image:"images/elements/010_Ne/11_Neon_undecaciano_dodecaborato.jpg",priority:"standard",display_context:"orbital",tags:["science","Ne","10"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Neon_undecaciano_dodecaborato.jpg"}]},{kind:"Uses",title:"Commercial neon signs in the city",text:"Practical application — Vibrant commercial neon signs lighting up a city street at night. Neon's bright red-orange discharge is highly visible even through fog and rain.",image:"images/elements/010_Ne/01_24_Hour_Service_Neon_Sign__14794096853_.jpg",priority:"core",display_context:"orbital",tags:["uses","Ne","10"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:NEON_(2535574361).jpg"}]},{kind:"Uses",title:"Helium-neon (He-Ne) gas laser tube",text:"Practical application — A helium-neon gas laser emitting a highly coherent, monochromatic red laser beam at 632.8 nm, widely used in optical measurements and alignment.",image:"images/elements/010_Ne/02_Helium-neon_laser.jpg",priority:"core",display_context:"orbital",tags:["uses","Ne","10"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Helium-neon_laser.jpg"}]},{kind:"Safety",title:"Compressed-gas cylinder hazard symbol",text:"Safety symbol — This GHS gas-cylinder pictogram is not an incident photograph. Neon is non-flammable and inert, but its pressurized cylinders require mechanical safety controls and a large release in an enclosed space can displace oxygen.",image:"images/elements/010_Ne/06_GHS-pictogram-bottle.svg",priority:"standard",display_context:"orbital",tags:["safety","Ne","10"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-bottle.svg"}]},{kind:"History",title:"Neon discovery and noble gas history",text:"Historical records — Discovered by William Ramsay and Morris Travers in 1898, then developed into practical neon lighting by Georges Claude in 1910.",image:"images/elements/010_Ne/07_Portrait_of_William_Ramsay_-_DPLA_-_3ecf87c8b4c37c0d2afb5bd0c6b0d206.jpg",priority:"core",display_context:"orbital",tags:["history","Ne","10"],panel:{type:"timeline",items:[{year:"1898",title:"Ramsay and Travers discover neon gas",text:"British chemists Ramsay and Travers evaporate liquid air and capture a new gas that glows bright orange-red, naming it 'neon' (new).",image:"images/elements/010_Ne/07_Portrait_of_William_Ramsay_-_DPLA_-_3ecf87c8b4c37c0d2afb5bd0c6b0d206.jpg"},{year:"1910",title:"Georges Claude displays first neon tube",text:"French inventor Georges Claude builds the first practical neon discharge tube using byproduct neon from liquid-air fractionation. This 1926 photograph shows Claude with experimental apparatus; it is not a 1910 event photograph.",image:"images/elements/010_Ne/16_Georges_Claude_at_the_Institut_1926.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Portrait_of_William_Ramsay_-_DPLA_-_3ecf87c8b4c37c0d2afb5bd0c6b0d206.jpg"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Georges_Claude_%C3%A0_l%27Institut_1926.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Neon emission spectrum",text:"Emission spectrum — Spectral lines of Neon (Ne) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/010_Ne/15_10_(Ne_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ne","10"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:10_%28Ne_I%29_NIST_ASD_emission_spectrum.png"}]}],11:[{kind:"Portrait",title:"Sodium metal floating in mineral oil",text:"Physical form — Sodium is a highly reactive, soft alkali metal. A freshly cut surface shows a bright silvery luster, but it quickly oxidizes and floats on mineral oil due to its low density (0.968 g/cm³). (metal)",image:"images/elements/011_Na/02_Sodium__11_Na_.jpg",priority:"core",display_context:"orbital",tags:["portrait","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sodium_(11_Na).jpg"}]},{kind:"Science",title:"Microscopic sodium chloride cubic crystals",text:"Microscopic morphology — Scanning electron micrograph of sodium chloride (table salt) crystals, showing their perfect cubic lattice structure. (compound crystals)",image:"images/elements/011_Na/07_Sodium_chloride_crystals.jpg",priority:"standard",display_context:"orbital",tags:["science","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sodium_chloride_crystals.jpg"}]},{kind:"Uses",title:"Sodium hydroxide pellets",text:"Physical form — Translucent white pellets of sodium hydroxide (caustic soda), which are highly hygroscopic and readily deliquesce in air. (hydroxide pellets)",image:"images/elements/011_Na/08_Sodium_hydroxide_pellets.jpg",priority:"standard",display_context:"orbital",tags:["uses","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sodium_hydroxide_pellets.jpg"}]},{kind:"Origin",title:"Natural halite (rock salt) mineral specimen",text:"Mineral source — Halite (natural sodium chloride crystals), the most important geological source mineral for sodium and chlorine extraction. (mineral)",image:"images/elements/011_Na/05_Halite-249324.jpg",priority:"standard",display_context:"orbital",tags:["origin","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Halite.jpg"}]},{kind:"Origin",title:"Natural thenardite (sodium sulfate) mineral",text:"Mineral source — Thenardite (anhydrous sodium sulfate mineral), serving as a significant geological source for sodium compound manufacture. (mineral)",image:"images/elements/011_Na/11_Thenardite_Sodium_sulfate_near_Sodaville_Mineral_County_Nevada.jpg",priority:"standard",display_context:"orbital",tags:["origin","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Thenardite_Sodium_sulfate_near_Sodaville_Mineral_County_Nevada.jpg"}]},{kind:"Science",title:"Characteristic yellow flame test of sodium",text:"Flame test — Sodium ions heated in a flame produce an intense, characteristic bright yellow emission due to atomic D-line transitions. (flame test)",image:"images/elements/011_Na/01_Sodium_flame_reaction.JPG",priority:"core",display_context:"orbital",tags:["science","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sodium_flame_reaction.JPG"}]},{kind:"Life",title:"Active transport by sodium-potassium pump",text:"Biological role — Diagram of the Na+/K+-ATPase pump. Using ATP energy, this membrane protein pumps sodium out and potassium into cells to maintain resting potentials. (ion pump)",image:"images/elements/011_Na/06_Scheme_sodium-potassium_pump-en.svg",priority:"standard",display_context:"orbital",tags:["life","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Scheme_sodium-potassium_pump-en.svg"}]},{kind:"Uses",title:"Low-pressure sodium street lamp glow",text:"Practical application — Low-pressure sodium street lamps emitting a monochromatic yellow glow, valued for their high luminous efficiency and superior fog penetration. (lamps)",image:"images/elements/011_Na/03_Low_pressure_sodium_lamp.jpg",priority:"core",display_context:"orbital",tags:["uses","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Low_pressure_sodium_lamp.jpg"}]},{kind:"Safety",title:"Vigorous reaction of sodium metal with water",text:"[Safety Warning] Sodium metal reacts violently with water, releasing flammable hydrogen gas and forming highly corrosive sodium hydroxide. The heat of reaction can ignite the hydrogen, causing explosions. It must be stored under mineral oil. Dry sand or class D extinguishers must be used for fires; water or CO₂ is strictly prohibited. (reaction hazard)",image:"images/elements/011_Na/10_Sodium_in_water.jpg",priority:"core",display_context:"orbital",tags:["safety","Na","11"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sodium_in_water.jpg"}]},{kind:"History",title:"Sodium discovery and electrolysis archives",text:"Historical records — Humphry Davy first isolated sodium by electrolyzing molten sodium hydroxide in 1807, subsequently naming the element 'sodium'. (history)",image:"images/elements/011_Na/09_Humphry_Davy_by_Turner_crop.jpg",priority:"core",display_context:"orbital",tags:["history","Na","11"],panel:{type:"timeline",items:[{year:"1807",title:"Davy isolates metallic sodium via electrolysis",text:"English chemist Humphry Davy electrolyzes molten sodium hydroxide, isolating metallic sodium for the first time.",image:"images/elements/011_Na/09_Humphry_Davy_by_Turner_crop.jpg"},{year:"1861",title:"Solvay process invented",text:"Ernest Solvay invents the Solvay process using brine and limestone to manufacture sodium carbonate efficiently at scale.",image:"images/elements/011_Na/20_Ernest_Solvay.jpg"}]},sources:[{label:"Wikimedia Commons · Humphry Davy portrait",url:"https://commons.wikimedia.org/wiki/File:Humphry_Davy_by_Turner_crop.jpg"},{label:"Wikimedia Commons · Ernest Solvay portrait (public domain)",url:"https://commons.wikimedia.org/wiki/File:Ernest_Solvay.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Sodium emission spectrum",text:"Emission spectrum — Spectral lines of Sodium (Na) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/011_Na/18_11_(Na_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","na","11"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:11_%28Na_I%29_NIST_ASD_emission_spectrum.png"}]}],12:[{kind:"Portrait",title:"High-purity metallic magnesium block",text:"Physical form — Magnesium is a lightweight, silvery-white alkaline earth metal. It is relatively soft and forms a dull oxide passivating film in air. (element overview)",image:"images/elements/012_Mg/03_Magnesium__Mg_.jpg",priority:"core",display_context:"orbital",tags:["portrait","Mg","12"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Magnesium_(Mg).jpg"}]},{kind:"Uses",title:"Epsom salt (magnesium sulfate heptahydrate)",text:"Physical form — Translucent crystals of magnesium sulfate heptahydrate (Epsom salt), widely used in medicine, agriculture, and cosmetic baths. (sulfate crystals)",image:"images/elements/012_Mg/07_Magnesium_sulfate_crystals.jpg",priority:"standard",display_context:"orbital",tags:["uses","Mg","12"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Magnesium_sulfate_crystals.jpg"}]},{kind:"Uses",title:"Magnesium glycinate dietary supplement",text:"Physical form — Magnesium glycinate capsules, a bioavailable dietary supplement used to support muscle function and nervous system health. (compound)",image:"images/elements/012_Mg/12_Magnesium_glycinate_supplement_Australia.jpg",priority:"standard",display_context:"orbital",tags:["uses","Mg","12"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Magnesium_glycinate_supplement_Australia.jpg"}]},{kind:"Origin",title:"Natural dolostone rock specimen",text:"Mineral source — Dolostone, a sedimentary carbonate rock rich in calcium-magnesium carbonate, acting as a major geological reservoir of magnesium. (dolostone)",image:"images/elements/012_Mg/09_Dolostone__Paleozoic__Ohio__USA_.jpg",priority:"standard",display_context:"orbital",tags:["origin","Mg","12"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Dolostone_(Paleozoic,_Ohio,_USA).jpg"}]},{kind:"Science",title:"Vigorous combustion of magnesium ribbon",text:"Flame test — A magnesium ribbon burning intensely in air, emitting a brilliant, blinding white light and generating white magnesium oxide ash. (combustion)",image:"images/elements/012_Mg/02_Magnesium_ribbon_burning.jpg",priority:"core",display_context:"orbital",tags:["science","Mg","12"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Magnesium_ribbon_burning.jpg"}]},{kind:"Safety",title:"Flammability hazard symbol for magnesium powder or ribbon",text:"Safety symbol — This GHS flame pictogram is not an incident photograph. Fine magnesium, filings, and ribbon can burn intensely; burning magnesium requires suitable Class D media rather than water or carbon-dioxide extinguishers.",image:"images/elements/012_Mg/06_GHS-pictogram-flamme.svg",priority:"core",display_context:"orbital",tags:["safety","Mg","12"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"History",title:"Magnesium discovery and isolation history",text:"Historical records — Joseph Black recognized magnesium as a unique element in 1755, and Humphry Davy isolated the impure metal via electrolysis in 1808. (history)",image:"images/elements/012_Mg/14_Joseph_Black.jpg",priority:"core",display_context:"orbital",tags:["history","Mg","12"],panel:{type:"timeline",items:[{year:"1755",title:"Joseph Black identifies magnesium oxide",text:"Scottish chemist Joseph Black distinguishes magnesia from lime, confirming magnesium as a new element.",image:"images/elements/012_Mg/14_Joseph_Black.jpg"},{year:"1808",title:"Davy isolates metallic magnesium via electrolysis",text:"Humphry Davy uses electrolysis to obtain magnesium amalgam, distilling it to isolate pure metallic magnesium.",image:"images/elements/012_Mg/18_Humphry_Davy_Wellcome_M0004638.jpg"}]},sources:[{label:"Wellcome Collection via Wikimedia Commons · Humphry Davy portrait (CC BY 4.0)",url:"https://commons.wikimedia.org/wiki/File:Portrait_of_Sir_Humphry_Davy,_1st_Baronet,_FRS_(1778_%E2%80%93_1829),_Wellcome_M0004638.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Magnesium emission spectrum",text:"Emission spectrum — Spectral lines of Magnesium (Mg) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/012_Mg/17_12_(Mg_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","mg","12"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:12_%28Mg_I%29_NIST_ASD_emission_spectrum.png"}]}],13:[{kind:"Portrait",title:"High-purity acid-etched aluminium sample",text:"Physical form — Acid-etched high-purity aluminium sheet, showing its characteristic grain boundaries. Aluminium is the most abundant metal in the crust. (etched)",image:"images/elements/013_Al/03_Aluminium_etched.jpg",priority:"core",display_context:"orbital",tags:["portrait","Al","13"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Aluminium_etched.jpg"}]},{kind:"Origin",title:"Rare aluminium-bearing Dellagiustaite mineral",text:"Natural occurrence — Dellagiustaite is a rare, aluminium-bearing mineral. This specimen provides a documented mineral context for aluminium rather than a generic rock image.",image:"images/elements/013_Al/10_Dellagiustaite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Al","13"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Dellagiustaite.jpg"}]},{kind:"Science",title:"Highly exothermic thermite reaction",text:"Chemical properties — The thermite reaction, where aluminium powder reduces iron oxide at high temperatures, producing molten iron and releasing heat exceeding 2500°C. (thermite reaction)",image:"images/elements/013_Al/09_ThermiteReaction.jpg",priority:"core",display_context:"orbital",tags:["science","Al","13"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:ThermiteReaction.jpg"}]},{kind:"Science",title:"Bohr model of aluminium atomic structure",text:"Scientific structure — Bohr atomic model and electron configuration (2, 8, 3) of aluminium, demonstrating its three valence electrons. (atomic structure)",image:"images/elements/013_Al/05_Electron_shell_013_Aluminium.svg",priority:"standard",display_context:"orbital",tags:["science","Al","13"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Electron_shell_013_Aluminium.svg"}]},{kind:"Uses",title:"High-strength aluminium alloy boat hull",text:"Practical application — Lightweight patrol vessel constructed from high-strength marine-grade aluminium alloy, valued for its low density and corrosion resistance in seawater. (transport)",image:"images/elements/013_Al/01_Bangladesh_Coast_Guard_Harbor_Patrol_Boats.__30233829981_.jpg",priority:"core",display_context:"orbital",tags:["uses","Al","13"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Bangladesh_Coast_Guard_Harbor_Patrol_Boats._(30233829981).jpg"}]},{kind:"Safety",title:"Flammability hazard symbol for fine aluminium",text:"Safety symbol — This GHS flame pictogram is not an incident photograph. Fine aluminium powder can present a fire or dust-explosion hazard; it does not describe the behaviour of a solid aluminium block.",image:"images/elements/013_Al/06_GHS-pictogram-flamme.svg",priority:"core",display_context:"orbital",tags:["safety","Al","13"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"Science",display_hint:"spectrum",title:"Aluminium emission spectrum",text:"Emission spectrum — Spectral lines of Aluminium (Al) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/013_Al/16_13_(Al_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","al","13"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:13_%28Al_I%29_NIST_ASD_emission_spectrum.png"}]}],14:[{kind:"Portrait",title:"High-purity polycrystalline silicon lump",text:"Physical form — A high-purity polycrystalline silicon lump. Silicon is a hard, brittle, blue-grey metalloid with a metallic luster, serving as the foundation of modern semiconductor technology. (element overview)",image:"images/elements/014_Si/02_Silicon__14_Si_.jpg",priority:"core",display_context:"orbital",tags:["portrait","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Silicon_(14_Si).jpg"}]},{kind:"Science",title:"Silicon diamond-cubic crystal lattice",text:"Scientific structure — Atomic model of silicon's diamond cubic crystal structure, where each silicon atom is tetrahedrally bonded to four neighbors. (compound)",image:"images/elements/014_Si/11_Crystal_structure_of_Silicon_Material.png",priority:"standard",display_context:"orbital",tags:["science","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Crystal_structure_of_Silicon_Material.png"}]},{kind:"Origin",title:"Natural pink rose quartz specimen",text:"Natural occurrence — Pink rose quartz, a crystalline variety of silicon dioxide (SiO₂) colored by trace manganese/titanium impurities, representing a common silicious mineral. (quartz alternate)",image:"images/elements/014_Si/04_Rose_quartz__32132819430_.jpg",priority:"standard",display_context:"orbital",tags:["origin","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Rose_quartz_(32132819430).jpg"}]},{kind:"Origin",title:"Natural purple amethyst geode specimen",text:"Natural occurrence — A natural amethyst specimen. Amethyst is a purple variety of quartz (SiO₂), crystallized in the trigonal system, colored by trace iron impurities. (amethyst)",image:"images/elements/014_Si/06_Amethyst__purple_quartz__3__32635320292_.jpg",priority:"standard",display_context:"orbital",tags:["origin","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Amethyst_(purple_quartz)_3_(32635320292).jpg"}]},{kind:"Origin",title:"Crystalline sillenite mineral specimen",text:"Natural occurrence — Sillenite mineral crystal, a naturally occurring bismuth silicate mineral showing resinous luster. (mineral)",image:"images/elements/014_Si/10_Sillenite-Bismuth-107521.jpg",priority:"standard",display_context:"orbital",tags:["origin","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sillenite-Bismuth-107521.jpg"}]},{kind:"Science",title:"Diatom silica cell wall micrograph",text:"Biological role — High-power light micrograph of marine diatoms, which synthesize intricate, glass-like cell walls (frustules) from dissolved silicic acid. (diatoms)",image:"images/elements/014_Si/05_Diatoms_through_the_microscope.jpg",priority:"standard",display_context:"orbital",tags:["science","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Diatoms_through_the_microscope.jpg"}]},{kind:"Uses",title:"Molten silicate glass blowing craft",text:"Practical application — Hot glass blowing process. Silicate glass (SiO₂) is heated to high temperatures to shape highly chemical-resistant laboratory and household glassware. (glass)",image:"images/elements/014_Si/01_Glassblowing.jpg",priority:"core",display_context:"orbital",tags:["uses","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Glassblowing.jpg"}]},{kind:"Uses",title:"Monocrystalline silicon solar cell array",text:"Practical application — Monocrystalline silicon solar panels, which convert solar energy into electricity utilizing the photovoltaic effect across p-n junctions. (solar)",image:"images/elements/014_Si/03_Solar_cell.png",priority:"core",display_context:"orbital",tags:["uses","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Solar_cell.png"}]},{kind:"Uses",title:"High-purity silicon wafer in cleanroom",text:"Practical application — High-purity monocrystalline silicon wafers in a cleanroom, serving as substrates for microchip fabrication. (chips)",image:"images/elements/014_Si/09_Silicon_wafers.jpg",priority:"standard",display_context:"orbital",tags:["uses","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Silicon_wafers.jpg"}]},{kind:"Safety",title:"GHS health hazard warning symbol",text:"[Safety Warning] Elemental silicon is non-toxic. However, chronic inhalation of fine crystalline silica dust (quartz dust) causes silicosis, an irreversible and fatal occupational lung disease. Wet-cutting and dust masks are mandatory. (silica dust)",image:"images/elements/014_Si/07_GHS-pictogram-silhouette.svg",priority:"core",display_context:"orbital",tags:["safety","Si","14"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-silhouette.svg"}]},{kind:"History",title:"Silicon discovery and semiconductor era",text:"Historical records — Jöns Jacob Berzelius first isolated amorphous silicon in 1823, laying the foundation for the silicon semiconductor age. (history)",image:"images/elements/014_Si/08_Jöns_Jacob_Berzelius.jpg",priority:"core",display_context:"orbital",tags:["history","Si","14"],panel:{type:"timeline",items:[{year:"1823",title:"Jöns Jacob Berzelius isolates silicon",text:"Swedish chemist Berzelius reduces silicon tetrafluoride with potassium, isolating amorphous silicon as a new element.",image:"images/elements/014_Si/08_Jöns_Jacob_Berzelius.jpg"},{year:"1947",title:"Bell Labs invents the transistor",text:"John Bardeen, Walter Brattain, and William Shockley invent the point-contact transistor at Bell Labs, which soon shifted from germanium to silicon.",image:"images/elements/014_Si/20_First_transistor_Bell_Labs.jpg"},{year:"1954",title:"First practical silicon solar cell developed",text:"Bell Labs scientists develop the first practical silicon solar cell with 6% efficiency, initiating commercial photovoltaic technology.",image:"images/elements/014_Si/21_Bell_Labs_solar_cell_1954.jpg"}]},sources:[{label:"Wikimedia Commons · Jöns Jacob Berzelius portrait",url:"https://commons.wikimedia.org/wiki/File:J%C3%B6ns_Jacob_Berzelius.jpg"},{label:"Wikimedia Commons · first Bell Labs transistor (CC BY 2.0)",url:"https://commons.wikimedia.org/wiki/File:The_First_Transistor_ever_made,_built_in_1947_-_Bell_Labs.jpg"},{label:"Wikimedia Commons · first Bell Labs solar module, 1954 (public domain)",url:"https://commons.wikimedia.org/wiki/File:SolarModul_1954.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Silicon emission spectrum",text:"Emission spectrum — Spectral lines of Silicon (Si) from the NIST Atomic Spectra Database.",image:"images/elements/014_Si/19_14_(Si_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","si","14"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],15:[{kind:"Portrait",title:"High-purity red-violet crystalline phosphorus",text:"Physical form — High-purity red-violet crystalline phosphorus obtained by vacuum sublimation, which is significantly more stable than white phosphorus. (element overview)",image:"images/elements/015_P/08_Phosphorus__15_P_.jpg",priority:"core",display_context:"orbital",tags:["portrait","P","15"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Phosphorus_(15_P).jpg"}]},{kind:"Safety",title:"White phosphorus stored under water",text:"Physical form — White phosphorus, a waxy yellow solid allotrope that is highly toxic and pyrophoric, requiring storage under water to prevent spontaneous ignition. (white phosphorus)",image:"images/elements/015_P/04_White_phosphorus.jpg",priority:"standard",display_context:"orbital",tags:["safety","P","15"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:White_phosphorus.jpg"}]},{kind:"Life",title:"Chemical structure of cellular ATP currency",text:"Biological role — Molecular skeleton of Adenosine Triphosphate (ATP). The hydrolysis of high-energy phosphate bonds serves as the universal energy currency in living cells. (ATP)",image:"images/elements/015_P/01_ATP-2D-skeletal.png",priority:"core",display_context:"orbital",tags:["life","P","15"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:ATP-2D-skeletal.svg"}]},{kind:"Life",title:"Phosphate backbone of DNA double helix",text:"Biological role — The deoxyribose-phosphate backbone of the DNA double helix, providing structural stability and negative charge to genetic material. (DNA backbone)",image:"images/elements/015_P/05_DNA_chemical_structure.svg",priority:"standard",display_context:"orbital",tags:["life","P","15"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:DNA_chemical_structure.svg"}]},{kind:"Safety",title:"GHS flammable chemical warning symbol",text:"[Safety Warning] White phosphorus is highly toxic (lethal dose ~15 mg) and pyrophoric, igniting spontaneously at 34°C to cause deep, painful chemical burns. Red phosphorus is stable but explosive when mixed with oxidizers. Combustion releases toxic, corrosive phosphorus pentoxide (P₂O₅) smoke. (white phosphorus fire)",image:"images/elements/015_P/06_GHS-pictogram-flamme.svg",priority:"core",display_context:"orbital",tags:["safety","P","15"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"History",title:"Phosphorus discovery and match industry",text:"Historical records — Hennig Brand discovered phosphorus by distilling urine in 1669, naming it after the Greek word for 'light-bearer' due to its glow. (history)",image:"images/elements/015_P/07_Hennig_Brand.jpg",priority:"core",display_context:"orbital",tags:["history","P","15"],panel:{type:"timeline",items:[{year:"1669",title:"Hennig Brand discovers phosphorus",text:"German alchemist Hennig Brand distills concentrated urine in search of the Philosopher\\'s Stone, accidentally obtaining a white waxy substance that glows in the dark.",image:"images/elements/015_P/07_Hennig_Brand.jpg"}]},sources:[{label:"Hennig Brand portrait — Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hennig_Brand.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Phosphorus emission spectrum",text:"Emission spectrum — Spectral lines of Phosphorus (P) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/015_P/16_15_(P_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","p","15"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:15_%28P_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Red phosphorus allotrope reference sample",text:"Allotropy — A reference sample of red phosphorus, a polymeric phosphorus allotrope that is much less reactive than molecular white phosphorus. The image documents the material itself, not a match or other consumer product.",image:"images/elements/015_P/09_Red_phosphorus.jpg",priority:"standard",display_context:"orbital",tags:["science","allotrope","P","15"],sources:[{label:"Wikimedia Commons — Red phosphorus",url:"https://commons.wikimedia.org/wiki/File:Red_phosphorus.jpg"}]}],16:[{kind:"Portrait",title:"Crystalline native sulfur specimen",text:"Physical state — A magnificent block of bright yellow, crystalline native sulfur. As a nonmetal, solid sulfur forms cyclic octatomic (S₈) molecules, exhibiting a resinous luster, low density, and extreme brittleness. (crystalline sulfur)",image:"images/elements/016_S/02_Sulfur__16_S_.jpg",priority:"core",display_context:"orbital",tags:["portrait","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sulfur_(16_S).jpg"}]},{kind:"Origin",title:"Pyrite crystal",text:"Natural occurrence — Pyrite (iron disulfide, FeS₂), commonly known as fool's gold, is a major natural sulfide mineral and an important source of sulfur. (sulfide mineral)",image:"images/elements/016_S/07_Pyrite__18858891699_.jpg",priority:"standard",display_context:"orbital",tags:["origin","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Pyrite_(18858891699).jpg"}]},{kind:"Origin",title:"Native sulfur from El Desierto mine",text:"Natural occurrence — High-purity native sulfur crystal specimen from the famous El Desierto mine in Potosí, Bolivia. Sulfur occurs naturally in volcanic regions, hot springs, and as massive underground deposits. (mineral)",image:"images/elements/016_S/09_Sulfur_-_El_Desierto_mine__San_Pablo_de_Napa__Daniel_Campos_Province__Potosí__Bolivia.jpg",priority:"standard",display_context:"orbital",tags:["origin","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sulfur_-_El_Desierto_mine,_San_Pablo_de_Napa,_Daniel_Campos_Province,_Potos%C3%AD,_Bolivia.jpg"}]},{kind:"Science",title:"Monoclinic sulfur crystals",text:"Allotropes — Needle-like monoclinic sulfur (beta-sulfur) crystals growing slowly from cooling molten sulfur. This demonstrates sulfur's complex allotropy, transitioning from stable orthorhombic alpha-sulfur to beta-sulfur. (allotropic crystals)",image:"images/elements/016_S/10_Crystals_growing_from_melted_sulfur.jpg",priority:"core",display_context:"orbital",tags:["science","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Crystals_growing_from_melted_sulfur.jpg"}]},{kind:"Life",title:"Cysteine structure",text:"Biological role — L-Cysteine is a sulfur-containing amino acid. The sulfur-to-sulfur covalent bonds (disulfide bridges) in cysteine are crucial for stabilizing the tertiary structures of proteins, such as keratin in hair. (amino acids)",image:"images/elements/016_S/01_L-Cysteine-skeletal.png",priority:"core",display_context:"orbital",tags:["life","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:L-Cysteine-skeletal.svg"}]},{kind:"Uses",title:"Sulfuric acid",text:"Industrial application — Concentrated sulfuric acid (H₂SO₄), the world's most widely manufactured chemical. It serves as a primary benchmark of a nation's industrial strength, used in fertilizers, refining, and synthesis. (sulfuric acid)",image:"images/elements/016_S/03_Sulfuric_acid_96_percent_extra_pure.jpg",priority:"core",display_context:"orbital",tags:["uses","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sulfuric_acid_96_percent_extra_pure.jpg"}]},{kind:"Uses",title:"Vulcanized rubber",text:"Practical application — Vulcanized rubber tire section. The vulcanization process cross-links rubber polymer chains with sulfur atoms, greatly increasing structural durability, elasticity, and heat resistance. (vulcanization)",image:"images/elements/016_S/04_Vulcanized_rubber.jpg",priority:"standard",display_context:"orbital",tags:["uses","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Vulcanized_rubber.jpg"}]},{kind:"Origin",title:"Sulfur mining at Kawah Ijen",text:"Natural occurrence — Traditional miners harvesting native sulfur deposited by volcanic fumaroles at the Kawah Ijen crater in East Java, Indonesia. (volcanic sulfur)",image:"images/elements/016_S/11_Kawah-Ijen_Indonesia_Ijen-Sulfur-Miner-01.jpg",priority:"standard",display_context:"orbital",tags:["origin","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Kawah-Ijen_Indonesia_Ijen-Sulfur-Miner-01.jpg"}]},{kind:"Safety",title:"Hydrogen sulfide toxic hazard",text:"[Safety Warning] Hydrogen sulfide (H₂S) is an extremely toxic, flammable gas with a strong rotten egg odor. At higher concentrations, it quickly paralyzes the olfactory system, rendering it odorless and leading to rapid, fatal asphyxiation. (toxic gas)",image:"images/elements/016_S/06_GHS-pictogram-skull.svg",priority:"standard",display_context:"orbital",tags:["safety","S","16"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-skull.svg"}]},{kind:"History",title:"Lavoisier establishes sulfur as an element",text:"Historical record — Antoine Lavoisier's late-eighteenth-century experiments helped establish sulfur as a chemical element rather than a compound.",image:"images/elements/016_S/18_Antoine_Lavoisier_and_his_wife_David.jpg",priority:"core",display_context:"orbital",tags:["history","S","16"],panel:{type:"timeline",items:[{year:"1777",title:"Antoine Lavoisier defines sulfur as an element",text:"French chemist Antoine Lavoisier presents experimental evidence to convince the scientific community that sulfur is a distinct element, not a compound.",image:"images/elements/016_S/18_Antoine_Lavoisier_and_his_wife_David.jpg"},{year:"1894",title:"Herman Frasch transforms sulfur mining",text:"German-American chemist Herman Frasch develops a method to extract sulfur from deep underground deposits by melting it with superheated water and pumping it up with compressed air. A later patent drawing documents the underground fusion method.",image:"images/elements/016_S/19_Frasch_process_sulfur_mining_patent.jpg"}]},sources:[{label:"Portrait of Monsieur Lavoisier and His Wife by Jacques-Louis David — Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:David_-_Portrait_of_Monsieur_Lavoisier_and_His_Wife.jpg"},{label:"Process of Mining Sulfur patent drawing — Digital Public Library of America via Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Process_of_Mining_Sulfur._-_DPLA_-_0d5d9e39616ea3827d7dcd24e7b92c64_(page_1).jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Sulfur emission spectrum",text:"Emission spectrum — Spectral lines of Sulfur (S) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/016_S/17_16_(S_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","s","16"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:16_%28S_I%29_NIST_ASD_emission_spectrum.png"}]}],17:[{kind:"Portrait",title:"Pressurized liquid chlorine in a quartz ampoule",text:"Physical state — Elemental chlorine liquefied above 7.4 bar and sealed in a quartz ampoule. The tight crop keeps the pale yellow liquid and vapor directly visible without the surrounding display label. (liquid chlorine)",image:"images/elements/017_Cl/20_Pressurized_liquid_chlorine_ampoule_cropped.jpg",priority:"core",display_context:"orbital",tags:["portrait","Cl","17"],sources:[{label:"Wikimedia Commons — Alchemist-hp (Free Art License)",url:"https://commons.wikimedia.org/wiki/File:Chlorine_liquid_in_an_ampoule_(cropped).jpg"}]},{kind:"Origin",title:"Clear halite crystals on matrix",text:"Natural occurrence — Clear cubic halite (rock salt, NaCl) crystals on their mineral matrix. Halite evaporite deposits supply the chloride used by the chloralkali process. (halite mineral)",image:"images/elements/017_Cl/18_Clear_halite_crystals_on_matrix.jpg",priority:"standard",display_context:"orbital",tags:["origin","Cl","17"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Clear_Halite_Crystals_on_matrix.jpg"}]},{kind:"Uses",title:"Household bleach",text:"Practical application — Household bleach bottles containing sodium hypochlorite (NaClO). It is a highly effective household disinfectant, sanitizer, and bleaching agent working through oxidation. (bleach)",image:"images/elements/017_Cl/02_Bleach_bottle.jpg",priority:"core",display_context:"orbital",tags:["uses","Cl","17"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Bleach_bottle.jpg"}]},{kind:"Uses",title:"Polyvinyl chloride (PVC) pipes",text:"Practical application — PVC pipes. PVC is one of the most widely manufactured synthetic plastics, containing about 57% chlorine by weight, providing rigidity and durability. (PVC)",image:"images/elements/017_Cl/04_PVC_Pipes.jpg",priority:"standard",display_context:"orbital",tags:["uses","Cl","17"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:PVC_Pipes.jpg"}]},{kind:"Safety",title:"Chlorine toxic gas hazard",text:"[Safety Warning] Chlorine gas (Cl₂) is highly toxic, corrosive, and reactive. Inhalation causes severe respiratory tract irritation, pulmonary edema, and death. It must be handled under strict containment. (toxicity)",image:"images/elements/017_Cl/01_GHS-pictogram-skull.svg",priority:"standard",display_context:"orbital",tags:["safety","Cl","17"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-skull.svg"}]},{kind:"History",title:"Chlorine discovery timeline",text:"Key milestones of chlorine: from its initial isolation in Sweden to its recognition as a chemical element.",image:"images/elements/017_Cl/07_Carl_Wilhelm_Scheele_from_Familj-Journalen1874.png",priority:"core",display_context:"orbital",tags:["history","Cl","17"],panel:{type:"timeline",items:[{year:"1774",title:"Carl Wilhelm Scheele isolates chlorine gas",text:"Swedish-German chemist Carl Wilhelm Scheele isolates chlorine by reacting hydrochloric acid with manganese dioxide, thinking it is a compound containing oxygen.",image:"images/elements/017_Cl/07_Carl_Wilhelm_Scheele_from_Familj-Journalen1874.png"},{year:"1810",title:"Humphry Davy identifies chlorine as an element",text:"English chemist Humphry Davy proves that the gas is a chemical element and names it 'chlorine' from the Greek word 'chloros' (pale green).",image:"images/elements/017_Cl/19_Humphry_Davy_Wellcome_engraving.jpg"}]},sources:[{label:"Wikimedia Commons — Carl Wilhelm Scheele",url:"https://commons.wikimedia.org/wiki/File:Carl_Wilhelm_Scheele_from_Familj-Journalen1874.png"}]},{kind:"Science",display_hint:"spectrum",title:"Chlorine emission spectrum",text:"Emission spectrum — Spectral lines of Chlorine (Cl) from the NIST Atomic Spectra Database.",image:"images/elements/017_Cl/17_17_(Cl_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","cl","17"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Chlorine valence-shell diagram",text:"Atomic structure — A chlorine atom has the electron-shell configuration 2,8,7. Its seven valence electrons account for the strong tendency of elemental chlorine to gain one electron in chloride compounds.",image:"images/elements/017_Cl/06_Electron_shell_017_Chlorine.svg",priority:"standard",display_context:"orbital",tags:["science","atomic-structure","Cl","17"],sources:[{label:"Wikimedia Commons — Electron shell 017 Chlorine",url:"https://commons.wikimedia.org/wiki/File:Electron_shell_017_Chlorine.svg"}]}],18:[{kind:"Portrait",title:"Argon gas discharge tube",text:"Physical state — An argon gas discharge tube glowing with a bright violet-blue light under high voltage, illustrating the distinct emission spectrum of this noble gas. (discharge)",image:"images/elements/018_Ar/10_Argon_discharge_tube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ar","18"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Argon_discharge_tube.jpg"}]},{kind:"Science",title:"Argon fluorohydride (HArF) structure",text:"Chemical properties — Molecular structure model of argon fluorohydride (HArF), the first stable compound of argon synthesized in 2000 at low temperatures, showing argon can form bonds. (compound)",image:"images/elements/018_Ar/12_Argon-fluorohydride-3D-balls.png",priority:"standard",display_context:"orbital",tags:["science","Ar","18"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Argon-fluorohydride-3D-balls.png"}]},{kind:"Uses",title:"TIG welding process",text:"Practical application — Tungsten Inert Gas (TIG) welding. Argon gas is used as an inert shielding atmosphere to protect the welding zone from reactive atmospheric gases at high temperatures. (welding)",image:"images/elements/018_Ar/09_Tig_welding.jpg",priority:"core",display_context:"orbital",tags:["uses","Ar","18"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Tig_welding.jpg"}]},{kind:"Safety",title:"Compressed gas cylinder hazard",text:"[Safety Warning] Argon is chemically inert and non-toxic. However, as a compressed gas, it presents physical rupture hazards, and releases in confined spaces can displace oxygen, causing rapid, silent asphyxiation. (asphyxiant)",image:"images/elements/018_Ar/05_GHS-pictogram-bottle.svg",priority:"standard",display_context:"orbital",tags:["safety","Ar","18"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-bottle.svg"}]},{kind:"History",title:"Argon discovery timeline",text:"Key milestones of argon: from the discovery of atmospheric nitrogen anomalies to its isolation as a noble gas.",image:"images/elements/018_Ar/07_Lord_Rayleigh.jpg",priority:"core",display_context:"orbital",tags:["history","Ar","18"],panel:{type:"timeline",items:[{year:"1894",title:"Lord Rayleigh and William Ramsay discover argon",text:"Lord Rayleigh and Sir William Ramsay isolate argon at University College London by removing oxygen, nitrogen, carbon dioxide, and water from clean air.",image:"images/elements/018_Ar/07_Lord_Rayleigh.jpg"},{year:"1895",title:"Ramsay establishes the noble gas group",text:"William Ramsay continues his work to isolate terrestrial helium, and later neon, krypton, and xenon, completing the noble gases column in the periodic table. His 1900 textbook records the new chemical framework.",image:"images/elements/018_Ar/11_William_Ramsay_Modern_Chemistry_title_page.jpg"}]},sources:[{label:"Wellcome Collection via Wikimedia Commons · William Ramsay, Modern Chemistry title page (CC BY 4.0)",url:"https://commons.wikimedia.org/wiki/File:W._Ramsay;_Modern_Chemistry._Title_page._Wellcome_L0005299.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Argon emission spectrum",text:"Emission spectrum — Spectral lines of Argon (Ar) from the NIST Atomic Spectra Database.",image:"images/elements/018_Ar/18_18_(Ar_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","ar","18"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],19:[{kind:"Portrait",title:"Freshly cut potassium metal sample",text:"Physical state — Silvery block of potassium metal showing a freshly cut surface. Potassium is a soft, highly reactive alkali metal that oxidizes within seconds in air and must be stored under protective mineral oil. (potassium metal)",image:"images/elements/019_K/03_Potassium__19_K_.jpg",priority:"core",display_context:"orbital",tags:["portrait","K","19"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Potassium_(19_K).jpg"}]},{kind:"Origin",title:"Sylvite mineral specimen",text:"Natural occurrence — Sylvite (potassium chloride, KCl), a major naturally occurring evaporite mineral which serves as a vital ore of potassium. (sylvite ore)",image:"images/elements/019_K/05_Sylvite-Quartz-Calcite-145142.jpg",priority:"standard",display_context:"orbital",tags:["origin","K","19"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sylvite-Quartz-Calcite-145142.jpg"}]},{kind:"Origin",title:"Potassium feldspar crystal",text:"Natural occurrence — Potassium feldspar (KAlSi₃O₈), one of the most abundant rock-forming silicate minerals in Earth's crust. (feldspar mineral)",image:"images/elements/019_K/11_Potassium_feldspar__32499528651_.jpg",priority:"standard",display_context:"orbital",tags:["origin","K","19"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Potassium_feldspar_(32499528651).jpg"}]},{kind:"Science",title:"Potassium flame test",text:"Emission spectrum — Excitation of potassium ions in a flame produces a characteristic pale lilac or violet emission light, used for chemical identification. (flame test)",image:"images/elements/019_K/02_Prueba_de_llama_de_tetracianoniquelato__II__de_potasio.jpg",priority:"standard",display_context:"orbital",tags:["science","K","19"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Prueba_de_llama_de_tetracianoniquelato_(II)_de_potasio.jpg"}]},{kind:"Life",title:"Potassium ion channel",text:"Biological role — Structure of a potassium channel. These specialized proteins regulate electrical potentials and signal transmission in cellular neurons. (potassium channel)",image:"images/elements/019_K/06_Potassium_channel.png",priority:"standard",display_context:"orbital",tags:["life","K","19"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Potassium_channel.svg"}]},{kind:"History",title:"Potassium discovery timeline",text:"Key milestones of potassium: from its extraction from plant ash compounds to its isolation by electrolysis.",image:"images/elements/019_K/17_Humphry_Davy_by_Thomas_Phillips.jpg",priority:"core",display_context:"orbital",tags:["history","K","19"],panel:{type:"timeline",items:[{year:"1807",title:"Humphry Davy isolates potassium",text:"English chemist Humphry Davy isolates potassium by electrolysis of molten potassium hydroxide (caustic potash), making it the first metal isolated via electrolysis.",image:"images/elements/019_K/17_Humphry_Davy_by_Thomas_Phillips.jpg"}]},sources:[{label:"Sir Humphry Davy by Thomas Phillips · Wikimedia Commons (public domain)",url:"https://commons.wikimedia.org/wiki/File:Sir_Humphry_Davy,_Bt_by_Thomas_Phillips.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Potassium emission spectrum",text:"Emission spectrum — Spectral lines of Potassium (K) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/019_K/16_19_(K_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","k","19"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:19_%28K_I%29_NIST_ASD_emission_spectrum.png"}]}],20:[{kind:"Portrait",title:"Calcium metal chunks",text:"Physical form — Silvery-white pieces of calcium metal under protective conditions. In contact with air, it quickly tarnishes, forming a white oxide-nitride coating. (calcium metal)",image:"images/elements/020_Ca/01_Calcium__20_Ca_.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ca","20"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Calcium_(20_Ca).jpg"}]},{kind:"Origin",title:"Gypsum mineral specimen",text:"Natural occurrence — Gypsum (hydrated calcium sulfate, CaSO₄·2H₂O), a widespread sulfate mineral mined extensively for industrial plaster and drywall production. (gypsum ore)",image:"images/elements/020_Ca/10_Gypsum_-_Sieroszowice_mine__Lubin__Lower_Silesia__Poland.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ca","20"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Gypsum_-_Sieroszowice_mine,_Lubin,_Lower_Silesia,_Poland.jpg"}]},{kind:"Science",title:"Calcium flame test",text:"Emission spectrum — Combustion of calcium compounds yields a characteristic brick-red or orange-red flame color, used in qualitative chemical analysis. (flame test)",image:"images/elements/020_Ca/06_Calcium_flame_test.jpg",priority:"standard",display_context:"orbital",tags:["science","Ca","20"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Calcium_flame_test.jpg"}]},{kind:"Life",title:"Human skeletal system",text:"Biological role — Human skeleton. Calcium phosphate minerals provide structural rigidity and strength to bones and teeth, serving as the body's calcium reservoir. (skeleton)",image:"images/elements/020_Ca/03_Human_skeleton_front_en.svg",priority:"core",display_context:"orbital",tags:["life","Ca","20"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Human_skeleton_front_en.svg"}]},{kind:"Life",title:"Intracellular calcium signaling",text:"Biological role — Calcium ions (Ca²⁺) act as essential intracellular messengers, regulating muscle contraction, neurotransmitter release, and cellular pathways. (signaling)",image:"images/elements/020_Ca/05_Calcium_signaling.png",priority:"standard",display_context:"orbital",tags:["life","Ca","20"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Calcium_signaling.svg"}]},{kind:"Safety",title:"Calcium metal flammability hazard",text:"[Safety Warning] Pure calcium metal reacts with water and moisture to release flammable hydrogen gas. The heat generated can cause hydrogen to ignite. Finely divided calcium powder is a severe fire and dust explosion hazard. (flammability)",image:"images/elements/020_Ca/07_GHS-pictogram-flamme.svg",priority:"standard",display_context:"orbital",tags:["safety","Ca","20"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"History",title:"Calcium discovery timeline",text:"Key milestones of calcium: from ancient construction lime to the electrochemical isolation of the metal.",image:"images/elements/020_Ca/17_Humphry_Davy_Wellcome_mezzotint.jpg",priority:"core",display_context:"orbital",tags:["history","Ca","20"],panel:{type:"timeline",items:[{year:"1808",title:"Humphry Davy isolates calcium",text:"English chemist Humphry Davy isolates metallic calcium by electrolyzing a mixture of lime (calcium oxide) and mercuric oxide in a mercury amalgam.",image:"images/elements/020_Ca/17_Humphry_Davy_Wellcome_mezzotint.jpg"},{year:"1808",title:"Nomenclature and etymology",text:"The element is named Calcium after 'calx', the Latin word for lime (calcium carbonate/oxide), which had been utilized for mortar since antiquity.",image:"images/elements/020_Ca/19_Roman_lime_kiln_Jan_Miel.jpg"}]},sources:[{label:"Wellcome Collection via Wikimedia Commons · Humphry Davy mezzotint (CC BY 4.0)",url:"https://commons.wikimedia.org/wiki/File:Sir_Humphry_Davy._Mezzotint_by_C._Turner,_1835,_after_H._How_Wellcome_V0001492.jpg"},{label:"Wikimedia Commons — Roman Lime Kiln with Peasants Gambling, Jan Miel",url:"https://commons.wikimedia.org/wiki/File:%27Roman_Lime_Kiln_with_Peasants_Gambling%27_by_Jan_Miel.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Calcium emission spectrum",text:"Emission spectrum — Spectral lines of Calcium (Ca) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/020_Ca/18_20_(Ca_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ca","20"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:20_%28Ca_I%29_NIST_ASD_emission_spectrum.png"}]}],21:[{kind:"Portrait",title:"Sublimed dendritic scandium metal",text:"Physical state — Sublimed dendritic scandium metal crystals and a 1cm³ volume cube, showing a lustrous silvery-white surface that slowly tarnishes to a yellowish tint. (scandium metal)",image:"images/elements/021_Sc/03_Scandium_sublimed_dendritic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Sc","21"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Scandium_sublimed_dendritic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Natural thortveitite crystal",text:"Natural occurrence — A thortveitite crystal, the rare scandium–yttrium silicate mineral (Sc,Y)₂Si₂O₇ and an important natural mineral source of scandium.",image:"images/elements/021_Sc/14_Thortveitite_natural_crystal.jpg",priority:"standard",display_context:"orbital",tags:["origin","Sc","21"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Thortveitite-ea14a.jpg"}]},{kind:"Safety",title:"General safety handling warning",text:"[Safety Warning] Elemental scandium metal and its compounds are generally considered of low to moderate toxicity. However, breathing scandium dust or mist can cause respiratory irritation. Standard protective dust masks and gloves are recommended. (safety)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Sc","21"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Scandium discovery timeline",text:"Key milestones of scandium: from Mendeleev's periodic prediction to the isolation of the element in Sweden.",image:"images/elements/021_Sc/12_Dmitri_Mendeleev.jpg",priority:"core",display_context:"orbital",tags:["history","Sc","21"],panel:{type:"timeline",items:[{year:"1869",title:"Dmitri Mendeleev predicts eka-boron",text:"Dmitri Mendeleev publishes his periodic law and predicts the existence of an undiscovered element he names 'eka-boron' with an atomic mass around 44.",image:"images/elements/021_Sc/12_Dmitri_Mendeleev.jpg"},{year:"1879",title:"Lars Fredrik Nilson discovers scandium",text:"Swedish chemist Lars Fredrik Nilson discovers a new element in euxenite and gadolinite minerals, naming it 'scandium' after Scandinavia.",image:"images/elements/021_Sc/07_Lars_Fredrik_Nilson.jpg"}]},sources:[{label:"Wikimedia Commons — Dmitri Mendeleev",url:"https://commons.wikimedia.org/wiki/File:Dmitri_Mendeleev.jpg"},{label:"Wikimedia Commons — Lars Fredrik Nilson",url:"https://commons.wikimedia.org/wiki/File:Lars_Fredrik_Nilson.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Scandium emission spectrum",text:"Emission spectrum — Spectral lines of Scandium (Sc) from the NIST Atomic Spectra Database.",image:"images/elements/021_Sc/14_21_(Sc_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","sc","21"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Scandium(III) sulfide crystal structure",text:"Crystal structure — Ball-and-stick model of the Sc₂S₃ crystal unit cell, showing a directly resolved scandium compound structure.",image:"images/elements/021_Sc/15_Scandium_III_sulfide_crystal_structure.png",priority:"standard",display_context:"orbital",tags:["science","crystal structure","Sc","21"],sources:[{label:"Wikimedia Commons — Scandium(III) sulfide crystal structure",url:"https://commons.wikimedia.org/wiki/File:Scandium(III)-sulfide-xtal-1964-unit-cell-CM-3D-balls.png"}]}],22:[{kind:"Portrait",title:"High-purity titanium crystal bar",text:"Physical state — Silvery-grey high-purity titanium metal crystal bar, manufactured by the thermal iodide deposition process. (titanium bar)",image:"images/elements/022_Ti/01_Titan-crystal_bar.JPG",priority:"core",display_context:"orbital",tags:["portrait","Ti","22"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Titan-crystal_bar.JPG"}]},{kind:"Origin",title:"Ilmenite mineral specimen",text:"Natural occurrence — Ilmenite (iron titanium oxide, FeTiO₃), a black mineral found in igneous and metamorphic rocks, serving as the main industrial ore of titanium. (ilmenite ore)",image:"images/elements/022_Ti/09_Ilmenite-147664.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ti","22"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Ilmenite-147664.jpg"}]},{kind:"Science",title:"Electrostatic levitation of liquid titanium alloy",text:"Chemical properties — Liquid titanium-zirconium-nickel alloy droplet levitated electrostatically during materials science research under vacuum conditions. (levitation)",image:"images/elements/022_Ti/06_Electrostatic_Levitation_of_a_Titanium-Zirconium-Nickel_Alloy.jpg",priority:"standard",display_context:"orbital",tags:["science","Ti","22"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Electrostatic_Levitation_of_a_Titanium-Zirconium-Nickel_Alloy.jpg"}]},{kind:"Uses",title:"Biocompatible titanium hip implant",text:"Practical application — Titanium hip replacement implant. Titanium is extensively used in orthopedic surgery due to its lightweight strength and excellent biocompatibility. (implant)",image:"images/elements/022_Ti/02_Titanium_hip_implant.jpg",priority:"core",display_context:"orbital",tags:["uses","Ti","22"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Titanium_hip_implant.jpg"}]},{kind:"Safety",title:"Titanium dust flammability hazard",text:"[Safety Warning] Titanium metal in bulk form is highly corrosion-resistant and biologically inert. However, fine titanium powder or grinding dust is highly flammable and poses a severe dust explosion risk when exposed to sparks or flame. (flammability)",image:"images/elements/022_Ti/04_GHS-pictogram-flamme.svg",priority:"standard",display_context:"orbital",tags:["safety","Ti","22"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"History",title:"Titanium discovery timeline",text:"Key milestones of titanium: from Gregor's discovery in mineral sands to the naming of the element after mythological titans.",image:"images/elements/022_Ti/05_William_Gregor.jpg",priority:"core",display_context:"orbital",tags:["history","Ti","22"],panel:{type:"timeline",items:[{year:"1791",title:"William Gregor discovers titanium",text:"English clergyman and mineralogist William Gregor discovers an unknown metal oxide in black sand from Cornwall, naming the mineral 'menachanite'.",image:"images/elements/022_Ti/05_William_Gregor.jpg"},{year:"1795",title:"Martin Klaproth names the element Titanium",text:"German chemist Martin Heinrich Klaproth independently discovers the oxide in rutile and names the element Titanium after the Titans of Greek mythology.",image:"images/elements/022_Ti/18_Martin_Heinrich_Klaproth_portrait.jpg"}]},sources:[{label:"Wikimedia Commons — William Gregor",url:"https://commons.wikimedia.org/wiki/File:William_Gregor.jpg"},{label:"Wellcome Collection via Wikimedia Commons — Martin Heinrich Klaproth",url:"https://commons.wikimedia.org/wiki/File:Martin_Heinrich_Klaproth._Mezzotint._Wellcome_V0003234.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Titanium emission spectrum (NIST ASD)",text:"Emission spectrum — The characteristic spectral lines of Titanium (Ti), recorded by the NIST Atomic Spectra Database. Each line corresponds to a specific electron transition unique to Ti. These lines are used for spectroscopic identification and stellar abundance measurements. (NIST ASD)",image:"images/elements/022_Ti/16_22_(Ti_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","spectroscopy","ti","22"],sources:[{label:"NIST Atomic Spectra Database",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:22_%28Ti_I%29_NIST_ASD_emission_spectrum.png"}]}],23:[{kind:"Portrait",title:"High-purity vanadium crystal bar and cube",text:"Physical state — Lustrous silver-grey high-purity vanadium metal crystal bar and a 1cm³ volume cube, showing high ductility and corrosion resistance. (vanadium metal)",image:"images/elements/023_V/06_Vanadium_crystal_bar_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","V","23"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Vanadium_crystal_bar_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Vanadinite mineral crystal",text:"Natural occurrence — Vanadinite (lead chlorovanadate, Pb₅(VO₄)₃Cl), displaying striking red hexagonal crystals. It is a major mineral source of vanadium. (vanadinite)",image:"images/elements/023_V/11_Vanadinite-153208.jpg",priority:"standard",display_context:"orbital",tags:["origin","V","23"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Vanadinite-153208.jpg"}]},{kind:"Science",title:"Vanadium oxidation states colors",text:"Chemical properties — Four different oxidation states of vanadium (+2 lavender, +3 green, +4 blue, and +5 yellow) in solution, demonstrating its rich inorganic chemistry. (oxidation states)",image:"images/elements/023_V/13_VanadiumColors.png",priority:"core",display_context:"orbital",tags:["science","V","23"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:VanadiumColors.png"}]},{kind:"Safety",title:"Vanadium dust safety warning",text:"[Safety Warning] Vanadium pentoxide dust is highly toxic. It is irritating to the eyes and respiratory tract, suspected of causing genetic defects, and classified as a hazard. Proper protective equipment is mandatory during industrial handling. (toxicity)",image:"images/elements/023_V/05_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","V","23"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Vanadium discovery timeline",text:"Key milestones of vanadium: from Del Río's discovery of erythronium in Mexico to the Norse goddess naming by Sefström.",image:"images/elements/023_V/18_Andres_Manuel_del_Rio_1825.png",priority:"core",display_context:"orbital",tags:["history","V","23"],panel:{type:"timeline",items:[{year:"1801",title:"Andrés Manuel del Río discovers the element",text:"Spanish-Mexican mineralogist Andrés Manuel del Río discovers vanadium in vanadinite ore, calling it 'erythronium' due to the red salts formed upon heating.",image:"images/elements/023_V/18_Andres_Manuel_del_Rio_1825.png"},{year:"1830",title:"Nils Gabriel Sefström rediscovers vanadium",text:"Swedish chemist Nils Gabriel Sefström rediscovers the metal and names it Vanadium after Vanadis, the Norse goddess of beauty and fertility, due to the colored compounds.",image:"images/elements/023_V/19_Nils_Gabriel_Sefstrom.png"}]},sources:[{label:"Wikimedia Commons — Andrés Manuel del Río, 1825",url:"https://commons.wikimedia.org/wiki/File:Andr%C3%A9s_Manuel_del_R%C3%ADo_(Rafael_Ximeno_y_Planes_1825)_retrato.png"},{label:"Wikimedia Commons — Nils Gabriel Sefström",url:"https://commons.wikimedia.org/wiki/File:Nils_Gabriel_Sefstr%C3%B6m_(1787-1845)_3.png"}]},{kind:"Science",display_hint:"spectrum",title:"Vanadium emission spectrum",text:"Emission spectrum — Spectral lines of Vanadium (V) from the NIST Atomic Spectra Database.",image:"images/elements/023_V/16_23_(V_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","v","23"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],24:[{kind:"Portrait",title:"Zone-refined chromium metal and cube",text:"Physical state — Silvery-blue zone-refined chromium metal chunk and a 1cm³ volume cube, showing a lustrous, highly polished surface. (chromium metal)",image:"images/elements/024_Cr/11_Chromium_zone_refined_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Cr","24"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Chromium_zone_refined_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Crocoite mineral specimen",text:"Natural occurrence — Crocoite (lead chromate, PbCrO₄) mineral from Tasmania, featuring vibrant red-orange crystals. It is the mineral in which chromium was first discovered. (crocoite)",image:"images/elements/024_Cr/10_Crocoite-245784.jpg",priority:"standard",display_context:"orbital",tags:["origin","Cr","24"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Crocoite-245784.jpg"}]},{kind:"Uses",title:"Chrome-plated hex nut",text:"Practical application — Thin electroplated chrome coats this steel hex nut, providing a decorative finish and corrosion resistance. (chrome plating)",image:"images/elements/024_Cr/02_Chrome_plating.jpg",priority:"core",display_context:"orbital",tags:["uses","Cr","24"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Chrome_plating.jpg"}]},{kind:"Safety",title:"Hexavalent chromium carcinogen warning",text:"[Safety Warning] Trivalent chromium (Cr³⁺) is a trace nutrient. However, hexavalent chromium (Cr⁶⁺, as in chromates/dichromates) is highly toxic, corrosive, mutagenic, and a confirmed human lung carcinogen. Handling requires strict protection. (toxic hazard)",image:"images/elements/024_Cr/08_GHS-pictogram-silhouette.svg",priority:"standard",display_context:"orbital",tags:["safety","Cr","24"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-silhouette.svg"}]},{kind:"History",title:"Chromium discovery timeline",text:"Key milestones of chromium: from Vauquelin's analysis of crocoite mineral to the chemical reduction of the oxide.",image:"images/elements/024_Cr/14_Louis_Nicolas_Vauquelin.jpg",priority:"core",display_context:"orbital",tags:["history","Cr","24"],panel:{type:"timeline",items:[{year:"1797",title:"Louis-Nicolas Vauquelin discovers chromium",text:"French chemist Louis-Nicolas Vauquelin isolates a new element from crocoite mineral, naming it Chromium from the Greek word 'chroma' (color) due to the color of its compounds.",image:"images/elements/024_Cr/14_Louis_Nicolas_Vauquelin.jpg"}]},sources:[{label:"Wikimedia Commons — Louis-Nicolas Vauquelin",url:"https://commons.wikimedia.org/wiki/File:Louis-Nicolas_Vauquelin.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Chromium emission spectrum",text:"Emission spectrum — Spectral lines of Chromium (Cr) from the NIST Atomic Spectra Database.",image:"images/elements/024_Cr/16_24_(Cr_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","cr","24"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Chromium(III) oxide sample",text:"Materials chemistry — A laboratory sample of chromium(III) oxide (Cr₂O₃), the stable green chromium oxide.",image:"images/elements/024_Cr/07_Chromium_III__oxide.jpg",priority:"standard",display_context:"orbital",tags:["science","materials chemistry","Cr","24"],sources:[{label:"Wikimedia Commons — Chromium(III) oxide sample",url:"https://commons.wikimedia.org/wiki/File:Chromium(III)-oxide-sample.jpg"}]}],25:[{kind:"Portrait",title:"Electrolytic manganese flakes and cube",text:"Physical form — Hard, brittle silvery-pink electrolytic manganese metal pieces and a 1cm³ volume cube. (manganese metal)",image:"images/elements/025_Mn/13_Manganese_electrolytic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Mn","25"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Manganese_electrolytic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Pyrolusite mineral specimen",text:"Natural occurrence — Pyrolusite (manganese dioxide, MnO₂), a dark grey, soft mineral which represents the main natural geological ore of manganese. (pyrolusite)",image:"images/elements/025_Mn/11_Pyrolusite-190168.jpg",priority:"standard",display_context:"orbital",tags:["origin","Mn","25"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Pyrolusite-190168.jpg"}]},{kind:"Uses",title:"Alkaline battery cell",text:"Practical application — Alkaline battery. Manganese dioxide (MnO₂) is used as the active cathode material to react with zinc, serving as an energy storage chemical. (battery)",image:"images/elements/025_Mn/01_Alkaline_battery.jpg",priority:"core",display_context:"orbital",tags:["uses","Mn","25"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Alkaline_battery.jpg"}]},{kind:"Safety",title:"Manganism chronic safety warning",text:"[Safety Warning] Manganese is an essential nutrient in small amounts. However, chronic inhalation of industrial manganese fumes or dust leads to Manganism, a severe neurological disease similar to Parkinson's disease. Protective equipment is required. (safety)",image:"images/elements/025_Mn/04_GHS-pictogram-silhouette.svg",priority:"standard",display_context:"orbital",tags:["safety","Mn","25"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-silhouette.svg"}]},{kind:"History",title:"Manganese discovery timeline",text:"Key milestones of manganese: from Scheele's recognition of a new oxide element to Gahn's successful reduction using charcoal.",image:"images/elements/025_Mn/05_Johan_Gottlieb_Gahn.jpg",priority:"core",display_context:"orbital",tags:["history","Mn","25"],panel:{type:"timeline",items:[{year:"1774",title:"Johan Gottlieb Gahn isolates manganese",text:"Swedish chemist Johan Gottlieb Gahn successfully isolates metallic manganese by heating manganese dioxide with charcoal (carbon) in a crucible.",image:"images/elements/025_Mn/05_Johan_Gottlieb_Gahn.jpg"},{year:"1774",title:"Carl Wilhelm Scheele recognizes manganese",text:"Swedish chemist Carl Wilhelm Scheele proves that the mineral pyrolusite contains a new chemical element, but fails to isolate the metal itself.",image:"images/elements/025_Mn/20_Carl_Wilhelm_Scheele_Scheffner.png"}]},sources:[{label:"Wikimedia Commons — Johan Gottlieb Gahn",url:"https://commons.wikimedia.org/wiki/File:Johan_Gottlieb_Gahn.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Manganese emission spectrum",text:"Emission spectrum — Spectral lines of Manganese (Mn) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/025_Mn/16_25_(Mn_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","mn","25"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:25_%28Mn_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Manganese dioxide sample",text:"Materials chemistry — A laboratory sample of manganese dioxide (MnO₂), an inorganic manganese oxide used extensively in electrochemistry.",image:"images/elements/025_Mn/10_Manganese-dioxide-sample.jpg",priority:"standard",display_context:"orbital",tags:["science","materials chemistry","Mn","25"],sources:[{label:"Wikimedia Commons — Manganese dioxide sample",url:"https://commons.wikimedia.org/wiki/File:Manganese-dioxide-sample.jpg"}]}],26:[{kind:"Portrait",title:"Electrolytic iron flakes and cube",text:"Physical state — Electrolytic pure iron metal flakes and a polished 1cm³ cube. Highly pure iron has a lustrous silver-grey color, is relatively soft, and displays strong ferromagnetic properties at room temperature. (pure iron)",image:"images/elements/026_Fe/02_Iron_electrolytic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Fe","26"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Iron_electrolytic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Hematite mineral specimen",text:"Natural occurrence — Hematite mineral specimen. An iron oxide mineral (Fe₂O₃) that constitutes the most important iron ore mined worldwide due to its high iron content. (hematite ore)",image:"images/elements/026_Fe/07_Hematite-121832.jpg",priority:"standard",display_context:"orbital",tags:["origin","Fe","26"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hematite-121832.jpg"}]},{kind:"Origin",title:"Magnetite crystal",text:"Natural occurrence — Magnetite crystal. A highly ferromagnetic iron oxide mineral (Fe₃O₄) that naturally attracts iron filings, historically serving as the first natural magnets (lodestones). (magnetite mineral)",image:"images/elements/026_Fe/08_Magnetite-118736.jpg",priority:"standard",display_context:"orbital",tags:["origin","Fe","26"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Magnetite-118736.jpg"}]},{kind:"Uses",title:"Structural steel beams",text:"Practical application — Heavy structural steel beams in construction. Iron is alloyed with carbon and other metals to form steel, the most vital material in modern infrastructure. (structural steel)",image:"images/elements/026_Fe/14_pexels_steel-constriction-with-pipes-14028309.jpg",priority:"core",display_context:"orbital",tags:["uses","Fe","26"],sources:[{label:"Pexels",url:"https://www.pexels.com/photo/steel-constriction-with-pipes-14028309/"}]},{kind:"History",title:"Ancient iron dagger and metallurgy history",text:"Historical record — An ancient iron dagger with an ivory handle, representing the long transition from early ironworking to industrial steel production.",image:"images/elements/026_Fe/16_Ancient_iron_dagger_with_ivory_handle.jpg",priority:"core",display_context:"orbital",tags:["history","Fe","26"],panel:{type:"timeline",items:[{year:"Iron Age",title:"Iron tools and weapons transform material culture",text:"Archaeological iron artifacts document the transition from bronze to iron metallurgy, enabling durable tools, weapons, and infrastructure across many societies.",image:"images/elements/026_Fe/17_Iron_Age_artifacts_Pattanam.jpg"},{year:"1856",title:"Henry Bessemer invents the Bessemer process",text:"English engineer Henry Bessemer patents a cheap method for mass-producing steel by blowing air through molten pig iron to burn off carbon impurities.",image:"images/elements/026_Fe/06_Bessemer_converter_Sheffield.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Iron_Dagger_with_Ivory_Handle_(41406737590).jpg"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Iron_artifacts_(Iron_age-early_historic_transition_phase),_Pattanam_Excavation_Site_Museum_(Kerala).jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Iron emission spectrum",text:"Emission spectrum — Spectral lines of Iron (Fe) from the NIST Atomic Spectra Database.",image:"images/elements/026_Fe/15_26_(Fe_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","fe","26"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"NASA electron micrograph of lunar iron crystals",text:"Electron microscopy — NASA scanning electron micrograph of iron crystals in an Apollo 15 lunar breccia; the largest crystal is about 3 µm across.",image:"images/elements/026_Fe/16_NASA_SEM_lunar_iron_crystal.jpg",priority:"standard",display_context:"orbital",tags:["science","electron microscopy","Fe","26"],sources:[{label:"NASA Johnson Space Center via Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Scanning_electron_microscope_view_of_iron_crystal_(S72-55208).jpg"}]}],27:[{kind:"Portrait",title:"Electrolytic cobalt pieces and cube",text:"Physical state — Electrolytic pure cobalt metal pieces and a 1cm³ cube. Cobalt is a hard, lustrous, silver-grey ferromagnetic transition metal, closely resembling iron and nickel. (pure cobalt)",image:"images/elements/027_Co/03_Kobalt_electrolytic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Co","27"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Kobalt_electrolytic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Cobaltite mineral crystal",text:"Natural occurrence — Cobaltite crystal specimen. Cobaltite (cobalt sulfarsenide, CoAsS) is a major natural sulfide mineral and an important industrial ore of cobalt. (cobaltite mineral)",image:"images/elements/027_Co/08_Cobaltite-34596.jpg",priority:"standard",display_context:"orbital",tags:["origin","Co","27"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Cobaltite-34596.jpg"}]},{kind:"Science",title:"Cobalt coordination complexes",text:"Chemical properties — Various cobalt coordination complexes in solution, showcasing the vibrant pink, blue, green, and yellow colors characteristic of cobalt's transition states. (coordination complexes)",image:"images/elements/027_Co/11_Cobalt_complexes.jpg",priority:"standard",display_context:"orbital",tags:["science","Co","27"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Cobalt_complexes.jpg"}]},{kind:"Safety",title:"GHS health hazard symbol",text:"[Safety Warning] Inhalation of cobalt metal dust or fumes is toxic, causing respiratory irritation and asthma-like symptoms, and is classified as a suspected human carcinogen. Handling requires proper ventilation. (health hazard)",image:"images/elements/027_Co/05_GHS-pictogram-silhouette.svg",priority:"standard",display_context:"orbital",tags:["safety","Co","27"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-silhouette.svg"}]},{kind:"Science",display_hint:"spectrum",title:"Cobalt emission spectrum",text:"Emission spectrum — Spectral lines of Cobalt (Co) from the NIST Atomic Spectra Database.",image:"images/elements/027_Co/15_27_(Co_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","co","27"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],28:[{kind:"Portrait",title:"Electrolytic nickel pieces and cube",text:"Physical state — Electrolytic pure nickel metal flakes and a polished 1cm³ cube. Nickel is a hard, ductile, silver-white metal with a slight golden tinge, displaying ferromagnetism. (pure nickel)",image:"images/elements/028_Ni/03_Nickel_electrolytic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ni","28"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Nickel_electrolytic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Nickeline mineral from Saxony",text:"Natural occurrence — A natural nickeline (nickel arsenide, NiAs) specimen from Saxony. This nickel-bearing mineral is one of the deceptive copper-coloured ores that led miners to call it kupfernickel, or “devil's copper.” (nickeline mineral)",image:"images/elements/028_Ni/16_Nickeline_Saxony.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ni","28"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Nickeline-522428.jpg"}]},{kind:"Safety",title:"GHS health hazard symbol",text:"[Safety Warning] Nickel dust is a suspected carcinogen and a common allergen. Dermal contact with nickel-containing alloys can trigger allergic contact dermatitis (nickel allergy). Protective equipment is required during industrial processing. (health hazard)",image:"images/elements/028_Ni/05_GHS-pictogram-silhouette.svg",priority:"standard",display_context:"orbital",tags:["safety","Ni","28"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-silhouette.svg"}]},{kind:"History",title:"Nickel discovery timeline",text:"Key milestones of nickel: from Axel Cronstedt's discovery in Sweden to its nomenclature origin.",image:"images/elements/028_Ni/06_Axel_Fredrik_Cronstedt.jpg",priority:"core",display_context:"orbital",tags:["history","Ni","28"],panel:{type:"timeline",items:[{year:"1751",title:"Axel Fredrik Cronstedt discovers nickel",text:"Swedish mineralogist Axel Fredrik Cronstedt isolates a new metal from an ore miners called 'Kupfernickel' (devil's copper), proving it is a new element.",image:"images/elements/028_Ni/06_Axel_Fredrik_Cronstedt.jpg"},{year:"1758",title:"Cronstedt publishes a new mineral system",text:"Cronstedt's Essay towards a system of mineralogy set out a chemical approach to classifying minerals, carrying forward the analytical methods that had enabled his nickel discovery.",image:"images/elements/028_Ni/17_Axel_Fredrik_Cronstedt_Jernkontoret.jpg"}]},sources:[{label:"Wikimedia Commons — Axel Fredrik Cronstedt portrait",url:"https://commons.wikimedia.org/wiki/File:Axel_Fredrik_Cronstedt.JPG"},{label:"Wikimedia Commons — Cronstedt medal",url:"https://commons.wikimedia.org/wiki/File:Jernkontoret,_Cronstedt.jpg"},{label:"Wikimedia Commons — nickeline from Saxony",url:"https://commons.wikimedia.org/wiki/File:Nickeline-522428.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Nickel emission spectrum",text:"Emission spectrum — Spectral lines of Nickel (Ni) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Nickel in distant stars.",image:"images/elements/028_Ni/15_28_(Ni_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ni","28"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:28_%28Ni_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Electrochemically grown nickel nodule",text:"Electrochemistry — A piece of nickel grown by electroplating, showing the metallic surface created by electrodeposition.",image:"images/elements/028_Ni/18_Nickel_nodule_electroplating.jpg",priority:"standard",display_context:"orbital",tags:["science","electrochemistry","Ni","28"],sources:[{label:"Wikimedia Commons — electroplated nickel nodule",url:"https://commons.wikimedia.org/wiki/File:Nickel_Nodule_obtained_by_Electroplating.jpg"}]}],29:[{kind:"Portrait",title:"Polished copper metal disc",text:"Physical state — A highly polished high-purity copper metal disc, showing its characteristic reddish-orange metallic luster. Copper is an exceptionally ductile and malleable metal. (copper metal)",image:"images/elements/029_Cu/03_Cu-Scheibe.JPG",priority:"core",display_context:"orbital",tags:["portrait","Cu","29"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Cu-Scheibe.JPG"}]},{kind:"Origin",title:"Native copper mineral specimen",text:"Natural occurrence — Native copper specimen. Copper is one of the few metals that occurs in nature in directly usable metallic form (native metal) as geological deposits. (native copper)",image:"images/elements/029_Cu/04_Native_Copper__mineral_.jpg",priority:"standard",display_context:"orbital",tags:["origin","Cu","29"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Native_Copper_(mineral).jpg"}]},{kind:"Uses",title:"Stranded copper wiring cables",text:"Practical application — Stranded electrical copper cables, utilized worldwide in motors, generators, transformers, and electronic wiring systems. (electrical wiring)",image:"images/elements/029_Cu/20_pexels_close-up-photo-of-copper-wires-5279317.jpg",priority:"core",display_context:"orbital",tags:["uses","Cu","29"],sources:[{label:"Pexels",url:"https://www.pexels.com/photo/close-up-photo-of-copper-wires-5279317/"}]},{kind:"Uses",title:"Decorative bronze vase",text:"Practical application — A decorative bronze vase. Copper is alloyed with tin to make bronze, and with zinc to make brass, which have been used for thousands of years. (bronze alloy)",image:"images/elements/029_Cu/19_pexels_close-up-of-bronze-vase-10068468.jpg",priority:"standard",display_context:"orbital",tags:["uses","Cu","29"],sources:[{label:"Pexels",url:"https://www.pexels.com/photo/close-up-photo-of-bronze-vase-10068468/"}]},{kind:"Safety",title:"GHS environmental hazard symbol",text:"[Safety Warning] Soluble copper compounds are toxic to aquatic organisms and classified as environmental hazards. Copper dust can cause respiratory tract irritation. Proper disposal and waste management are required. (environmental hazard)",image:"images/elements/029_Cu/07_GHS-pictogram-pollu.svg",priority:"standard",display_context:"orbital",tags:["safety","Cu","29"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-pollu.svg"}]},{kind:"History",title:"Copper in human material history",text:"Historical record — A Moche copper axe-blade ornament, an archaeological example of copper's long role in craft and exchange. It is historical material culture, not a pure-element specimen. (pre-Columbian metallurgy)",image:"images/elements/029_Cu/21_Moche_copper_axe-blade_ornament.jpg",priority:"core",display_context:"orbital",tags:["history","Cu","29"],panel:{type:"timeline",items:[{year:"Pre-Columbian era",title:"Copper in ancient material culture",text:"This Moche copper axe-blade ornament records copper's role in skilled metalwork and exchange long before modern industrial use.",image:"images/elements/029_Cu/21_Moche_copper_axe-blade_ornament.jpg"},{year:"c. 3500 BC",title:"Bronze Age begins",text:"Metalworkers discover that alloying copper with tin produces bronze, a significantly harder alloy that transforms tools, weapons, and civilizations.",image:"images/elements/029_Cu/09_Copper_smelting.jpg"},{year:"1831",title:"Discovery of electromagnetic induction",text:"Michael Faraday's coil experiments establish electromagnetic induction, paving the way for generators, motors, and the electrical age. This 1855 Royal Institution image documents Faraday's experimental lecture setting.",image:"images/elements/029_Cu/22_Faraday_Royal_Institution_lecture_1855.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Copper_Axe_Blade_Ornament_MET_vs1987_394_218.jpg"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Professor_Faraday_lecturing_at_the_Royal_Institution,_27th_December,_1855_RIIC_0006_20110213_BAL_EP.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Copper emission spectrum",text:"Emission spectrum — Spectral lines of Copper (Cu) from the NIST Atomic Spectra Database.",image:"images/elements/029_Cu/20_29_(Cu_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","cu","29"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Copper(II) sulfate pentahydrate sample",text:"Materials chemistry — A sample of blue copper(II) sulfate pentahydrate, CuSO₄·5H₂O.",image:"images/elements/029_Cu/01_Copper_II_-sulfate-sample.jpg",priority:"standard",display_context:"orbital",tags:["science","materials chemistry","Cu","29"],sources:[{label:"Wikimedia Commons — Copper(II) sulfate pentahydrate sample",url:"https://commons.wikimedia.org/wiki/File:Copper(II)-sulfate-pentahydrate-sample.jpg"}]}],30:[{kind:"Portrait",title:"Sublimed zinc fragments and cube",text:"Physical state — Sublimed high-purity zinc metal fragments and a 1cm³ volume cube. Zinc is a moderately reactive, bluish-grey crystalline transition metal. (pure zinc)",image:"images/elements/030_Zn/03_Zinc_fragment_sublimed_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Zn","30"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Zinc_fragment_sublimed_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Sphalerite mineral crystal",text:"Natural occurrence — Sphalerite crystal. Sphalerite (zinc sulfide, ZnS) is the most abundant natural zinc-bearing mineral and the primary commercial ore of zinc. (sphalerite)",image:"images/elements/030_Zn/09_Sphalerite-112532.jpg",priority:"standard",display_context:"orbital",tags:["origin","Zn","30"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sphalerite-112532.jpg"}]},{kind:"Uses",title:"Galvanized steel sheets",text:"Practical application — Galvanized steel sheet. Zinc is primarily used to coat steel (galvanization), protecting the underlying iron from rust through sacrificial corrosion. (galvanized steel)",image:"images/elements/030_Zn/01_Galvanized_steel.jpg",priority:"core",display_context:"orbital",tags:["uses","Zn","30"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Galvanized_steel.jpg"}]},{kind:"Uses",title:"Zinc-carbon battery cell",text:"Practical application — Zinc-carbon battery schematic. Metallic zinc acts as the anode casing and electron donor in common dry cell batteries. (battery anode)",image:"images/elements/030_Zn/02_Zinc-carbon_battery.png",priority:"standard",display_context:"orbital",tags:["uses","Zn","30"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Zinc-carbon_battery.png"}]},{kind:"Safety",title:"GHS exclamation hazard symbol",text:"[Safety Warning] Metallic zinc is of low toxicity. However, inhaling zinc oxide fumes generated during welding galvanized steel causes 'metal fume fever', a temporary influenza-like illness. (welding safety)",image:"images/elements/030_Zn/06_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Zn","30"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Zinc discovery timeline",text:"Key milestones of zinc: from ancient brass metallurgy to its scientific isolation in Europe.",image:"images/elements/030_Zn/08_Andreas_Sigismund_Marggraf.jpg",priority:"core",display_context:"orbital",tags:["history","Zn","30"],panel:{type:"timeline",items:[{year:"c. 1000 BC",title:"Early brass production",text:"Ancient metalworkers in India and the Mediterranean produce brass (a copper-zinc alloy) by heating copper with zinc-rich minerals, though zinc was not yet recognized as a metal.",image:"images/elements/030_Zn/12_The_Zinc_Works_and_Incat.jpg"},{year:"1746",title:"Andreas Marggraf isolates pure zinc",text:"German chemist Andreas Sigismund Marggraf successfully isolates pure metallic zinc by reducing calamine mineral with charcoal in a closed vessel, describing the method in detail.",image:"images/elements/030_Zn/08_Andreas_Sigismund_Marggraf.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Zinc emission spectrum",text:"Emission spectrum — Spectral lines of Zinc (Zn) from the NIST Atomic Spectra Database.",image:"images/elements/030_Zn/15_30_(Zn_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","zn","30"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Zinc oxide sample",text:"Materials chemistry — A laboratory sample of zinc oxide (ZnO), a zinc compound with a direct semiconductor and materials-science role.",image:"images/elements/030_Zn/07_Zinc_oxide_sample.jpg",priority:"standard",display_context:"orbital",tags:["science","materials chemistry","Zn","30"],sources:[{label:"Wikimedia Commons — Zinc oxide sample",url:"https://commons.wikimedia.org/wiki/File:Zinc_oxide_sample.jpg"}]}],31:[{kind:"Portrait",title:"Gallium melting in a hand",text:"Physical form — Metallic gallium melting at body temperature in a hand. (element sample)",image:"images/elements/031_Ga/08_Gallium_melting_in_hand.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ga","31"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Gallium_melting_in_hand.jpg"}]},{kind:"Uses",title:"Gallium phosphide semiconductor wafer",text:"Practical application — Gallium phosphide (GaP) monocrystalline semiconductor wafer, used in fabricating green and yellow light-emitting diodes (LEDs). (semiconductor wafer)",image:"images/elements/031_Ga/05_GaP-wafer.jpg",priority:"core",display_context:"orbital",tags:["uses","Ga","31"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GaP-wafer.jpg"}]},{kind:"Science",title:"Gallium(III) nitrate formula diagram",text:"Scientific structure — Formula diagram showing a gallium(III) ion with nitrate anions; it is not a medical thermometer. (gallium compound)",image:"images/elements/031_Ga/09_Gallium_thermometer.png",priority:"standard",display_context:"orbital",tags:["science","Ga","31"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Gallium_thermometer.png"}]},{kind:"Safety",title:"Gallium nitrate chemical sample",text:"[Safety Warning] Pure gallium is non-toxic and safe to touch, but liquid gallium weds to glass and stains skin. Certain gallium salts (like gallium nitrate) are corrosive and irritants. Gallium must not come into contact with structural aluminium. (corrosion hazard)",image:"images/elements/031_Ga/10_Gallium_III__nitrate_hydrate.jpg",priority:"standard",display_context:"orbital",tags:["safety","Ga","31"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Gallium_III__nitrate_hydrate.jpg"}]},{kind:"History",title:"Gallium discovery timeline",text:"Key milestones of gallium: from Mendeleev's periodic law prediction to the spectroscopic discovery in France.",image:"images/elements/031_Ga/02_Paul-Émile_Lecoq_de_Boisbaudran.jpg",priority:"core",display_context:"orbital",tags:["history","Ga","31"],panel:{type:"timeline",items:[{year:"1869",title:"Dmitri Mendeleev predicts eka-aluminum",text:"Dmitri Mendeleev predicts the existence and properties of an element he calls 'eka-aluminum' below aluminum in his periodic table.",image:"images/elements/031_Ga/15_Mendeleev_1869_periodic_table.png"},{year:"1875",title:"Lecoq de Boisbaudran discovers gallium",text:"French chemist Paul-Émile Lecoq de Boisbaudran discovers gallium in sphalerite ore by spectroscopy, naming it Gallia (Latin for France) and isolating the metal by electrolysis.",image:"images/elements/031_Ga/02_Paul-Émile_Lecoq_de_Boisbaudran.jpg"}]},sources:[{label:"Wikimedia Commons — Mendeleev's 1869 periodic table",url:"https://commons.wikimedia.org/wiki/File:Mendeleev%27s_1869_periodic_table.png"}]},{kind:"Science",display_hint:"spectrum",title:"Gallium emission spectrum",text:"Emission spectrum — Spectral lines of Gallium (Ga) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Gallium in distant stars.",image:"images/elements/031_Ga/14_31_(Ga_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ga","31"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:31_%28Ga_I%29_NIST_ASD_emission_spectrum.png"}]}],32:[{kind:"Portrait",title:"Germanium polycrystalline chunk",text:"Physical state — Polycrystalline germanium chunk, showing a metallic grey color and bright luster. Germanium is a hard, brittle, lustrous metalloid belonging to the carbon group. (metalloid)",image:"images/elements/032_Ge/11_GermaniumUSGOV.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ge","32"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GermaniumUSGOV.jpg"}]},{kind:"Origin",title:"Argyrodite mineral crystal",text:"Natural occurrence — Argyrodite mineral crystal. Argyrodite (silver germanium sulfide, Ag₈GeS₆) is a rare mineral from which germanium was first discovered and isolated. (argyrodite mineral)",image:"images/elements/032_Ge/07_Argyrodite-rare08-2-80b.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ge","32"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Argyrodite-rare08-2-80b.jpg"}]},{kind:"Origin",title:"Germanite natural mineral specimen",text:"Natural occurrence — Germanite, a rare copper–iron–germanium sulfide mineral (Cu₂₆Fe₄Ge₄S₃₂). It occurs in hydrothermal ore deposits and is one of the minerals that directly contains germanium. (germanite mineral)",image:"images/elements/032_Ge/16_Germanite_natural_mineral.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ge","32"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Germanite-231229.jpg"}]},{kind:"Uses",title:"Vintage germanium transistor",text:"Practical application — Vintage germanium alloy junction transistor. Germanium was the semiconductor material used in the first transistors, launching the solid-state electronics era. (transistor)",image:"images/elements/032_Ge/09_Germanium_transistor.jpg",priority:"core",display_context:"orbital",tags:["uses","Ge","32"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Germanium_transistor.jpg"}]},{kind:"History",title:"Germanium discovery timeline",text:"Key milestones of germanium: from Mendeleev's eka-silicon prediction to Winkler's isolation of the element.",image:"images/elements/032_Ge/03_Clemens_Winkler.jpg",priority:"core",display_context:"orbital",tags:["history","Ge","32"],panel:{type:"timeline",items:[{year:"1869",title:"Dmitri Mendeleev predicts eka-silicon",text:"Dmitri Mendeleev predicts the existence of eka-silicon, predicting its atomic mass (~72), density, and chemical properties with high accuracy.",image:"images/elements/032_Ge/15_Mendeleev_1871_periodic_table.png"},{year:"1886",title:"Clemens Winkler isolates Germanium",text:"German chemist Clemens Winkler analyzes argyrodite mineral and isolates a new element, naming it Germanium after his homeland, confirming Mendeleev's predictions.",image:"images/elements/032_Ge/03_Clemens_Winkler.jpg"}]},sources:[{label:"Wikimedia Commons — Mendeleev's 1871 periodic table",url:"https://commons.wikimedia.org/wiki/File:Mendelejevs_periodiska_system_1871.png"}]},{kind:"Science",display_hint:"spectrum",title:"Germanium emission spectrum",text:"Emission spectrum — Spectral lines of Germanium (Ge) from the NIST Atomic Spectra Database.",image:"images/elements/032_Ge/14_32_(Ge_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","ge","32"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Germanium dichloride molecular model",text:"Molecular structure — Van der Waals sphere model of germanium dichloride (GeCl₂).",image:"images/elements/032_Ge/12_Germanium_dichloride_balls.png",priority:"standard",display_context:"orbital",tags:["science","molecular structure","Ge","32"],sources:[{label:"Wikimedia Commons — Germanium dichloride molecular model",url:"https://commons.wikimedia.org/wiki/File:Germanium_dichloride_balls.png"}]},{kind:"Safety",title:"Germanium compound and germane exposure warning",text:"[Safety Warning] Elemental germanium has low acute toxicity, but fine processing dust and several germanium compounds require exposure control. Germane (GeH₄), used in semiconductor processing, is highly toxic and flammable; use closed systems, ventilation, and appropriate respiratory protection. (compound hazard)",image:"images/elements/014_Si/07_GHS-pictogram-silhouette.svg",priority:"standard",display_context:"orbital",tags:["safety","Ge","32"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-silhouette.svg"}]}],33:[{kind:"Portrait",title:"Grey crystalline arsenic chunks",text:"Physical state — Grey crystalline arsenic chunks showing its metallic luster. Arsenic is a brittle metalloid that exists in several allotropic forms, grey arsenic being the most stable. (grey arsenic)",image:"images/elements/033_As/03_Arsenic__33_As_.jpg",priority:"core",display_context:"orbital",tags:["portrait","As","33"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Arsenic_(33_As).jpg"}]},{kind:"Origin",title:"Orpiment mineral specimen",text:"Natural occurrence — Orpiment (arsenic trisulfide, As₂S₃) specimen. A bright yellow-orange mineral historically used as a pigment and noted for its toxicity. (orpiment mineral)",image:"images/elements/033_As/06_Auripigment__Orpiment_.jpg",priority:"standard",display_context:"orbital",tags:["origin","As","33"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Auripigment_(Orpiment).jpg"}]},{kind:"Origin",title:"Realgar crystal specimen",text:"Natural occurrence — Realgar crystal specimen. Realgar (arsenic monosulfide, As₄S₄) is a red-orange sulfide mineral associated with geothermal activity and ores. (realgar mineral)",image:"images/elements/033_As/07_Realgar-229713.jpg",priority:"standard",display_context:"orbital",tags:["origin","As","33"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Realgar-229713.jpg"}]},{kind:"Uses",title:"Gallium arsenide semiconductor wafer",text:"Practical application — A polished gallium arsenide (GaAs) single-crystal wafer. GaAs enables high-frequency electronics, optical devices, and high-efficiency solar cells. (compound semiconductor)",image:"images/elements/033_As/17_Gallium_Arsenide_GaAs_wafer.jpg",priority:"core",display_context:"orbital",tags:["uses","As","33"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Gallium_Arsenide_(GaAs)_2%22_wafer.jpg"}]},{kind:"History",title:"Arsenic discovery timeline",text:"Key milestones of arsenic: from ancient toxic mineral pigments to its chemical isolation by Albertus Magnus.",image:"images/elements/033_As/02_Albertus_Magnus.jpg",priority:"core",display_context:"orbital",tags:["history","As","33"],panel:{type:"timeline",items:[{year:"c. 1250",title:"Albertus Magnus isolates arsenic",text:"German alchemist and bishop Albertus Magnus is credited with isolating elemental arsenic by heating arsenic trisulfide with soap.",image:"images/elements/033_As/02_Albertus_Magnus.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Arsenic emission spectrum",text:"Emission spectrum — Spectral lines of Arsenic (As) from the NIST Atomic Spectra Database.",image:"images/elements/033_As/15_33_(As_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","as","33"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Marsh test for arsenic",text:"Analytical chemistry — A laboratory Marsh test in progress. If arsenic is present, a reaction generates arsine gas; heating the gas deposits a dark arsenic mirror inside the narrow glass tube. It was one of the first sensitive forensic tests for arsenic.",image:"images/elements/033_As/16_Marsh_test_for_arsenic.jpg",priority:"standard",display_context:"orbital",tags:["science","analytical chemistry","forensics","arsenic test","33"],sources:[{label:"Wikimedia Commons — Marshsche Probe",url:"https://commons.wikimedia.org/wiki/File:Marshsche_Probe.jpg"}]}],34:[{kind:"Portrait",title:"Elemental selenium samples",text:"Physical state — Several pieces of elemental selenium from the SPŠCHBr collection, photographed on a laboratory watch glass. Their brittle, metallic-grey appearance is characteristic of selenium's stable grey allotrope.",image:"images/elements/034_Se/04_Elemental_selenium_samples_on_watch_glass.jpg",priority:"core",display_context:"orbital",tags:["portrait","Se","34"],sources:[{label:"Milda 444 · CC BY-SA 4.0 · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Selen2.jpg"}]},{kind:"Origin",title:"Native selenium crystals",text:"Natural occurrence — Native selenium crystals. Elemental selenium occurs naturally in volcanically active areas and hydrothermal veins, but is primarily extracted as a byproduct of copper refining. (native selenium)",image:"images/elements/034_Se/15_Native_selenium.jpg",priority:"standard",display_context:"orbital",tags:["origin","Se","34"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Native_selenium.jpg"}]},{kind:"Science",title:"Red vs black selenium allotropes",text:"Chemical properties — Red amorphous selenium powder alongside black vitreous selenium, demonstrating selenium's striking allotropic variations and colors. (allotropes)",image:"images/elements/034_Se/03_SeBlackRed.jpg",priority:"standard",display_context:"orbital",tags:["science","Se","34"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:SeBlackRed.jpg"}]},{kind:"Life",title:"Selenocysteine amino acid skeletal structure",text:"Biological role — Selenocysteine molecule. Known as the 21st amino acid, selenocysteine is essential in various selenoproteins that act as antioxidants in human cells. (amino acid)",image:"images/elements/034_Se/10_L-Selenocysteine-skeletal.png",priority:"standard",display_context:"orbital",tags:["life","Se","34"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:L-Selenocysteine-skeletal.svg"}]},{kind:"Uses",title:"Vintage selenium photocell",text:"Practical application — Vintage selenium photocell. Selenium's electrical conductivity increases under light exposure (photoconductivity), making it the foundation of early solar cells and xerography. (photocell)",image:"images/elements/034_Se/11_Selenium_photocell.jpg",priority:"core",display_context:"orbital",tags:["uses","Se","34"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Selenium_photocell.jpg"}]},{kind:"Uses",title:"Vintage selenium rectifier",text:"Practical application — Selenium rectifier stacks. Selenium rectifiers were used to convert alternating current (AC) to direct current (DC) in electronics before silicon diodes. (rectifier)",image:"images/elements/034_Se/06_Selenium_rectifier_red.jpg",priority:"standard",display_context:"orbital",tags:["uses","Se","34"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Selenium_rectifier_red.jpg"}]},{kind:"History",title:"Selenium discovery timeline",text:"Key milestones of selenium: from Jöns Jacob Berzelius' discovery to Moon-based nomenclature.",image:"images/elements/034_Se/23_Berzelius_daguerreotype.png",priority:"core",display_context:"orbital",tags:["history","Se","34"],panel:{type:"timeline",items:[{year:"1817",title:"Jöns Jacob Berzelius discovers selenium",text:"Swedish chemist Jöns Jacob Berzelius discovers selenium in sulfur residues from a sulfuric acid factory, naming it after Selene, the Greek goddess of the Moon.",image:"images/elements/034_Se/23_Berzelius_daguerreotype.png"},{year:"1817",title:"Nomenclature and properties",text:"Berzelius names the element after the Moon (Greek 'selene') due to its chemical similarity to tellurium, which is named after the Earth (Latin 'tellus').",image:"images/elements/034_Se/21_Selene_Louvre_altar.jpg"}]},sources:[{label:"Unknown photographer · Public domain · Wikimedia Commons — Berzelius daguerreotype",url:"https://commons.wikimedia.org/wiki/File:J%C3%B6ns_Jacob_Berzelius_daguerreotype.png"},{label:"Wikimedia Commons — Selene altar, Louvre",url:"https://commons.wikimedia.org/wiki/File:Altar_Selene_Louvre_Ma508.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Selenium emission spectrum",text:"Emission spectrum — Spectral lines of Selenium (Se) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition.",image:"images/elements/034_Se/20_34_(Se_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","se","34"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:34_%28Se_I%29_NIST_ASD_emission_spectrum.png"}]}],35:[{kind:"Portrait",title:"High-purity liquid bromine ampoule",text:"Physical state — A close view of 99.5% pure elemental bromine sealed in a small glass ampoule. Its nearly black liquid and dense orange-brown vapor are clearly visible without an element tile or display label. (liquid bromine)",image:"images/elements/035_Br/06_Bromine-ampoule.jpg",priority:"core",display_context:"orbital",tags:["portrait","Br","35"],sources:[{label:"Wikimedia Commons — Jurii (CC BY 3.0)",url:"https://commons.wikimedia.org/wiki/File:Bromine-ampoule.jpg"}]},{kind:"Origin",title:"Bromargyrite mineral specimen",text:"Natural occurrence — Bromargyrite mineral specimen. Bromargyrite (silver bromide, AgBr) is a rare halide mineral found in oxidized silver deposits, representing a natural source of bromine. (bromargyrite)",image:"images/elements/035_Br/09_Bromargyrite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Br","35"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Bromargyrite.jpg"}]},{kind:"Safety",title:"Bromine corrosive hazard label",text:"[Safety Warning] Liquid bromine is highly corrosive to human skin and organic tissues, causing deep, painful, and slow-healing burns. Bromine vapor is highly toxic and severely damages the respiratory system. (severe hazard)",image:"images/elements/035_Br/02_Bromine_hazard_label.svg",priority:"standard",display_context:"orbital",tags:["safety","Br","35"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Bromine_hazard_label.svg"}]},{kind:"History",title:"Bromine discovery timeline",text:"Key milestones of bromine: from Balard's discovery in France to its nomenclature based on stench.",image:"images/elements/035_Br/03_Antoine_Jérôme_Balard.jpg",priority:"core",display_context:"orbital",tags:["history","Br","35"],panel:{type:"timeline",items:[{year:"1826",title:"Antoine Jérôme Balard discovers bromine",text:"French chemist Antoine Jérôme Balard isolates bromine from seaweed ash and salt marsh brine, proving it is a new halogen element.",image:"images/elements/035_Br/03_Antoine_Jérôme_Balard.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Bromine emission spectrum",text:"Emission spectrum — Spectral lines of Bromine (Br) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Bromine in distant stars.",image:"images/elements/035_Br/14_35_(Br_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","br","35"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:35_%28Br_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Bromine-water reaction with tomato lycopene",text:"Reaction experiment — Bromine water reacts with lycopene in tomato juice in a fume cupboard, producing the visible colour gradients in the test tube. It is a real laboratory observation of bromine's addition chemistry with an unsaturated organic pigment. (bromination reaction)",image:"images/elements/035_Br/17_Bromination_of_tomato_juice.jpg",priority:"standard",display_context:"orbital",tags:["science","experiment","reaction","bromination","Br","35"],sources:[{label:"Wikimedia Commons — Bromination of Tomato juice (CC0, Martin Zapletal)",url:"https://commons.wikimedia.org/wiki/File:Bromination_of_Tomato_juice.jpg"}]}],36:[{kind:"Portrait",title:"Krypton gas discharge tube",text:"Physical state — A low-pressure krypton gas discharge tube glowing with a brilliant pale violet-white light under high voltage, demonstrating its characteristic atomic emission. (krypton discharge)",image:"images/elements/036_Kr/06_Krypton_discharge_tube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Kr","36"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Krypton_discharge_tube.jpg"}]},{kind:"Uses",title:"High-intensity krypton flash lamp",text:"Practical application — Krypton gas-filled photographic flash lamp. Due to its fast response and intense light emission, krypton is utilized in high-speed photography and airport runway lighting. (flash lamp)",image:"images/elements/036_Kr/08_Krypton_flash_lamp.jpg",priority:"core",display_context:"orbital",tags:["uses","Kr","36"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Krypton_flash_lamp.jpg"}]},{kind:"History",title:"Krypton discovery timeline",text:"Key milestones of krypton: from the spectroscopy of liquid air residues to its isolation as a new element.",image:"images/elements/036_Kr/14_William_Ramsay_in_laboratory.jpg",priority:"core",display_context:"orbital",tags:["history","Kr","36"],panel:{type:"timeline",items:[{year:"1898",title:"Sir William Ramsay and Morris Travers discover krypton",text:"Scottish chemist William Ramsay and English chemist Morris Travers isolate krypton in London by evaporating liquid air and analyzing the residue spectroscopic lines.",image:"images/elements/036_Kr/14_William_Ramsay_in_laboratory.jpg"}]},sources:[{label:"Wikimedia Commons · William Ramsay in his laboratory (no known restrictions)",url:"https://commons.wikimedia.org/wiki/File:Portrait_of_William_Ramsay_(1852-1916),_Chemist_(2551068777).jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Krypton emission spectrum",text:"Emission spectrum — Spectral lines of Krypton (Kr) from the NIST Atomic Spectra Database.",image:"images/elements/036_Kr/13_36_(Kr_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","kr","36"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Glowing ultrapure krypton",text:"Gas-discharge experiment — A vial of ultrapure krypton glowing under electrical excitation, demonstrating atomic emission.",image:"images/elements/036_Kr/11_Krypton-glow.jpg",priority:"standard",display_context:"orbital",tags:["science","gas discharge","Kr","36"],sources:[{label:"Wikimedia Commons — Krypton glow",url:"https://commons.wikimedia.org/wiki/File:Krypton-glow.jpg"}]},{kind:"Safety",title:"Compressed krypton and oxygen-displacement risk",text:"[Safety Warning] Krypton is chemically inert and non-toxic, but a large release can displace oxygen in a confined space without warning. Secure compressed-gas cylinders, use appropriate regulators, and provide ventilation or oxygen monitoring where a leak could accumulate. (compressed gas)",image:"images/elements/018_Ar/05_GHS-pictogram-bottle.svg",priority:"standard",display_context:"orbital",tags:["safety","Kr","36"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-bottle.svg"}]}],37:[{kind:"Portrait",title:"Pure rubidium metal in ampoule",text:"Physical state — Soft, silvery-white rubidium metal sealed inside a glass ampoule. Rubidium is an extremely reactive alkali metal with a very low melting point of 39.3°C. (rubidium metal)",image:"images/elements/037_Rb/11_Rubidium__Element_-_37_.jpg",priority:"core",display_context:"orbital",tags:["portrait","Rb","37"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Rubidium_Element_-_37.jpg"}]},{kind:"Origin",title:"Voloshinite mineral specimen",text:"Natural occurrence — Voloshinite, a rare rubidium-bearing mica mineral specimen. Rubidium does not form major mineral deposits and is obtained as a byproduct of lithium ores. (mineral byproduct)",image:"images/elements/037_Rb/10_Voloshinite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Rb","37"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Voloshinite.jpg"}]},{kind:"Science",title:"Rubidium flame test",text:"Emission spectrum — Excitation of rubidium ions in a flame yields a characteristic deep red-violet emission light, which led to its spectroscopic discovery. (flame test)",image:"images/elements/037_Rb/06_Rubidium_flame_test.jpg",priority:"standard",display_context:"orbital",tags:["science","Rb","37"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Rubidium_flame_test.jpg"}]},{kind:"Uses",title:"Rubidium atomic clock core",text:"Practical application — A rubidium atomic resonance frequency reference module, widely used in telecommunications, global positioning, and network synchronization. (atomic clock)",image:"images/elements/037_Rb/02_Rubidium_atomic_clock.jpg",priority:"core",display_context:"orbital",tags:["uses","Rb","37"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Rubidium_atomic_clock.jpg"}]},{kind:"History",title:"Rubidium discovery timeline",text:"Key milestones of rubidium: from its spectroscopic discovery in mineral water to its modern industrial applications.",image:"images/elements/037_Rb/09_Robert_Wilhelm_Bunsen.jpg",priority:"core",display_context:"orbital",tags:["history","Rb","37"],panel:{type:"timeline",items:[{year:"1861",title:"Robert Bunsen and Gustav Kirchhoff discover rubidium",text:"German chemists Robert Bunsen and Gustav Kirchhoff discover rubidium in Heidelberg by analyzing the emission spectrum of lepidolite mineral residues, identifying two bright red lines.",image:"images/elements/037_Rb/09_Robert_Wilhelm_Bunsen.jpg"},{year:"1861",title:"Nomenclature based on spectrum color",text:"They name the element Rubidium from the Latin word 'rubidus' (dark red) due to the distinct dark red lines in its emission spectrum.",image:"images/elements/037_Rb/13_Die_Flammenfärbung_des_Rubidium.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Rubidium emission spectrum",text:"Emission spectrum — Spectral lines of Rubidium (Rb) from the NIST Atomic Spectra Database.",image:"images/elements/037_Rb/14_37_(Rb_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","rb","37"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],38:[{kind:"Portrait",title:"Distilled dendritic strontium crystals",text:"Physical state — Silvery-yellow high-purity distilled dendritic strontium metal crystals. Strontium is a soft, reactive alkaline earth metal that quickly oxidizes in air. (strontium crystals)",image:"images/elements/038_Sr/09_Strontium_destilled_crystals.jpg",priority:"core",display_context:"orbital",tags:["portrait","Sr","38"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Strontium_destilled_crystals.jpg"}]},{kind:"Origin",title:"Madagascar celestine crystal cluster",text:"Natural occurrence — A stunning cluster of pale blue celestine (strontium sulfate, SrSO₄) crystals from Madagascar, the primary mineral source of strontium. (celestine mineral)",image:"images/elements/038_Sr/11_Celestine_-_Sakoany_deposit__Katsepy__Mitsinjo__Boeny__Madagascar.jpg",priority:"standard",display_context:"orbital",tags:["origin","Sr","38"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Celestine_-_Sakoany_deposit,_Katsepy,_Mitsinjo,_Boeny,_Madagascar.jpg"}]},{kind:"Science",title:"Strontium flame emission",text:"Emission spectrum — Excitation of strontium ions produces an intense crimson-red flame, commonly utilized in qualitative chemical analysis and pyrotechnics. (flame test)",image:"images/elements/038_Sr/06_FlammenfärbungSr.png",priority:"standard",display_context:"orbital",tags:["science","Sr","38"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Flammenf%C3%A4rbungSr.png"}]},{kind:"Safety",title:"High chemical reactivity hazard",text:"[Safety Warning] Strontium metal reacts vigorously with water and moisture to produce flammable hydrogen gas and highly alkaline strontium hydroxide. It must be stored under protective mineral oil or inert gas. (chemical reactivity)",image:"images/elements/038_Sr/05_Strontium_unter_Argon_Schutzgas_Atmosphäre.jpg",priority:"standard",display_context:"orbital",tags:["safety","Sr","38"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Strontium_unter_Argon_Schutzgas_Atmosph%C3%A4re.jpg"}]},{kind:"History",title:"Strontium discovery timeline",text:"Key milestones of strontium: from the discovery of strontianite mineral in Scotland to the isolation of the pure metal.",image:"images/elements/038_Sr/01_Adair_Crawford.jpg",priority:"core",display_context:"orbital",tags:["history","Sr","38"],panel:{type:"timeline",items:[{year:"1790",title:"Adair Crawford discovers strontium",text:"Scottish physician Adair Crawford analyzes a mineral from a lead mine in Strontian, Scotland, and determines it contains a new earth element, different from barium.",image:"images/elements/038_Sr/01_Adair_Crawford.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Strontium emission spectrum",text:"Emission spectrum — Spectral lines of Strontium (Sr) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Strontium in distant stars.",image:"images/elements/038_Sr/14_38_(Sr_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","sr","38"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:38_%28Sr_I%29_NIST_ASD_emission_spectrum.png"}]}],39:[{kind:"Portrait",title:"Sublimed dendritic yttrium metal and cube",text:"Physical state — Silvery-white sublimed dendritic yttrium metal chunk and a highly polished 1cm³ volume cube, showing high metallic luster. (yttrium metal)",image:"images/elements/039_Y/08_Yttrium_sublimed_dendritic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Y","39"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Yttrium_sublimed_dendritic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Xenotime mineral specimen",text:"Natural occurrence — Xenotime (yttrium phosphate, YPO₄) mineral specimen. It is a major mineral source mined commercially for yttrium and heavy rare-earth elements. (xenotime mineral)",image:"images/elements/039_Y/09_Xenotime-25410.jpg",priority:"standard",display_context:"orbital",tags:["origin","Y","39"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Xenotime-25410.jpg"}]},{kind:"Science",title:"Changesite-(Y) lunar mineral BSE image",text:"Geology — Backscattered electron (BSE) micrograph of Changesite-(Y), a phosphate mineral containing yttrium discovered in lunar basalt samples retrieved by the Chang'e 5 mission. (lunar mineral)",image:"images/elements/039_Y/10_BSE_images_of_changesite-_Y___a_.jpg",priority:"standard",display_context:"orbital",tags:["science","Y","39"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:BSE_images_of_changesite-(Y)_(a).jpg"}]},{kind:"Safety",title:"Yttrium dust handling precaution",text:"[Safety Warning] Yttrium metal in bulk is stable. However, finely divided yttrium powder or dust is highly flammable (pyrophoric) and represents a severe fire and dust explosion hazard. Inhalation of yttrium dust causes lung damage. (flammability warning)",image:"images/elements/022_Ti/04_GHS-pictogram-flamme.svg",priority:"standard",display_context:"orbital",tags:["safety","Y","39"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"History",title:"Yttrium discovery timeline",text:"Key milestones of yttrium: from Johan Gadolin's discovery in Sweden to its isolation as a distinct metal.",image:"images/elements/039_Y/02_Johan_Gadolin.jpg",priority:"core",display_context:"orbital",tags:["history","Y","39"],panel:{type:"timeline",items:[{year:"1794",title:"Johan Gadolin discovers yttrium",text:"Finnish chemist Johan Gadolin discovers a new metal oxide in a black mineral from a quarry in Ytterby, Sweden, which is later named 'yttria'.",image:"images/elements/039_Y/02_Johan_Gadolin.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Yttrium emission spectrum",text:"Emission spectrum — Spectral lines of Yttrium (Y) from the NIST Atomic Spectra Database.",image:"images/elements/039_Y/12_39_(Y_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","y","39"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],40:[{kind:"Portrait",title:"High-purity zirconium crystal bar and cube",text:"Physical state — Lustrous silvery high-purity zirconium metal crystal bar and a polished 1cm³ volume cube. Zirconium is highly resistant to corrosion and heat. (zirconium metal)",image:"images/elements/040_Zr/08_Zirconium_crystal_bar_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Zr","40"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Zirconium_crystal_bar_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Zircon mineral crystal",text:"Natural occurrence — A reddish-brown zircon (zirconium silicate, ZrSiO₄) mineral crystal. Zircon is an exceptionally durable mineral used widely in radiometric geochronology. (zircon crystal)",image:"images/elements/040_Zr/09_Zircon-176217.jpg",priority:"standard",display_context:"orbital",tags:["origin","Zr","40"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Zircon-176217.jpg"}]},{kind:"Safety",title:"Zirconium powder handling precaution",text:"[Safety Warning] Bulk zirconium metal is highly corrosion-resistant and bio-inert. However, fine zirconium shavings, powder, or filings are pyrophoric, igniting spontaneously in air and creating explosive dust clouds. (pyrophoric hazard)",image:"images/elements/022_Ti/04_GHS-pictogram-flamme.svg",priority:"standard",display_context:"orbital",tags:["safety","Zr","40"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"History",title:"Zirconium discovery timeline",text:"Key milestones of zirconium: from Klaproth's analysis of zircon mineral to its reduction in Sweden.",image:"images/elements/040_Zr/04_Martin_Heinrich_Klaproth.jpg",priority:"core",display_context:"orbital",tags:["history","Zr","40"],panel:{type:"timeline",items:[{year:"1789",title:"Martin Heinrich Klaproth discovers zirconium oxide",text:"German chemist Martin Heinrich Klaproth analyzes zircon mineral and discovers a new oxide he names 'zirconia'.",image:"images/elements/040_Zr/04_Martin_Heinrich_Klaproth.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Zirconium emission spectrum",text:"Emission spectrum — Spectral lines of Zirconium (Zr) from the NIST Atomic Spectra Database.",image:"images/elements/040_Zr/14_40_(Zr_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","zr","40"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Zirconium(IV) chloride crystal structure",text:"Crystal structure — Ball-and-stick model of part of the zirconium(IV) chloride (ZrCl₄) crystal structure.",image:"images/elements/040_Zr/16_Zirconium_tetrachloride_crystal_structure.png",priority:"standard",display_context:"orbital",tags:["science","crystal structure","Zr","40"],sources:[{label:"Wikimedia Commons — Zirconium(IV) chloride crystal structure",url:"https://commons.wikimedia.org/wiki/File:Zirconium-tetrachloride-3D-balls-A.png"}]},{kind:"Uses",title:"Cubic zirconia gemstone",text:"Materials application — A faceted cubic zirconia gemstone, made from stabilized zirconium dioxide (ZrO₂). (zirconia)",image:"images/elements/040_Zr/02_Zirconium_dioxide_sample.jpg",priority:"standard",display_context:"orbital",tags:["uses","gemstone","zirconia","Zr","40"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Yellow_cubic_zirconia.JPG"}]}],41:[{kind:"Portrait",title:"Niobium crystals and cube",text:"Physical state — Lustrous silvery niobium metal crystals and a polished 1cm³ volume cube. Niobium is a soft, ductile transition metal that turns blue when oxidized. (niobium metal)",image:"images/elements/041_Nb/06_Niobium_crystals_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Nb","41"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Niobium_crystals_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Columbite mineral ore",text:"Natural occurrence — Columbite mineral specimen, an iron-manganese niobium oxide. Columbite is the historical source mineral from which niobium was first identified. (columbite)",image:"images/elements/041_Nb/08_Columbit.jpg",priority:"standard",display_context:"orbital",tags:["origin","Nb","41"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Columbit.jpg"}]},{kind:"Uses",title:"Niobium-tin superconductor wire coil",text:"Practical application — Niobium-tin (Nb₃Sn) superconducting wire coil. Niobium-based alloys are critical in superconducting magnets for MRI machines and particle accelerators. (superconductors)",image:"images/elements/041_Nb/07_Niobium-tin_wire.jpg",priority:"core",display_context:"orbital",tags:["uses","Nb","41"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Niobium-tin_wire.jpg"}]},{kind:"Safety",title:"Niobium shavings safety warning",text:"[Safety Warning] Elemental niobium in bulk form is highly biocompatible and physiologically inert. However, niobium metal dust or fine shavings can cause eye and respiratory tract irritation. Standard dust protection is recommended. (dust safety)",image:"images/elements/041_Nb/02_Niobium_dust_irritant_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Nb","41"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Niobium discovery timeline",text:"Key milestones of niobium: from Hatchett's discovery of columbium to Rose's confirmation and naming.",image:"images/elements/041_Nb/11_Charles_Hatchett_Wellcome_etching.jpg",priority:"core",display_context:"orbital",tags:["history","Nb","41"],panel:{type:"timeline",items:[{year:"1801",title:"Charles Hatchett discovers columbium",text:"English chemist Charles Hatchett analyzes a mineral specimen from America in the British Museum, discovering a new element he names 'columbium' (Cb).",image:"images/elements/041_Nb/11_Charles_Hatchett_Wellcome_etching.jpg"},{year:"1844",title:"Heinrich Rose names the element Niobium",text:"German chemist Heinrich Rose proves columbium is a mixture and renames the element Niobium, after Niobe, the daughter of Tantalus, due to its chemical similarity to tantalum.",image:"images/elements/041_Nb/13_Niobe_Jacques_Louis_David.jpg"}]},sources:[{label:"Wellcome Collection via Wikimedia Commons · Charles Hatchett etching (CC BY 4.0)",url:"https://commons.wikimedia.org/wiki/File:Charles_Hatchett._Soft-ground_etching_by_F._C._Lewis_after_T_Wellcome_V0002614_(cropped).jpg"},{label:"Dallas Museum of Art via Wikimedia Commons — Niobe, Jacques-Louis David",url:"https://commons.wikimedia.org/wiki/File:Niobe_JacquesLouisDavid_1772_Dallas_Museum_of_Art.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Niobium emission spectrum",text:"Emission spectrum — Spectral lines of Niobium (Nb) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Niobium in distant stars.",image:"images/elements/041_Nb/12_41_(Nb_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","nb","41"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:41_%28Nb_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Niobium dioxide crystal structure",text:"Crystal structure — A structural model of niobium dioxide (NbO₂), showing the ordered niobium–oxygen framework in this transition-metal oxide.",image:"images/elements/041_Nb/14_Niobium_dioxide_crystal_structure.png",priority:"standard",display_context:"orbital",tags:["science","Nb","41"],sources:[{label:"Wikimedia Commons — Crystal structure of niobium dioxide (NbO₂)",url:"https://commons.wikimedia.org/wiki/File:Crystal_structure_of_niobium_dioxide_(NbO₂).png"}]}],42:[{kind:"Portrait",title:"Molybdenum crystalline fragment and cube",text:"Physical state — Silvery-grey high-purity crystalline molybdenum metal fragment and a polished 1cm³ volume cube. Molybdenum is a highly refractory metal with a very high melting point. (molybdenum metal)",image:"images/elements/042_Mo/06_Molybdenum_crystaline_fragment_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Mo","42"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Molybdenum_crystaline_fragment_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Molybdenite mineral specimen",text:"Natural occurrence — Molybdenite (molybdenum disulfide, MoS₂) specimen. Molybdenite is the primary commercial ore of molybdenum, closely resembling graphite. (molybdenite)",image:"images/elements/042_Mo/08_Molybdenite-155356.jpg",priority:"standard",display_context:"orbital",tags:["origin","Mo","42"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Molybdenite-155356.jpg"}]},{kind:"Science",title:"Molybdenum trioxide crystal structure",text:"Chemical properties — 3D molecular crystal structure model of molybdenum trioxide (MoO₃), an important industrial chemical intermediate and precursor. (molybdenum oxide)",image:"images/elements/042_Mo/11_Molybdenum_VI_-oxide.png",priority:"standard",display_context:"orbital",tags:["science","Mo","42"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Molybdenum_VI_-oxide.png"}]},{kind:"Safety",title:"Molybdenum compound handling precaution",text:"[Safety Warning] Molybdenum trioxide (MoO₃) is harmful if swallowed, causes serious eye irritation, and is suspected of causing cancer. Handling must be performed under strict ventilation controls. (toxicity warning)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Mo","42"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Molybdenum discovery timeline",text:"Key milestones of molybdenum: from Scheele's identification in molybdenite to Hjelm's reduction of the metal.",image:"images/elements/042_Mo/04_Carl_Wilhelm_Scheele.jpg",priority:"core",display_context:"orbital",tags:["history","Mo","42"],panel:{type:"timeline",items:[{year:"1778",title:"Carl Wilhelm Scheele discovers molybdenum",text:"Swedish chemist Carl Wilhelm Scheele proves that molybdenite is not graphite and contains a distinct mineral acid element, which he names molybdenum.",image:"images/elements/042_Mo/04_Carl_Wilhelm_Scheele.jpg"},{year:"1781",title:"Peter Jacob Hjelm isolates the metal",text:"Swedish chemist Peter Jacob Hjelm successfully isolates metallic molybdenum by reducing molybdenum oxide with carbon (charcoal).",image:"images/elements/042_Mo/09_Molybdite-Molybdenite-233200.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Molybdenum emission spectrum",text:"Emission spectrum — Spectral lines of Molybdenum (Mo) from the NIST Atomic Spectra Database.",image:"images/elements/042_Mo/12_42_(Mo_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","mo","42"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],43:[{kind:"Portrait",title:"Technetium-99 sample in a sealed ampoule",text:"Physical sample — Technetium-99 powder electroplated onto a 6 × 1 mm gold foil and sealed in an argon-filled glass ampoule. It is a genuine elemental technetium specimen, protected because technetium is radioactive. (sealed Tc-99 sample)",image:"images/elements/043_Tc/10_Technetium_sample_sealed_ampoule.jpg",priority:"core",display_context:"orbital",tags:["portrait","Tc","43"],sources:[{label:"Wikimedia Commons — Technetium sample cropped (Marco Cardin, CC BY-SA 4.0)",url:"https://commons.wikimedia.org/wiki/File:Technetium-sample-cropped.jpg"}]},{kind:"Uses",title:"Sodium pertechnetate injection vial",text:"Practical application — Medical injection vial containing sterile sodium pertechnetate (Na[⁹⁹ᵐTc]O₄) solution, a clinical form used in nuclear medicine. It is a technetium compound, not an elemental technetium sample. (injection vial)",image:"images/elements/043_Tc/02_Sodium_pertechnetate_vial.jpg",priority:"core",display_context:"orbital",tags:["uses","Tc","43"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sodium_pertechnetate_vial.jpg"}]},{kind:"Science",title:"Technetium-99m decay chart",text:"Nuclear production — Activity chart of a technetium-99m generator (moly cow), showing the decay of molybdenum-99 (⁹⁹Mo) to produce short-lived technetium-99m. (decay chart)",image:"images/elements/043_Tc/07_Technetium-99m_Generator_Tc-99m-Contend_verus_Time.svg",priority:"standard",display_context:"orbital",tags:["science","Tc","43"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Technetium-99m_Generator_Tc-99m-Contend_verus_Time.svg"}]},{kind:"Safety",title:"Radioactivity hazard warning",text:"[Safety Warning] Technetium is a radioactive hazard. All handling requires specialized radiological shielding, personal dosimetry, and strict contamination protocols. Under no circumstances should it be inhaled or ingested. (radioactive hazard)",image:"images/elements/043_Tc/01_Technetium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Tc","43"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Technetium_radiation_warning.svg"}]},{kind:"History",title:"Technetium discovery timeline",text:"Key milestones of technetium: from Mendeleev's periodic prediction to its physical synthesis in Italy.",image:"images/elements/043_Tc/04_Emilio_Segrè.jpg",priority:"core",display_context:"orbital",tags:["history","Tc","43"],panel:{type:"timeline",items:[{year:"1937",title:"Emilio Segrè and Carlo Perrier synthesize technetium",text:"Italian physicists Emilio Segrè and Carlo Perrier discover technetium in Palermo by analyzing a molybdenum foil bombarded with deuterons in a cyclotron.",image:"images/elements/043_Tc/04_Emilio_Segrè.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Technetium emission spectrum",text:"Emission spectrum — Spectral lines of Technetium (Tc) from the NIST Atomic Spectra Database.",image:"images/elements/043_Tc/09_43_(Tc_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","tc","43"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],44:[{kind:"Portrait",title:"Ruthenium metal half bar",text:"Physical state — Hard, brittle silvery-white ruthenium metal bar chunk. Ruthenium is a rare transition metal belonging to the platinum group metals (PGMs). (ruthenium metal)",image:"images/elements/044_Ru/06_Ruthenium_a_half_bar.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ru","44"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Ruthenium_a_half_bar.jpg"}]},{kind:"Origin",title:"Platinum group metal ore",text:"Natural occurrence — Platinum ore specimen. Ruthenium occurs naturally in trace quantities alloyed with other platinum-group metals in nickel-copper sulfide ores. (platinum ore)",image:"images/elements/044_Ru/05_Platinum_ore.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ru","44"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Platinum_ore.jpg"}]},{kind:"Science",title:"Ruthenium tetroxide chemical model",text:"Chemical properties — Molecular structure model of ruthenium tetroxide (RuO₄), a highly volatile and toxic yellow crystalline oxide compound of ruthenium. (ruthenium tetroxide)",image:"images/elements/044_Ru/02_Ruthenium_tetroxide.svg",priority:"standard",display_context:"orbital",tags:["science","Ru","44"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Ruthenium_tetroxide.svg"}]},{kind:"History",title:"Ruthenium discovery timeline",text:"Key milestones of ruthenium: from the discovery of platinum residues to Karl Ernst Claus' isolation.",image:"images/elements/044_Ru/04_Karl_Ernst_Claus.jpg",priority:"core",display_context:"orbital",tags:["history","Ru","44"],panel:{type:"timeline",items:[{year:"1844",title:"Karl Ernst Claus discovers ruthenium",text:"Russian chemist Karl Ernst Claus isolates ruthenium from platinum residues at Kazan State University, showing it represents a distinct new chemical element.",image:"images/elements/044_Ru/04_Karl_Ernst_Claus.jpg"},{year:"1844",title:"Naming in honor of Russia",text:"Claus names the element Ruthenium in honor of Russia (Latin 'Ruthenia'), as the raw platinum group minerals he investigated originated from the Ural Mountains.",image:"images/elements/044_Ru/10_Russia_map_late_16c.jpg"}]},sources:[{label:"Wikimedia Commons — late-16th-century map of Russia",url:"https://commons.wikimedia.org/wiki/File:The_map_of_Russia,_late_16_c.,_Holland.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Ruthenium emission spectrum",text:"Emission spectrum — Spectral lines of Ruthenium (Ru) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Ruthenium in distant stars.",image:"images/elements/044_Ru/09_44_(Ru_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ru","44"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:44_%28Ru_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Safety",title:"Volatile ruthenium tetroxide hazard",text:"[Safety Warning] Ruthenium metal is comparatively inert, but ruthenium tetroxide (RuO₄) is a volatile, strongly oxidizing compound that can severely damage eyes, skin, and the respiratory tract. Handle reactive ruthenium compounds only in a suitable fume hood with chemical-resistant protection. (oxidizing compound)",image:"images/elements/009_F/05_GHS-pictogram-acid.svg",priority:"standard",display_context:"orbital",tags:["safety","Ru","44"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-acid.svg"}]}],45:[{kind:"Portrait",title:"High-purity rhodium metal bead",text:"Physical state — A highly reflective, silvery-white 1-gram pure rhodium metal bead. Rhodium is an extremely rare, hard, and corrosion-resistant transition metal. (rhodium bead)",image:"images/elements/045_Rh/05_Pure_rhodium_bead__1_gram._Original_size_in_cm_-_0.5.jpg",priority:"core",display_context:"orbital",tags:["portrait","Rh","45"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Pure_rhodium_bead__1_gram._Original_size_in_cm_-_0.5.jpg"}]},{kind:"Origin",title:"Platinum-group sulfide ore",text:"Natural source — Rhodium occurs at trace levels with other platinum-group metals in sulfide ore bodies. This platinum-palladium-rich sulfide ore from the Stillwater Complex illustrates the geological host from which rhodium is recovered as a refining byproduct.",image:"images/elements/045_Rh/13_Stillwater_platinum_group_ore.jpg",priority:"standard",display_context:"orbital",tags:["origin","Rh","45"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sulfidic_bronzitite_(platinum-palladium_ore)_Stillwater_Mine_MT.jpg"}]},{kind:"Safety",title:"Rhodium compound handling precaution",text:"[Safety Warning] Rhodium metal in bulk is inert. However, rhodium compounds (such as rhodium trichloride, RhCl₃) are toxic, suspected of causing genetic defects, and cause severe skin and eye damage. (chemical hazard)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Rh","45"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Rhodium discovery timeline",text:"Key milestones of rhodium: from Wollaston's analysis of crude platinum ore to its naming.",image:"images/elements/045_Rh/14_William_Hyde_Wollaston_portrait.jpg",priority:"core",display_context:"orbital",tags:["history","Rh","45"],panel:{type:"timeline",items:[{year:"1803",title:"William Hyde Wollaston discovers rhodium",text:"English chemist William Hyde Wollaston discovers rhodium in London by dissolving crude platinum ore in aqua regia and neutralizing it with sodium hydroxide.",image:"images/elements/045_Rh/14_William_Hyde_Wollaston_portrait.jpg"}]},sources:[{label:"Wikimedia Commons · William Hyde Wollaston portrait (CC BY-SA 4.0)",url:"https://commons.wikimedia.org/wiki/File:William_Hyde_Wollaston,_portrait.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Rhodium emission spectrum",text:"Emission spectrum — Spectral lines of Rhodium (Rh) from the NIST Atomic Spectra Database.",image:"images/elements/045_Rh/10_45_(Rh_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","rh","45"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Rhodium trichloride crystal structure",text:"Crystal structure — Unit-cell and extended structural models of rhodium trichloride (RhCl₃).",image:"images/elements/045_Rh/15_Rhodium_trichloride_structure.png",priority:"standard",display_context:"orbital",tags:["science","Rh","45"],sources:[{label:"Wikimedia Commons — Rhodium trichloride structure",url:"https://commons.wikimedia.org/wiki/File:Rhodium_trichloride_structure.png"}]}],46:[{kind:"Portrait",title:"Pure palladium metal chunk",text:"Physical state — Lustrous silvery-white chunk of pure palladium metal. Palladium is a soft, ductile platinum-group metal that is highly resistant to corrosion. (palladium chunk)",image:"images/elements/046_Pd/05_Palladium__46_Pd_.jpg",priority:"core",display_context:"orbital",tags:["portrait","Pd","46"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Palladium__46_Pd_.jpg"}]},{kind:"Origin",title:"Stillwater mine platinum-palladium ore",text:"Natural occurrence — A massive chalcopyrite-pyrrhotite mineral ore specimen rich in platinum-group metals from the famous Stillwater Complex in Montana, USA. (palladium ore)",image:"images/elements/046_Pd/10_Massive_sulfide__Pt-Pd-rich_chalcopyrite-pyrrhotite__Stillwater_mine_MT.jpg",priority:"standard",display_context:"orbital",tags:["origin","Pd","46"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Massive_sulfide__Pt-Pd-rich_chalcopyrite-pyrrhotite__Stillwater_mine_MT.jpg"}]},{kind:"Science",title:"Palladium-hydrogen absorption structure",text:"Chemical properties — Lattice structure model showing palladium's ability to absorb up to 900 times its own volume of hydrogen gas, forming palladium hydride. (hydrogen absorption)",image:"images/elements/046_Pd/08_Palladium-hydrogen.jpg",priority:"standard",display_context:"orbital",tags:["science","Pd","46"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Palladium-hydrogen.jpg"}]},{kind:"Safety",title:"Palladium compound handling precaution",text:"[Safety Warning] Palladium metal is stable. However, soluble palladium compounds (like palladium chloride, PdCl₂) are toxic, cause serious eye damage, and are skin sensitizers. Proper protection is required. (handling safety)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Pd","46"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Palladium discovery timeline",text:"Key milestones of palladium: from Wollaston's analysis of platinum residues to its naming after an asteroid.",image:"images/elements/046_Pd/14_William_Hyde_Wollaston_Wellcome_pen_drawing.jpg",priority:"core",display_context:"orbital",tags:["history","Pd","46"],panel:{type:"timeline",items:[{year:"1802",title:"William Hyde Wollaston discovers palladium",text:"English chemist William Hyde Wollaston isolates palladium in London from crude platinum ore, publishing his discovery anonymously before revealing himself.",image:"images/elements/046_Pd/14_William_Hyde_Wollaston_Wellcome_pen_drawing.jpg"},{year:"1802",title:"Naming after asteroid Pallas",text:"Wollaston names the element Palladium after the asteroid Pallas, which was discovered just two months prior and named after the Greek goddess of wisdom.",image:"images/elements/046_Pd/15_Pallas_VLT_2024.png"}]},sources:[{label:"Wellcome Collection via Wikimedia Commons · William Hyde Wollaston pen drawing (CC BY 4.0)",url:"https://commons.wikimedia.org/wiki/File:William_Hyde_Wollaston._Pen_drawing._Wellcome_V0006362ER.jpg"},{label:"Wikimedia Commons — Pallas VLT images",url:"https://commons.wikimedia.org/wiki/File:Pallas_VLT_images_-_Vermersch_et_al._2024.png"}]},{kind:"Science",display_hint:"spectrum",title:"Palladium emission spectrum",text:"Emission spectrum — Spectral lines of Palladium (Pd) from the NIST Atomic Spectra Database.",image:"images/elements/046_Pd/12_46_(Pd_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","pd","46"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],47:[{kind:"Portrait",title:"Electrolytic silver crystal",text:"Physical state — A brilliant, highly detailed dendritic silver metal crystal grown slowly via electrolysis. Silver has the highest electrical conductivity of any metal. (silver crystal)",image:"images/elements/047_Ag/06_Silver_crystal.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ag","47"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Silver_crystal.jpg"}]},{kind:"Origin",title:"Acanthite mineral specimen",text:"Natural occurrence — Acanthite (silver sulfide, Ag₂S) mineral specimen. Acanthite is the most important natural mineral ore mined for silver extraction. (acanthite ore)",image:"images/elements/047_Ag/08_Acanthite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ag","47"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Acanthite.jpg"}]},{kind:"Science",title:"Light-sensitive silver chloride precipitate",text:"Chemical properties — Silver chloride (AgCl) precipitate suspended in water, which undergoes rapid photolysis to metallic silver under exposure to light, the foundation of chemical photography. (photochemistry)",image:"images/elements/047_Ag/02_Silver_chloride_sample.jpg",priority:"standard",display_context:"orbital",tags:["science","Ag","47"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Silver_chloride_sample.jpg"}]},{kind:"Uses",title:"Silver bullion coins",text:"Practical application — Silver bullion coins, a direct use of silver as a precious metal for investment and coinage. (silver coinage)",image:"images/elements/047_Ag/05_Silver_coin.jpg",priority:"core",display_context:"orbital",tags:["uses","Ag","47"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Silver_coin.jpg"}]},{kind:"Safety",title:"Silver nitrate stains on skin",text:"[Safety Warning] Silver nitrate (AgNO₃) can severely irritate or burn skin and eyes, and leaves characteristic dark stains on exposed skin. Handle solutions with suitable protection. (silver nitrate hazard)",image:"images/elements/047_Ag/01_Silver_nitrate_warning.jpg",priority:"standard",display_context:"orbital",tags:["safety","Ag","47"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Silver_nitrate_stains.jpg"}]},{kind:"History",title:"Ancient silver coins",text:"Key milestones of silver: from prehistoric native silver smelting to its status as one of the seven metals of antiquity.",image:"images/elements/047_Ag/04_Ancient_silver_coins.jpg",priority:"core",display_context:"orbital",tags:["history","Ag","47"],panel:{type:"timeline",items:[{year:"Antiquity",title:"Silver utilized as a metal of antiquity",text:"Silver is known since prehistoric times. It was one of the seven metals of antiquity, widely mined and refined in ancient Anatolia, Greece, and Rome for currency.",image:"images/elements/047_Ag/04_Ancient_silver_coins.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Silver emission spectrum",text:"Emission spectrum — Spectral lines of Silver (Ag) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Silver in distant stars.",image:"images/elements/047_Ag/12_47_(Ag_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ag","47"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:47_%28Ag_I%29_NIST_ASD_emission_spectrum.png"}]}],48:[{kind:"Portrait",title:"Crystalline cadmium metal bar",text:"Physical state — Lustrous silvery crystalline cadmium metal bar. Cadmium is a soft, bluish-white transition metal that is highly malleable and ductile, closely resembling zinc. (cadmium metal)",image:"images/elements/048_Cd/07_Cadmium-crystal_bar.jpg",priority:"core",display_context:"orbital",tags:["portrait","Cd","48"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Cadmium-crystal_bar.jpg"}]},{kind:"Origin",title:"Greenockite mineral specimen",text:"Natural occurrence — Greenockite, a rare natural cadmium sulfide (CdS) mineral. Cadmium is primarily obtained commercially as a byproduct of zinc ore refining. (greenockite)",image:"images/elements/048_Cd/09_Greenockite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Cd","48"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Greenockite.jpg"}]},{kind:"Science",title:"Glowing CdTe quantum dots",text:"Chemical properties — Vials of cadmium telluride (CdTe) quantum dots fluorescing under ultraviolet light. The emission color shifts across the spectrum due to quantum confinement. (quantum dots)",image:"images/elements/048_Cd/06_CdTe_quantum_dots.jpg",priority:"standard",display_context:"orbital",tags:["science","Cd","48"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:CdTe_quantum_dots.jpg"}]},{kind:"Safety",title:"Cadmium toxicity hazard label",text:"[Safety Warning] Cadmium is highly toxic. It causes organ damage, is a carcinogen, and is extremely hazardous to aquatic environments. Ingestion causes Itai-itai disease (severe bone softening). (heavy metal toxicity)",image:"images/elements/048_Cd/02_Cadmium_hazard_label.svg",priority:"standard",display_context:"orbital",tags:["safety","Cd","48"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Cadmium_hazard_label.svg"}]},{kind:"History",title:"Cadmium discovery timeline",text:"Key milestones of cadmium: from the discovery of impurities in zinc carbonate to its isolation as a distinct metal.",image:"images/elements/048_Cd/05_Friedrich_Stromeyer.jpg",priority:"core",display_context:"orbital",tags:["history","Cd","48"],panel:{type:"timeline",items:[{year:"1817",title:"Friedrich Stromeyer discovers cadmium",text:"German chemist Friedrich Stromeyer discovers cadmium in Göttingen while examining an impurity in zinc carbonate (calamine), which turned yellow upon heating.",image:"images/elements/048_Cd/05_Friedrich_Stromeyer.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Cadmium emission spectrum",text:"Emission spectrum — Spectral lines of Cadmium (Cd) from the NIST Atomic Spectra Database.",image:"images/elements/048_Cd/12_48_(Cd_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","cd","48"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],49:[{kind:"Portrait",title:"Pure indium metal bar",text:"Physical state — A highly lustrous, silvery-white pure indium metal bar. Indium is so soft that it can be easily cut with a knife and makes a high-pitched 'cry' when bent. (indium metal)",image:"images/elements/049_In/06_In_49.jpg",priority:"core",display_context:"orbital",tags:["portrait","In","49"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:In_49.jpg"}]},{kind:"Origin",title:"Sphalerite zinc-sulfide ore",text:"Natural source — Indium rarely forms its own minerals. It substitutes in zinc sulfide minerals such as sphalerite and is recovered as a trace byproduct during zinc refining.",image:"images/elements/049_In/13_Sphalerite_Harz_indium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","In","49"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:33Sphalerit_harz_hg.jpg"}]},{kind:"Safety",title:"Indium compound handling precaution",text:"[Safety Warning] Elemental indium is of low toxicity. However, indium compounds (such as indium phosphide, InP) are highly toxic and suspected carcinogens. Inhalation of indium dust causes pulmonary disease. (toxic compounds)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","In","49"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Indium discovery timeline",text:"Key milestones of indium: from the spectroscopic analysis of zinc ores to its naming after its indigo line.",image:"images/elements/049_In/05_Ferdinand_Reich.jpg",priority:"core",display_context:"orbital",tags:["history","In","49"],panel:{type:"timeline",items:[{year:"1863",title:"Ferdinand Reich and Theodor Richter discover indium",text:"German chemists Ferdinand Reich and Hieronymous Theodor Richter discover indium in Freiberg by analyzing the emission spectrum of zinc blend ores, identifying a bright indigo-blue line.",image:"images/elements/049_In/05_Ferdinand_Reich.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Indium emission spectrum",text:"Emission spectrum — Spectral lines of Indium (In) from the NIST Atomic Spectra Database.",image:"images/elements/049_In/10_49_(In_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","in","49"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Indium crystal unit cell",text:"Crystal structure — Structural model of the unit cell of metallic indium.",image:"images/elements/049_In/14_Indium_unit_cell_structure.png",priority:"standard",display_context:"orbital",tags:["science","In","49"],sources:[{label:"Wikimedia Commons — Indium unit cell",url:"https://commons.wikimedia.org/wiki/File:Indium_uc.png"}]}],50:[{kind:"Portrait",title:"Alpha vs Beta tin allotropes",text:"Physical state — Lustrous metallic beta-tin alongside crumbling grey alpha-tin, demonstrating the allotropic phase transition of tin. (allotropy)",image:"images/elements/050_Sn/06_Sn-Alpha-Beta.jpg",priority:"core",display_context:"orbital",tags:["portrait","Sn","50"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sn-Alpha-Beta.jpg"}]},{kind:"Origin",title:"Cassiterite mineral specimen",text:"Natural occurrence — Cassiterite (tin dioxide, SnO₂), a heavy, dark brown oxide mineral that represents the primary geological ore of tin. (cassiterite ore)",image:"images/elements/050_Sn/09_Cassiterite-291597.jpg",priority:"standard",display_context:"orbital",tags:["origin","Sn","50"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Cassiterite-291597.jpg"}]},{kind:"Science",title:"Alpha- and beta-tin crystal-structure diagram",text:"Scientific structure — Diagram comparing the crystal structures of alpha-tin and beta-tin, the allotropes involved in the low-temperature phase transformation known as tin pest. (phase transition)",image:"images/elements/050_Sn/04_Tin_pest.jpg",priority:"standard",display_context:"orbital",tags:["science","Sn","50"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Tin_pest.jpg"}]},{kind:"Safety",title:"Tin compound handling precaution",text:"[Safety Warning] Inorganic tin metal is non-toxic and biocompatible. However, soluble tin salts (such as tin chloride) are corrosive irritants. Organotin compounds are highly toxic environmental pollutants. (chemical safety)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Sn","50"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Bronze Age tin ingot",text:"Key milestones of tin: from prehistoric smelting and the Bronze Age to modern alloy technologies.",image:"images/elements/050_Sn/05_Bronze_Age_tin_ingot.jpg",priority:"core",display_context:"orbital",tags:["history","Sn","50"],panel:{type:"timeline",items:[{year:"Antiquity",title:"Smelting of tin and bronze",text:"Tin is one of the seven metals of antiquity. Around 3000 BC, early metallurgists discover that alloying copper with tin produces bronze, initiating the Bronze Age.",image:"images/elements/050_Sn/05_Bronze_Age_tin_ingot.jpg"},{year:"1914–1918",title:"Industrial tinplate production",text:"A worker pickles tin in a South Wales tin factory during the First World War, documenting industrial-scale tinplate production.",image:"images/elements/050_Sn/14_WWI_South_Wales_tin_factory.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Tin emission spectrum",text:"Emission spectrum — Spectral lines of Tin (Sn) from the NIST Atomic Spectra Database.",image:"images/elements/050_Sn/13_50_(Sn_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","sn","50"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],51:[{kind:"Portrait",title:"Crystalline metallic antimony chunk",text:"Physical state — Lustrous, highly crystalline, and brittle metallic antimony chunk, showing a silvery-blue sheen. Antimony is a typical metalloid. (antimony chunk)",image:"images/elements/051_Sb/05_Antimony-4.jpg",priority:"core",display_context:"orbital",tags:["portrait","Sb","51"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Antimony-4.jpg"}]},{kind:"Origin",title:"Needle-like stibnite mineral crystals",text:"Natural occurrence — Striking needle-like grey crystals of stibnite (antimony trisulfide, Sb₂S₃), which is the primary natural ore source of antimony. (stibnite mineral)",image:"images/elements/051_Sb/06_Stibnite__Antimony_sulphide__-_geograph.org.uk_-_633878.jpg",priority:"standard",display_context:"orbital",tags:["origin","Sb","51"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Stibnite_Antimony_sulphide_-_geograph.org.uk_-_633878.jpg"}]},{kind:"Science",title:"Antimony trichloride crystals",text:"Chemical properties — Crystalline antimony trichloride (SbCl₃), demonstrating the halogen compounds of antimony. (chemical crystals)",image:"images/elements/051_Sb/03_Antimony_trichloride_solid.jpeg",priority:"standard",display_context:"orbital",tags:["science","Sb","51"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Antimony_trichloride_solid.jpeg"}]},{kind:"Uses",title:"Movable type metal letters",text:"Practical application — Movable type metal letters. Antimony is alloyed with lead and tin to make type metal because it expands slightly upon cooling, ensuring crisp print definitions. (alloys)",image:"images/elements/051_Sb/08_Type_metal.jpg",priority:"core",display_context:"orbital",tags:["uses","Sb","51"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Type_metal.jpg"}]},{kind:"Safety",title:"Antimony trioxide carcinogen warning",text:"[Safety Warning] Antimony and its compounds are toxic, resembling arsenic. Antimony trioxide dust is toxic by inhalation, causes severe skin irritation, and is a suspected carcinogen. (toxicity warning)",image:"images/elements/051_Sb/01_Antimony_trioxide_hazard.png",priority:"standard",display_context:"orbital",tags:["safety","Sb","51"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Antimony_trioxide_hazard.png"}]},{kind:"History",title:"Antimony history timeline",text:"Key milestones of antimony: from ancient stibnite cosmetic liners to alchemical treatises and modern flame retardants.",image:"images/elements/051_Sb/09_Barite-Stibnite-tmu27c.jpg",priority:"core",display_context:"orbital",tags:["history","Sb","51"],panel:{type:"timeline",items:[{year:"Antiquity",title:"Stibnite used as kohl cosmetic",text:"Ancient Egyptians and Middle Eastern civilizations utilize finely powdered stibnite mineral (kohl) as a black eye cosmetic and medicine.",image:"images/elements/051_Sb/09_Barite-Stibnite-tmu27c.jpg"},{year:"c. 1500",title:"Basil Valentine describes antimony metallurgy",text:"Alchemical author Basil Valentine publishes 'The Triumphal Chariot of Antimony', detailing the preparation of metallic antimony and its chemical compounds.",image:"images/elements/051_Sb/02_Basil_Valentine.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Antimony emission spectrum",text:"Emission spectrum — Spectral lines of Antimony (Sb) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Antimony in distant stars.",image:"images/elements/051_Sb/13_51_(Sb_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","sb","51"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:51_%28Sb_I%29_NIST_ASD_emission_spectrum.png"}]}],52:[{kind:"Portrait",title:"Crystalline tellurium metalloid chunk",text:"Physical state — Highly lustrous, silvery-white crystalline tellurium metalloid chunk. Tellurium is a brittle, relatively rare metalloid showing semiconductor properties. (tellurium chunk)",image:"images/elements/052_Te/07_Tellurium2.jpg",priority:"core",display_context:"orbital",tags:["portrait","Te","52"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Tellurium2.jpg"}]},{kind:"Origin",title:"Calaverite gold telluride mineral",text:"Natural occurrence — Calaverite (gold telluride, AuTe₂) mineral specimen. Tellurium is one of the few elements that readily forms minerals alloyed with gold in nature. (calaverite)",image:"images/elements/052_Te/08_Calaverite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Te","52"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Calaverite.jpg"}]},{kind:"Safety",title:"Tellurium handling precaution",text:"[Safety Warning] Tellurium is harmful if inhaled or swallowed. Ingestion leads to the synthesis of dimethyl telluride, causing a strong, persistent, garlic-like breath and sweat odor (tellurium breath). (chemical hazard)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Te","52"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Tellurium discovery timeline",text:"Key milestones of tellurium: from Transylvanian gold ores to its naming after Earth.",image:"images/elements/052_Te/03_Franz-Joseph_Müller_von_Reichenstein.jpg",priority:"core",display_context:"orbital",tags:["history","Te","52"],panel:{type:"timeline",items:[{year:"1782",title:"Franz-Joseph Müller von Reichenstein discovers tellurium",text:"Austrian mineralogist Franz-Joseph Müller von Reichenstein discovers tellurium in gold ores from Transylvania, identifying it as a new distinct metal.",image:"images/elements/052_Te/03_Franz-Joseph_Müller_von_Reichenstein.jpg"},{year:"1798",title:"Martin Heinrich Klaproth names tellurium",text:"German chemist Martin Heinrich Klaproth isolates the element and names it Tellurium from the Latin word 'tellus' (Earth).",image:"images/elements/052_Te/11_Martin_Heinrich_Klaproth_Tardieu.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Tellurium emission spectrum",text:"Emission spectrum — Spectral lines of Tellurium (Te) from the NIST Atomic Spectra Database.",image:"images/elements/052_Te/09_52_(Te_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","te","52"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Telluride-precursor powder TEM micrograph",text:"Electron microscopy — TEM micrograph of a powder prepared from a NaHTeNH₃ sample using H₂Te as the telluride-ion precursor; the scale bar is 100 nm.",image:"images/elements/052_Te/04_Fig1-TEM-micrography-of-a-powder-obtained-from-NaHTeNH-3-sample-using-H-2-Te-as-telluride-ion-precursor.jpg",priority:"standard",display_context:"orbital",tags:["science","Te","52"],sources:[{label:"Wikimedia Commons — TEM micrograph of telluride-precursor powder",url:"https://commons.wikimedia.org/wiki/File:Fig1-TEM-micrography-of-a-powder-obtained-from-NaHTeNH-3-sample-using-H-2-Te-as-telluride-ion-precursor.jpg"}]}],53:[{kind:"Portrait",title:"Dark violet iodine crystals",text:"Physical state — Lustrous, dark violet-black crystalline iodine flakes showing a metallic sheen. As a nonmetal halogen, iodine is a solid under standard conditions. (iodine crystals)",image:"images/elements/053_I/05_Iodine_crystals.jpg",priority:"core",display_context:"orbital",tags:["portrait","I","53"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Iodine_crystals.jpg"}]},{kind:"Origin",title:"Iodargyrite mineral specimen",text:"Natural occurrence — Iodargyrite (silver iodide, AgI) mineral specimen, a natural iodide source found in oxidized silver mineral deposits. (iodargyrite mineral)",image:"images/elements/053_I/08_Iodargyrite-263859.jpg",priority:"standard",display_context:"orbital",tags:["origin","I","53"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Iodargyrite-263859.jpg"}]},{kind:"Science",title:"Gaseous iodine sublimation in flask",text:"Chemical properties — Solid iodine subliming directly into a dense, brilliant violet gas when heated in a glass flask, demonstrating its low-temperature phase transition. (sublimation)",image:"images/elements/053_I/06_Iodine_sublimation.jpg",priority:"standard",display_context:"orbital",tags:["science","I","53"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Iodine_sublimation.jpg"}]},{kind:"Safety",title:"Iodine corrosive hazard label",text:"[Safety Warning] Elemental iodine is corrosive. Contact causes skin burns and severe eye irritation, and the vapor is highly irritating to the lungs. It is also highly toxic to aquatic life. (corrosive halogen)",image:"images/elements/053_I/02_Iodine_hazard_label.svg",priority:"standard",display_context:"orbital",tags:["safety","I","53"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Iodine_hazard_label.svg"}]},{kind:"History",title:"Iodine discovery timeline",text:"Key milestones of iodine: from French seaweed ash residues to the identification of its chemical properties.",image:"images/elements/053_I/03_Bernard_Courtois.jpg",priority:"core",display_context:"orbital",tags:["history","I","53"],panel:{type:"timeline",items:[{year:"1811",title:"Bernard Courtois discovers iodine",text:"French chemist Bernard Courtois discovers iodine in seaweed ash residue while extracting sodium and potassium compounds, noticing a violet vapor when adding acid.",image:"images/elements/053_I/03_Bernard_Courtois.jpg"},{year:"1813",title:"Joseph Louis Gay-Lussac defines it as an element",text:"French chemist Joseph Louis Gay-Lussac names the element Iodine from the Greek word 'ioeides' (violet-colored) due to the color of its vapor.",image:"images/elements/053_I/14_Gay_Lussac_MET_medallion.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Iodine emission spectrum",text:"Emission spectrum — Spectral lines of Iodine (I) from the NIST Atomic Spectra Database.",image:"images/elements/053_I/10_53_(I_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","i","53"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]}],54:[{kind:"Portrait",title:"Xenon discharge blue-violet glow",text:"Physical state — A low-pressure xenon gas discharge tube glowing with a beautiful, bright blue-violet color under high voltage. (discharge glow)",image:"images/elements/054_Xe/04_Post-processed_xenon_discharge_tube_cropped.jpg",priority:"core",display_context:"orbital",tags:["portrait","Xe","54"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Post-processed_xenon_discharge_tube_cropped.jpg"}]},{kind:"Uses",title:"Compressed xenon gas cylinder",text:"Industrial handling — Compressed xenon gas cylinder. Xenon is recovered from liquid air by fractional distillation and supplied for lamps, propulsion, and research. (compressed gas)",image:"images/elements/054_Xe/01_Xenon_gas_cylinder.png",priority:"standard",display_context:"orbital",tags:["uses","Xe","54"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Xenon_gas_cylinder.png"}]},{kind:"Science",title:"Xenon gas discharge tube experiment",text:"Emission spectrum — Gaseous xenon discharge tube experiment. Xenon has a highly complex visible emission spectrum, generating a daylight-like white light when pressurized. (discharge emission)",image:"images/elements/054_Xe/06_Xenon_discharge.jpg",priority:"standard",display_context:"orbital",tags:["science","Xe","54"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Xenon_discharge.jpg"}]},{kind:"History",title:"Xenon discovery timeline",text:"Key milestones of xenon: from Ramsay's discovery in London to its naming as the stranger gas.",image:"images/elements/054_Xe/02_William_Ramsay.jpg",priority:"core",display_context:"orbital",tags:["history","Xe","54"],panel:{type:"timeline",items:[{year:"1898",title:"William Ramsay and Morris Travers discover xenon",text:"British chemists Sir William Ramsay and Morris Travers discover xenon by analyzing residues of liquefied atmospheric air.",image:"images/elements/054_Xe/02_William_Ramsay.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Xenon emission spectrum",text:"Emission spectrum — Spectral lines of Xenon (Xe) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Xenon in distant stars.",image:"images/elements/054_Xe/12_54_(Xe_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","xe","54"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:54_%28Xe_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Safety",title:"Compressed xenon and oxygen-displacement risk",text:"[Safety Warning] Xenon is chemically inert and non-toxic, but it is stored under pressure and can displace oxygen in enclosed areas. Secure cylinders, use compatible regulators, and ventilate spaces where a large release could accumulate. (compressed gas)",image:"images/elements/018_Ar/05_GHS-pictogram-bottle.svg",priority:"standard",display_context:"orbital",tags:["safety","Xe","54"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-bottle.svg"}]}],55:[{kind:"Portrait",title:"High-purity cesium crystals",text:"Physical state — High-purity elemental cesium crystallized into bright, dendritic metallic forms inside a sealed glass ampoule. The close view shows the metal itself rather than a labeled display cube. (cesium crystals)",image:"images/elements/055_Cs/16_High_purity_cesium_dendritic_crystals.JPG",priority:"core",display_context:"orbital",tags:["portrait","Cs","55"],sources:[{label:"Wikimedia Commons — Dnn87 (CC BY 3.0)",url:"https://commons.wikimedia.org/wiki/File:CsCrystals1.JPG"}]},{kind:"Origin",title:"Pollucite cesium mineral",text:"Natural source — Pollucite is a cesium-rich aluminosilicate mineral and the principal ore used to produce cesium compounds and metal.",image:"images/elements/055_Cs/14_Pollucite_cesium_mineral.jpg",priority:"standard",display_context:"orbital",tags:["origin","Cs","55"],sources:[{label:"U.S. Geological Survey · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Pollucite(CesiumMineral)USGOV.jpg"}]},{kind:"Safety",title:"Cesium explosive water reaction",text:"[Safety Warning] Cesium metal is extremely hazardous. It reacts explosively with water and ice even down to -116°C, igniting hydrogen gas spontaneously and shattering glass containment vessels. (explosive hazard)",image:"images/elements/055_Cs/01_Caesium_and_water.png",priority:"standard",display_context:"orbital",tags:["safety","Cs","55"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Caesium_and_water.png"}]},{kind:"History",title:"Cesium discovery timeline",text:"Key milestones of cesium: from the first spectroscopic discovery in mineral water to the definition of the second.",image:"images/elements/055_Cs/15_Bunsen_Kirchhoff_Roscoe_1862.jpg",priority:"core",display_context:"orbital",tags:["history","Cs","55"],panel:{type:"timeline",items:[{year:"1860",title:"Robert Bunsen and Gustav Kirchhoff discover cesium",text:"German chemists Robert Bunsen and Gustav Kirchhoff discover cesium in Dürkheim mineral water residues by detecting sky-blue lines in its emission spectrum.",image:"images/elements/055_Cs/15_Bunsen_Kirchhoff_Roscoe_1862.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Bunsen,_Kirchhoff,_and_Roscoe_-_DPLA_-_0d1cd667019095a1892406b6bf446a68.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Caesium emission spectrum",text:"Emission spectrum — Spectral lines of Caesium (Cs) from the NIST Atomic Spectra Database.",image:"images/elements/055_Cs/13_55_(Cs_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","cs","55"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"NIST cesium fountain atomic clock",text:"Precision measurement — NIST researchers operate a cesium fountain clock, which measures the cesium-133 hyperfine transition used to define the SI second.",image:"images/elements/055_Cs/02_Cesium_fountain_clock.jpg",priority:"core",display_context:"orbital",tags:["science","Cs","55"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Cesium_fountain_clock.jpg"}]}],56:[{kind:"Portrait",title:"Barium metal in a sealed tube",text:"Physical form — Fresh silvery barium metal kept in a sealed glass tube. Barium tarnishes quickly in air as its reactive surface forms a dark oxide layer.",image:"images/elements/056_Ba/12_Barium_metal_in_sealed_tube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ba","56"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Barium_(Element_-_56)_2.jpg"}]},{kind:"Origin",title:"Barite mineral specimen",text:"Natural occurrence — Barite (barium sulfate, BaSO₄) mineral specimen. Barite is the most abundant natural mineral source mined commercially for barium extraction. (barite ore)",image:"images/elements/056_Ba/09_Barite-232754.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ba","56"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Barite-232754.jpg"}]},{kind:"Safety",title:"Barium compound toxic hazard",text:"[Safety Warning] Soluble barium compounds (such as barium chloride) are highly toxic cardiac poisons. Pure barium metal is highly flammable, reacts with water, and must be stored under protective mineral oil. (toxicity warning)",image:"images/elements/056_Ba/01_Barium_soluble_compound_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Ba","56"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-skull.svg"}]},{kind:"History",title:"Barium discovery timeline",text:"Key milestones of barium: from ancient barite (Bologna stone) studies to Humphry Davy's electrochemical isolation.",image:"images/elements/056_Ba/02_Humphry_Davy.jpg",priority:"core",display_context:"orbital",tags:["history","Ba","56"],panel:{type:"timeline",items:[{year:"1774",title:"Carl Wilhelm Scheele identifies barium oxide",text:"Swedish chemist Carl Wilhelm Scheele determines that barite contains a new distinct mineral earth element, which he names 'baryta'.",image:"images/elements/056_Ba/14_Scheele_commemorative_medal_1789.jpg"},{year:"1808",title:"Humphry Davy isolates barium metal",text:"English chemist Humphry Davy isolates metallic barium in London by electrolyzing a mixture of moist barium hydroxide and mercuric oxide.",image:"images/elements/056_Ba/02_Humphry_Davy.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Humphry_Davy.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Barium emission spectrum",text:"Emission spectrum — Spectral lines of Barium (Ba) from the NIST Atomic Spectra Database.",image:"images/elements/056_Ba/11_56_(Ba_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","ba","56"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Barium bromide crystal structure",text:"Crystal structure — Space-filling model of the 3 × 3 × 3 unit-cell packing in barium bromide (BaBr₂), based on a reported powder X-ray diffraction structure.",image:"images/elements/056_Ba/13_Barium_bromide_crystal_structure.png",priority:"standard",display_context:"orbital",tags:["science","Ba","56"],sources:[{label:"Wikimedia Commons — Barium bromide crystal packing",url:"https://commons.wikimedia.org/wiki/File:Barium-bromide-xtal-packing-3x3x3-3D-sf.png"}]}],57:[{kind:"Portrait",title:"Silvery lanthanum metal chunks",text:"Physical state — Lustrous, silvery-grey pure lanthanum metal pieces. Lanthanum is the prototype element of the lanthanide series, showing rapid oxidation in air. (lanthanum pieces)",image:"images/elements/057_La/05_Lanthanum-2.jpg",priority:"core",display_context:"orbital",tags:["portrait","La","57"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Lanthanum-2.jpg"}]},{kind:"Origin",title:"Monazite mineral crystal",text:"Natural occurrence — Monazite-Ce crystal, a rare-earth phosphate mineral that serves as a major commercial source for lanthanum extraction. (monazite ore)",image:"images/elements/057_La/09_Monazite-Ce.jpg",priority:"standard",display_context:"orbital",tags:["origin","La","57"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Monazite-Ce.jpg"}]},{kind:"Uses",title:"Ferrocerium lighter flint sparking",text:"Practical application — Sparking ferrocerium lighter flint. Lanthanum is alloyed with cerium and iron to make pyrophoric ferrocerium flints for lighters and fire starters. (lighter flint)",image:"images/elements/057_La/03_Ferrocerium_lighter_flint.jpg",priority:"core",display_context:"orbital",tags:["uses","La","57"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Ferrocerium_lighter_flint.jpg"}]},{kind:"Safety",title:"Lanthanum powder handling precaution",text:"[Safety Warning] Lanthanum metal is highly flammable in powder form. It reacts with water and moisture to produce flammable hydrogen gas. Soluble lanthanum salts are mild irritants. (handling safety)",image:"images/elements/022_Ti/04_GHS-pictogram-flamme.svg",priority:"standard",display_context:"orbital",tags:["safety","La","57"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"History",title:"Lanthanum discovery timeline",text:"Key milestones of lanthanum: from Mosander's isolation of a hidden oxide to its naming.",image:"images/elements/057_La/08_Carl_Gustaf_Mosander.jpg",priority:"core",display_context:"orbital",tags:["history","La","57"],panel:{type:"timeline",items:[{year:"1839",title:"Carl Gustaf Mosander discovers lanthanum",text:"Swedish chemist Carl Gustaf Mosander discovers lanthanum in Stockholm as an impurity in a cerium nitrate sample, isolating it as a new oxide.",image:"images/elements/057_La/08_Carl_Gustaf_Mosander.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Lanthanum emission spectrum",text:"Emission spectrum — Spectral lines of Lanthanum (La) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Lanthanum in distant stars.",image:"images/elements/057_La/10_57_(La_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","la","57"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:57_%28La_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Lanthanum(III) sulfate structure",text:"Chemical structure — Structural formula showing lanthanum(III) ions and sulfate groups in lanthanum(III) sulfate.",image:"images/elements/057_La/11_Lanthanum_sulfate_structure.png",priority:"standard",display_context:"orbital",tags:["science","La","57"],sources:[{label:"Wikimedia Commons — Lanthanum(III) sulfate",url:"https://commons.wikimedia.org/wiki/File:Lanthanum_(III)_sulfate.png"}]}],58:[{kind:"Portrait",title:"Silvery-grey cerium metal chunk",text:"Physical form — A lustrous, silvery-grey pure metallic cerium chunk. Cerium is the most abundant of the rare-earth elements, closely resembling iron. (cerium metal)",image:"images/elements/058_Ce/05_Cerium_metal.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ce","58"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Cerium_metal.jpg"}]},{kind:"Origin",title:"Monazite from Antsirabé, Madagascar",text:"Natural occurrence — Monazite is a rare-earth phosphate mineral and the principal natural source of cerium. This specimen formed naturally in the Ankaratra Mountains of Madagascar.",image:"images/elements/058_Ce/13_Monazite_Antsirabe_cerium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ce","58"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Monazit_-_Antsirab%C3%A9,_Ankaratra-Gebirge,_Madagaskar,_S%C3%BCdostafrika.jpg"}]},{kind:"Safety",title:"Pyrophoric cerium metal sparks",text:"[Safety Warning] Cerium metal is highly pyrophoric. Scraping or filing cerium metal creates friction heat that ignites the filings, producing brilliant sparks. Powdered cerium is a severe fire hazard. (pyrophoric warning)",image:"images/elements/058_Ce/01_Cerium_pyrophoric_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Ce","58"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-flamme.svg"}]},{kind:"History",title:"Cerium discovery timeline",text:"Key milestones of cerium: from Berzelius' discovery to the isolation of the pure metal.",image:"images/elements/058_Ce/14_Wilhelm_Hisinger_1827_relief.jpg",priority:"core",display_context:"orbital",tags:["history","Ce","58"],panel:{type:"timeline",items:[{year:"1803",title:"Jöns Jacob Berzelius and Wilhelm Hisinger discover cerium",text:"Swedish chemists Jöns Jacob Berzelius and Wilhelm Hisinger independently discover cerium oxide in a heavy mineral from Bastnäs, Sweden.",image:"images/elements/058_Ce/14_Wilhelm_Hisinger_1827_relief.jpg"},{year:"1803",title:"Naming after asteroid Ceres",text:"They name the element Cerium after the newly discovered asteroid Ceres, which was spotted in 1801 by Giuseppe Piazzi.",image:"images/elements/058_Ce/15_Ceres_in_color.png"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Wilhelm_Hisinger_SPA.jpg"},{label:"NASA/JPL-Caltech/UCLA/MPS/DLR/IDA via Wikimedia Commons — Ceres in color",url:"https://commons.wikimedia.org/wiki/File:Ceres_in_color.png"}]},{kind:"Science",display_hint:"spectrum",title:"Cerium emission spectrum",text:"Emission spectrum — Spectral lines of Cerium (Ce) from the NIST Atomic Spectra Database.",image:"images/elements/058_Ce/12_58_(Ce_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","ce","58"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Cerium(III) fluoride crystal structure",text:"Crystal structure — Three-dimensional model of cerium(III) fluoride (CeF₃).",image:"images/elements/058_Ce/16_Cerium_fluoride_crystal_structure.png",priority:"standard",display_context:"orbital",tags:["science","Ce","58"],sources:[{label:"Wikimedia Commons — Cerium(III) fluoride crystal structure",url:"https://commons.wikimedia.org/wiki/File:Cerium(III)-fluoride-xtal-3D-bs-17.png"}]}],59:[{kind:"Portrait",title:"Silvery praseodymium metal pieces",text:"Physical state — Lustrous, silvery-grey praseodymium metal pieces. Praseodymium oxidizes slowly in air, forming a green oxide layer. (praseodymium pieces)",image:"images/elements/059_Pr/09_Praseodymium.jpg",priority:"core",display_context:"orbital",tags:["portrait","Pr","59"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Praseodymium.jpg"}]},{kind:"Origin",title:"Monazite rare-earth mineral",text:"Natural source — Praseodymium occurs as a minor rare-earth constituent of phosphate minerals such as monazite. These minerals are processed together to separate individual rare-earth elements.",image:"images/elements/059_Pr/13_Monazite_Evje_praseodymium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Pr","59"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Monazit,_Evje,_Norwegen.jpg"}]},{kind:"Safety",title:"Praseodymium compound handling precaution",text:"[Safety Warning] Praseodymium metal dust is flammable. Soluble praseodymium compounds (such as chloride and nitrate salts) are skin and eye irritants. Handling requires standard protection. (irritant warning)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Pr","59"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:GHS-pictogram-exclam.svg"}]},{kind:"History",title:"Praseodymium discovery timeline",text:"Key milestones of praseodymium: from the alchemical substance didymium to Carl Auer's successful separation in Vienna.",image:"images/elements/059_Pr/02_Carl_Auer_von_Welsbach.jpg",priority:"core",display_context:"orbital",tags:["history","Pr","59"],panel:{type:"timeline",items:[{year:"1885",title:"Carl Auer von Welsbach discovers praseodymium",text:"Austrian chemist Carl Auer von Welsbach discovers praseodymium in Vienna by separation of didymium oxide into two distinct colored earth oxides.",image:"images/elements/059_Pr/02_Carl_Auer_von_Welsbach.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Praseodymium emission spectrum",text:"Emission spectrum — Spectral lines of Praseodymium (Pr) from the NIST Atomic Spectra Database.",image:"images/elements/059_Pr/12_59_(Pr_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","pr","59"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Praseodymium spark spectrum",text:"Spectroscopic measurement — A recorded praseodymium spark spectrum across the visible range.",image:"images/elements/059_Pr/14_Praseodymium_spark_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","Pr","59"],sources:[{label:"Wikimedia Commons — Praseodymium spectrum",url:"https://commons.wikimedia.org/wiki/File:Praseodymium_spectrum.png"}]}],60:[{kind:"Portrait",title:"Lustrous neodymium metal chunk",text:"Physical state — Lustrous, silvery neodymium metal pieces showing golden surface oxidation. Neodymium is a highly reactive lanthanide. (neodymium metal)",image:"images/elements/060_Nd/07_Neodymium2.jpg",priority:"core",display_context:"orbital",tags:["portrait","Nd","60"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Neodymium2.jpg"}]},{kind:"Origin",title:"Bastnaesite mineral specimen",text:"Natural occurrence — Bastnäsite mineral specimen. Bastnäsite is a major fluorocarbonate mineral source mined extensively for neodymium extraction. (bastnaesite)",image:"images/elements/060_Nd/14_Bastnaesite__GeoDIL_number_-_821_.jpg",priority:"standard",display_context:"orbital",tags:["origin","Nd","60"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Bastnaesite_GeoDIL_number_-_821.jpg"}]},{kind:"Uses",title:"Neodymium magnet spheres",text:"Practical application — Extremely powerful NdFeB (Neodymium-Iron-Boron) magnet spheres lifting heavy metal loads, demonstrating outstanding magnetic energy density. (neodymium magnet)",image:"images/elements/060_Nd/05_Neodymium_magnet_lifting_spheres.jpg",priority:"core",display_context:"orbital",tags:["uses","Nd","60"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Neodymium_magnet_lifting_spheres.jpg"}]},{kind:"Safety",title:"Neodymium magnet ball grid",text:"[Safety Warning] Powerful neodymium magnetic spheres can pinch skin. Loose small magnets also pose a severe ingestion hazard, especially when more than one is swallowed. (magnet safety)",image:"images/elements/060_Nd/01_Neodymium_magnet_warning.jpg",priority:"standard",display_context:"orbital",tags:["safety","Nd","60"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Neodymium_Magnet_Ball_Grid.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Neodymium emission spectrum",text:"Emission spectrum — Spectral lines of Neodymium (Nd) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Neodymium in distant stars.",image:"images/elements/060_Nd/15_60_(Nd_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","nd","60"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:60_%28Nd_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Nd:YAG laser rod",text:"Laser material — A neodymium-doped yttrium aluminium garnet (Nd:YAG) rod, the gain medium used in solid-state lasers.",image:"images/elements/060_Nd/11_Nd-YAG_rod.jpg",priority:"standard",display_context:"orbital",tags:["science","Nd","60"],sources:[{label:"Wikimedia Commons — Nd:YAG laser",url:"https://commons.wikimedia.org/wiki/File:Nd-YAG_laser.JPG"}]}],61:[{kind:"Portrait",title:"Encapsulated promethium-147 source",text:"Verified isotope sample — A close view of the sealed source identified in the accompanying collection as containing promethium-147. The radioactive material remains encapsulated; the photograph does not claim that the visible metal parts are bulk promethium. (Pm-147 source)",image:"images/elements/061_Pm/11_Promethium147_encapsulated_source_closeup.jpg",priority:"core",display_context:"orbital",tags:["portrait","sample","radioactive","Pm","61"],sources:[{label:"Wikimedia Commons — James St. John (CC BY 2.0)",url:"https://commons.wikimedia.org/wiki/File:Promethium_(Element_-_61)_3.jpg"}]},{kind:"History",title:"Oak Ridge National Laboratory",text:"Synthesis history — Oak Ridge National Laboratory, where promethium was first synthesized and isolated from nuclear fission products in 1945. (laboratory synthesis)",image:"images/elements/061_Pm/03_Oak_Ridge_National_Laboratory.jpg",priority:"standard",display_context:"orbital",tags:["history","Pm","61"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Safety",title:"Radioactive radiation warning sign",text:"[Safety Warning] Promethium compounds emit beta particles, necessitating shielding to prevent exposure and bremsstrahlung secondary X-rays. (radioactive risk)",image:"images/elements/061_Pm/01_Promethium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Pm","61"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Promethium discovery timeline",text:"Key milestones of promethium: from fission product isolation to the nuclear fire Titan naming.",image:"images/elements/061_Pm/07_Jacob_A_Marinsky.jpg",priority:"core",display_context:"orbital",tags:["history","Pm","61"],panel:{type:"timeline",items:[{year:"1945",title:"Jacob A. Marinsky and Lawrence E. Glendenin isolate promethium",text:"American chemists Jacob A. Marinsky, Lawrence E. Glendenin, and Charles D. Coryell first isolate promethium at Oak Ridge National Laboratory by analyzing uranium fission products.",image:"images/elements/061_Pm/07_Jacob_A_Marinsky.jpg"},{year:"1947",title:"Discovery announcement and naming",text:"The discovery is officially announced, and the element is named after Prometheus, the Titan from Greek mythology who stole fire from heaven, symbolizing its synthesis from nuclear fire.",image:"images/elements/061_Pm/08_Lawrence_E_Glendenin.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Promethium emission spectrum",text:"Emission spectrum — Spectral lines of Promethium (Pm) from the NIST Atomic Spectra Database.",image:"images/elements/061_Pm/09_61_(Pm_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","pm","61"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Rare-earth spectral comparison",text:"Comparative spectroscopy — A Pm-labelled vial appears among the rare-earth samples above the discharge-spectrum comparison. The lower spectra are a multi-element reference, not a claim that one trace is promethium alone.",image:"images/elements/061_Pm/06_The_Rare_Earth_Elements_and_Their_Spectra.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Pm","61"],sources:[{label:"Wikimedia Commons — The Rare Earth Elements and Their Spectra",url:"https://commons.wikimedia.org/wiki/File:The_Rare_Earth_Elements_and_Their_Spectra.png"}]}],62:[{kind:"Portrait",title:"Silvery samarium metal sample",text:"Physical state — Silvery-grey samarium metal sample under mineral oil. Samarium is a moderately hard lanthanide that oxidizes slowly in air. (samarium metal)",image:"images/elements/062_Sm/05_Samarium-2.jpg",priority:"core",display_context:"orbital",tags:["portrait","Sm","62"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Samarium-2.jpg"}]},{kind:"Origin",title:"Monazite from Kalkfeld, Namibia",text:"Natural occurrence — Samarium is recovered alongside other lanthanides from phosphate minerals such as monazite. This large natural monazite specimen is from Kalkfeld, Namibia.",image:"images/elements/062_Sm/14_Monazite_Kalkfeld_samarium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Sm","62"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Monazit_-_Kalkfeld,_Namibia.jpg"}]},{kind:"Safety",title:"Samarium compound handling precaution",text:"[Safety Warning] Soluble samarium salts are eye and skin irritants, while samarium metal dust presents a moderate fire and explosion hazard. (chemical warning)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Sm","62"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Samarium discovery timeline",text:"Key milestones of samarium: from Paris spectroscopic detection to the first element named after a person.",image:"images/elements/062_Sm/15_Samarskite_GeoDIL_176.jpg",priority:"core",display_context:"orbital",tags:["history","Sm","62"],panel:{type:"timeline",items:[{year:"1879",title:"Paul-Émile Lecoq de Boisbaudran discovers samarium",text:"French chemist Paul-Émile Lecoq de Boisbaudran discovers samarium in Paris by spectroscopically analyzing the mineral samarskite.",image:"images/elements/062_Sm/15_Samarskite_GeoDIL_176.jpg"},{year:"1879",title:"Naming of samarium",text:"The element is named 'samarium' after the mineral samarskite, which itself was named in honor of the Russian mine official Colonel Vasili Samarsky-Bykhovets, making it the first chemical element named after a person.",image:"images/elements/062_Sm/11_Samarskite_fresh_specimen.jpg"}]},sources:[{label:"Wikimedia Commons — samarskite specimen",url:"https://commons.wikimedia.org/wiki/File:Samarskite-fresh.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Samarium emission spectrum",text:"Emission spectrum — Spectral lines of Samarium (Sm) from the NIST Atomic Spectra Database.",image:"images/elements/062_Sm/09_62_(Sm_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","sm","62"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Samarium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of samarium's characteristic atomic emission lines.",image:"images/elements/062_Sm/02_Samarium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Sm","62"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],63:[{kind:"Portrait",title:"High-purity europium ingot in a glovebox",text:"Physical state — An approximately 300 g, 99.998% pure elemental europium ingot with crystalline, sublimed dendritic growth. It is photographed under argon in a glovebox because europium oxidizes rapidly in air. (europium metal)",image:"images/elements/063_Eu/11_Eu-Block.jpg",priority:"core",display_context:"orbital",tags:["portrait","Eu","63"],sources:[{label:"Wikimedia Commons — Alchemist-hp (CC BY-SA 3.0 DE)",url:"https://commons.wikimedia.org/wiki/File:Eu-Block.jpg"}]},{kind:"Origin",title:"Monazite-bearing mineral sand",text:"Natural source — Europium is a sparse rare-earth constituent of monazite and related heavy-mineral sands. It is recovered with other rare earths and then separated by solvent extraction.",image:"images/elements/063_Eu/16_Monazite_sand_europium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Eu","63"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Monazit_-_Caravelli,_Bahia,_Brasilien.jpg"}]},{kind:"Safety",title:"Europium powder handling precaution",text:"[Safety Warning] Europium metal is pyrophoric in powder form, reacts violently with water to release flammable hydrogen gas, and requires storage under inert gas. (pyrophoric metal)",image:"images/elements/022_Ti/04_GHS-pictogram-flamme.svg",priority:"standard",display_context:"orbital",tags:["safety","Eu","63"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Europium discovery timeline",text:"Key milestones of europium: from samarium fraction oxide isolation to its naming after Europe.",image:"images/elements/063_Eu/03_Eugène-Anatole_Demarçay.jpg",priority:"core",display_context:"orbital",tags:["history","Eu","63"],panel:{type:"timeline",items:[{year:"1901",title:"Eugène-Anatole Demarçay isolates europium",text:"French chemist Eugène-Anatole Demarçay isolates europium in Paris from samarium concentrates, detecting new spectral lines in the purified oxide.",image:"images/elements/063_Eu/03_Eugène-Anatole_Demarçay.jpg"},{year:"1901",title:"Naming after Europe",text:"Demarçay names the new element Europium in honor of the continent of Europe.",image:"images/elements/063_Eu/17_Europe_map_1730.jpg"}]},sources:[{label:"Wikimedia Commons — 1730 map of Europe",url:"https://commons.wikimedia.org/wiki/File:Map_of_Europe,_1730.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Europium emission spectrum",text:"Emission spectrum — Spectral lines of Europium (Eu) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Europium in distant stars.",image:"images/elements/063_Eu/14_63_(Eu_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","eu","63"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:63_%28Eu_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Europium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of europium's characteristic atomic emission lines.",image:"images/elements/063_Eu/01_Europium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Eu","63"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],64:[{kind:"Portrait",title:"Crystalline gadolinium metal pieces",text:"Physical state — Lustrous silvery-white crystalline gadolinium metal pieces. Gadolinium is a malleable, ductile rare-earth metal that is ferromagnetic below 20°C. (gadolinium metal)",image:"images/elements/064_Gd/04_Gadolinium-2.jpg",priority:"core",display_context:"orbital",tags:["portrait","Gd","64"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Gadolinium-2.jpg"}]},{kind:"Origin",title:"Gadolinite mineral specimen",text:"Natural occurrence — Gadolinite mineral specimen, a silicate mineral containing yttrium, iron, and beryllium, historically the source mineral where gadolinium and other rare earths were discovered. (gadolinite mineral)",image:"images/elements/064_Gd/08_Gadolinite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Gd","64"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Safety",title:"Gadolinium compound handling precaution",text:"[Safety Warning] Soluble gadolinium ions are toxic; it must be administered as a stable chelate to prevent deposition in brain and skin tissues (nephrogenic systemic fibrosis). (toxicity warning)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Gd","64"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Gadolinium discovery timeline",text:"Key milestones of gadolinium: from Geneva spectroscopic detection to naming after Johan Gadolin.",image:"images/elements/064_Gd/10_Galissard_de_Marignac.jpg",priority:"core",display_context:"orbital",tags:["history","Gd","64"],panel:{type:"timeline",items:[{year:"1880",title:"Jean Charles Galissard de Marignac discovers gadolinium",text:"Swiss chemist Jean Charles Galissard de Marignac detects gadolinium spectroscopically in samples of didymia and gadolinite.",image:"images/elements/064_Gd/10_Galissard_de_Marignac.jpg"},{year:"1886",title:"Isolation and naming after Johan Gadolin",text:"French chemist Paul-Émile Lecoq de Boisbaudran isolates the oxide and names it Gadolinium in honor of Finnish chemist Johan Gadolin, the pioneer of rare-earth research.",image:"images/elements/064_Gd/14_Johan_Gadolin_bicentennial_cover.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Gadolinium emission spectrum",text:"Emission spectrum — Spectral lines of Gadolinium (Gd) from the NIST Atomic Spectra Database.",image:"images/elements/064_Gd/13_64_(Gd_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","gd","64"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Gadolinium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of gadolinium's characteristic atomic emission lines.",image:"images/elements/064_Gd/02_Gadolinium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Gd","64"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],65:[{kind:"Portrait",title:"Terbium metal pieces in glass",text:"Physical state — Fresh silvery-grey terbium metal pieces kept in a glass container. Terbium is a soft, malleable lanthanide whose surface gradually tarnishes in air.",image:"images/elements/065_Tb/09_Terbium__Element_-_65__4.jpg",priority:"core",display_context:"orbital",tags:["portrait","Tb","65"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Terbium_(Element_-_65)_4.jpg"}]},{kind:"Origin",title:"Xenotime crystals from Hitterø, Norway",text:"Natural occurrence — Xenotime is an yttrium phosphate mineral (YPO₄) that hosts trace amounts of heavy lanthanides including terbium. This naturally grown crystal group is from Hitterø, Norway.",image:"images/elements/065_Tb/12_Xenotime_Hittero_terbium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Tb","65"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Xenotim_mineralogisches_museum_bonn.jpg"}]},{kind:"Safety",title:"Terbium compound handling precaution",text:"[Safety Warning] Soluble terbium salts are irritating to eyes and skin, and metallic terbium dust is a flammable risk that must be handled under dry conditions. (compound hazard)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Tb","65"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Terbium emission spectrum",text:"Emission spectrum — Spectral lines of Terbium (Tb) from the NIST Atomic Spectra Database.",image:"images/elements/065_Tb/11_65_(Tb_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","tb","65"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Terbium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of terbium's characteristic atomic emission lines.",image:"images/elements/065_Tb/02_Terbium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Tb","65"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],66:[{kind:"Portrait",title:"Silvery dendritic dysprosium metal",text:"Physical state — Silvery, dendritic dysprosium metal pieces. Dysprosium has a bright metallic sheen and is soft enough to be machined easily. (dysprosium pieces)",image:"images/elements/066_Dy/04_Dysprosium.jpg",priority:"core",display_context:"orbital",tags:["portrait","Dy","66"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Dysprosium.jpg"}]},{kind:"Origin",title:"Xenotime with rutile from Bahia, Brazil",text:"Natural occurrence — Dysprosium is recovered with other heavy rare earths from phosphate minerals such as xenotime. The dark crystals in this natural Brazilian specimen are xenotime intergrown with rutile.",image:"images/elements/066_Dy/13_Xenotime_rutile_dysprosium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Dy","66"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Xenotime_with_Rutile-08-2-78aa.jpg"}]},{kind:"Safety",title:"Dysprosium compound handling precaution",text:"[Safety Warning] Dysprosium compounds are of low to moderate toxicity. Soluble dysprosium chloride and nitrate salts are corrosive skin irritants. (irritant warning)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Dy","66"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Dysprosium emission spectrum",text:"Emission spectrum — Spectral lines of Dysprosium (Dy) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Dysprosium in distant stars.",image:"images/elements/066_Dy/12_66_(Dy_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","dy","66"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:66_%28Dy_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Dysprosium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of dysprosium's characteristic atomic emission lines.",image:"images/elements/066_Dy/02_Dysprosium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Dy","66"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],67:[{kind:"Portrait",title:"Silvery-white holmium metal pieces",text:"Physical state — Lustrous silvery-white holmium metal pieces. Holmium is soft, malleable, and stable in dry air at room temperature. (holmium metal)",image:"images/elements/067_Ho/05_Holmium.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ho","67"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Holmium.jpg"}]},{kind:"Science",title:"Holmium oxide glass plate",text:"Materials science — A plate of holmium oxide glass. Holmium-containing glass has characteristic visible absorption bands and is used as a wavelength reference in spectrophotometry. (holmium glass)",image:"images/elements/067_Ho/04_Holmium_glass_filter.jpg",priority:"standard",display_context:"orbital",tags:["science","Ho","67"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Origin",title:"Xenotime heavy rare-earth mineral",text:"Natural source — Holmium occurs with other heavy rare earths in phosphate minerals such as xenotime. The dark xenotime crystals shown here grew naturally in a quartz-rich host rock.",image:"images/elements/067_Ho/13_Xenotime_holmium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ho","67"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Xenotim_-_Kohlergraben,_Binnental,_Wallis,_Schweiz.jpg"}]},{kind:"Safety",title:"Holmium laser safety warning",text:"[Safety Warning] Holmium lasers require specialized eye protection due to eye damage risks. Soluble holmium salts are toxic by ingestion and irritate mucous membranes. (laser hazard)",image:"images/elements/067_Ho/02_Holmium_laser_safety_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Ho","67"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Safety_Symbols_Art,_Warning_Type_2_-_Laser_Radiation.svg"}]},{kind:"History",title:"Holmium discovery timeline",text:"Key milestones of holmium: from Element X detection to Cleve's Stockholm naming.",image:"images/elements/067_Ho/03_Per_Teodor_Cleve.jpg",priority:"core",display_context:"orbital",tags:["history","Ho","67"],panel:{type:"timeline",items:[{year:"1879",title:"Per Teodor Cleve isolates and names holmium",text:"Swedish chemist Per Teodor Cleve independently isolates holmium from erbia residues and names it Holmium after 'Holmia', the Latin name for Stockholm, Sweden.",image:"images/elements/067_Ho/03_Per_Teodor_Cleve.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Holmium emission spectrum",text:"Emission spectrum — Spectral lines of Holmium (Ho) from the NIST Atomic Spectra Database.",image:"images/elements/067_Ho/12_67_(Ho_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","ho","67"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Holmium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of holmium's characteristic atomic emission lines.",image:"images/elements/067_Ho/01_Holmium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Ho","67"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],68:[{kind:"Portrait",title:"Lustrous silvery erbium chunks",text:"Physical state — Lustrous silvery erbium metal chunks. Erbium is a relatively stable, soft rare-earth metal showing a bright metallic sheen. (erbium metal)",image:"images/elements/068_Er/05_Erbium.jpg",priority:"core",display_context:"orbital",tags:["portrait","Er","68"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Erbium.jpg"}]},{kind:"Origin",title:"Xenotime and monazite in natural host rock",text:"Natural occurrence — Erbium occurs with other heavy rare earths in phosphate minerals such as xenotime and monazite. This natural specimen from Austria contains both minerals in their rock matrix.",image:"images/elements/068_Er/13_Xenotime_monazite_erbium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Er","68"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Monazit,_Xenotim,_H%C3%A4matit_-_Stbr._Lohninger,_Rauris,_%C3%96sterreich.jpg"}]},{kind:"Safety",title:"Erbium compound handling precaution",text:"[Safety Warning] Soluble erbium salts are mild skin and eye irritants, and metallic erbium powder represents a moderate fire hazard. (flammability warning)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Er","68"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Erbium emission spectrum",text:"Emission spectrum — Spectral lines of Erbium (Er) from the NIST Atomic Spectra Database.",image:"images/elements/068_Er/12_68_(Er_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","er","68"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Erbium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of erbium's characteristic atomic emission lines.",image:"images/elements/068_Er/02_Erbium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Er","68"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],69:[{kind:"Portrait",title:"Pure sublimed dendritic thulium crystals",text:"Physical state — Extremely pure, sublimed dendritic thulium crystals and a 1 cm³ metal cube. Thulium is the rarest and most expensive stable lanthanide. (thulium crystals)",image:"images/elements/069_Tm/09_Thulium_sublimed_dendritic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Tm","69"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Thulium_sublimed_dendritic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Monazite from Rostadheia, Norway",text:"Natural occurrence — Thulium is a trace constituent of rare-earth phosphate ores. This group of naturally formed monazite specimens comes from Rostadheia, Iveland, Norway.",image:"images/elements/069_Tm/13_Monazite_Rostadheia_thulium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Tm","69"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Monazit_-_Rostadheia,_Iveland,_S.-Norwegen.jpg"}]},{kind:"Safety",title:"Thulium compound handling precaution",text:"[Safety Warning] Radioactive thulium-170 requires lead shielding to prevent ionizing radiation exposure. Soluble thulium salts are mild skin irritants. (radiation hazard)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Tm","69"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Thulium emission spectrum",text:"Emission spectrum — Spectral lines of Thulium (Tm) from the NIST Atomic Spectra Database.",image:"images/elements/069_Tm/12_69_(Tm_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","tm","69"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Thulium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of thulium's characteristic atomic emission lines.",image:"images/elements/069_Tm/02_Thulium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Tm","69"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],70:[{kind:"Portrait",title:"Silvery ytterbium metal chunks",text:"Physical state — Silvery-grey ytterbium metal chunks. Ytterbium is a soft, ductile lanthanide that is relatively stable but oxidizes slowly in moist air. (ytterbium metal)",image:"images/elements/070_Yb/05_Ytterbium.jpg",priority:"core",display_context:"orbital",tags:["portrait","Yb","70"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Ytterbium.jpg"}]},{kind:"Origin",title:"Xenotime in chlorite-bearing host rock",text:"Natural occurrence — Ytterbium is recovered with other heavy rare earths from phosphate minerals such as xenotime and monazite. This natural Austrian rock specimen contains xenotime with chlorite.",image:"images/elements/070_Yb/13_Xenotime_chlorite_ytterbium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Yb","70"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Xenotim,_Chlorit_-_Lacheggklamm,_Hohe_Tauern.jpg"}]},{kind:"Safety",title:"Ytterbium laser safety warning",text:"[Safety Warning] Ytterbium-doped lasers generate invisible infrared radiation that causes permanent blindness. Ytterbium metal dust is flammable and must be stored under protective gas. (laser warning)",image:"images/elements/070_Yb/02_Ytterbium_laser_safety_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Yb","70"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Laser_Warning_Symbol_-_USA.svg"}]},{kind:"History",title:"Ytterbium discovery timeline",text:"Key milestones of ytterbium: from Marignac's erbia isolation to the village of Ytterby.",image:"images/elements/070_Yb/03_Jean_Charles_Galissard_de_Marignac.jpg",priority:"core",display_context:"orbital",tags:["history","Yb","70"],panel:{type:"timeline",items:[{year:"1878",title:"Jean Charles Galissard de Marignac discovers ytterbium",text:"Swiss chemist Jean Charles Galissard de Marignac discovers ytterbium in Geneva by isolating its oxide from erbia samples.",image:"images/elements/070_Yb/03_Jean_Charles_Galissard_de_Marignac.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Ytterbium emission spectrum",text:"Emission spectrum — Spectral lines of Ytterbium (Yb) from the NIST Atomic Spectra Database.",image:"images/elements/070_Yb/12_70_(Yb_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","yb","70"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Ytterbium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of ytterbium's characteristic atomic emission lines.",image:"images/elements/070_Yb/01_Ytterbium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Yb","70"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],71:[{kind:"Portrait",title:"Pure sublimed dendritic lutetium crystals",text:"Physical state — Pure sublimed dendritic lutetium crystals next to a 1 cm³ metal cube. Lutetium is the heaviest and hardest of all the lanthanides. (lutetium crystals)",image:"images/elements/071_Lu/11_Lutetium_sublimed_dendritic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Lu","71"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Lutetium_sublimed_dendritic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Xenotime in quartz and feldspar, Malawi",text:"Natural occurrence — Lutetium is the least abundant stable rare-earth metal and is recovered in trace amounts with other heavy rare earths from minerals such as xenotime. This natural Malawi specimen shows xenotime in quartz and alkali feldspar.",image:"images/elements/071_Lu/13_Xenotime_quartz_lutetium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Lu","71"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Xenotim,_Quarz,_Kalifeldspat_-_Mt._Malosa,_Zomba,_Malawi_-_33115.jpg"}]},{kind:"Safety",title:"Lutetium compound handling precaution",text:"[Safety Warning] Lutetium compounds are low in toxicity. Soluble lutetium salts are mild skin and eye irritants, while the metal powder presents a moderate fire risk. (handling safety)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Lu","71"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Lutetium discovery timeline",text:"Key milestones of lutetium: from Urbain's separation to naming after Paris.",image:"images/elements/071_Lu/03_Georges_Urbain.jpg",priority:"core",display_context:"orbital",tags:["history","Lu","71"],panel:{type:"timeline",items:[{year:"1907",title:"Georges Urbain, Carl Auer von Welsbach, and Charles James discover lutetium",text:"French chemist Georges Urbain, Austrian chemist Carl Auer von Welsbach, and American chemist Charles James independently discover lutetium as an impurity in ytterbium oxide.",image:"images/elements/071_Lu/03_Georges_Urbain.jpg"},{year:"1907",title:"Naming and etymology",text:"Urbain names the element Lutetium from the Latin name 'Lutetia' (Paris), in honor of his hometown.",image:"images/elements/071_Lu/14_Lutetia_Paris_map.jpg"}]},sources:[{label:"Wikimedia Commons — Lutetia Parisorum map",url:"https://commons.wikimedia.org/wiki/File:Lutetia_Parisorum_urbs,_toto_orbe_celeberrima_notissimaque,_caput_regni_Franciae.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Lutetium emission spectrum",text:"Emission spectrum — Spectral lines of Lutetium (Lu) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Lutetium in distant stars.",image:"images/elements/071_Lu/12_71_(Lu_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","lu","71"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:71_%28Lu_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Lutetium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of lutetium's characteristic atomic emission lines.",image:"images/elements/071_Lu/02_Lutetium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Lu","71"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],72:[{kind:"Portrait",title:"Silvery electron-beam remelted hafnium",text:"Physical state — Silvery, high-purity electron-beam remelted hafnium metal ingot. Hafnium is a lustrous, silvery-grey transition metal that is highly corrosion-resistant. (hafnium ingot)",image:"images/elements/072_Hf/09_Hafnium_ebeam_remelted.jpg",priority:"core",display_context:"orbital",tags:["portrait","Hf","72"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Hafnium_ebeam_remelted.jpg"}]},{kind:"Origin",title:"Zircon mineral in host rock",text:"Natural occurrence — Zircon (ZrSiO4) in its natural rock matrix. Hafnium does not occur as a free element; it substitutes into zircon and related zirconium minerals, commonly at about 1–4%. (zircon mineral)",image:"images/elements/072_Hf/13_Zircon_GeoDIL_2385.jpg",priority:"standard",display_context:"orbital",tags:["origin","Hf","72"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Zircon_(GeoDIL_number_-_2385).jpg"}]},{kind:"Safety",title:"Hafnium powder handling precaution",text:"[Safety Warning] Hafnium metal in finely divided powder form is pyrophoric and can ignite spontaneously in air. It must be kept away from sources of ignition. (pyrophoric hazard)",image:"images/elements/022_Ti/04_GHS-pictogram-flamme.svg",priority:"standard",display_context:"orbital",tags:["safety","Hf","72"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Hafnium discovery timeline",text:"Key milestones of hafnium: from Copenhagen X-ray spectroscopy to naming after Hafnia.",image:"images/elements/072_Hf/03_Dirk_Coster.jpg",priority:"core",display_context:"orbital",tags:["history","Hf","72"],panel:{type:"timeline",items:[{year:"1923",title:"Dirk Coster and George de Hevesy discover hafnium",text:"Dutch physicist Dirk Coster and Hungarian chemist George de Hevesy discover hafnium in Copenhagen by analyzing zirconium minerals using X-ray spectroscopy.",image:"images/elements/072_Hf/03_Dirk_Coster.jpg"},{year:"1923",title:"Naming after Copenhagen",text:"They name the element Hafnium from 'Hafnia', the Latin name for Copenhagen, where Niels Bohr's institute is located and the discovery was made.",image:"images/elements/072_Hf/14_Hafnia_Copenhagen_1748_map.jpg"}]},sources:[{label:"Wikimedia Commons — Hafnia (Copenhagen), 1748",url:"https://commons.wikimedia.org/wiki/File:Hafnia_Hodierna_Tab_I_Koebenhavn.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Hafnium emission spectrum",text:"Emission spectrum — Spectral lines of Hafnium (Hf) from the NIST Atomic Spectra Database.",image:"images/elements/072_Hf/12_72_(Hf_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","hf","72"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Hafnium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of hafnium's characteristic atomic emission lines.",image:"images/elements/072_Hf/01_Hafnium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Hf","72"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],73:[{kind:"Portrait",title:"Pure tantalum single crystal and cube",text:"Physical state — Pure tantalum single crystal cylinder and a 1 cm³ metal cube. Tantalum is a dense, hard, and highly corrosion-resistant blue-grey transition metal. (tantalum metal)",image:"images/elements/073_Ta/09_Tantalum_single_crystal_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ta","73"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Tantalum_single_crystal_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Tantalite mineral specimen",text:"Natural occurrence — Tantalite mineral specimen. Tantalite, a heavy black mineral ([Fe,Mn]Ta2O6), is the primary geological source for commercial tantalum extraction. (tantalite ore)",image:"images/elements/073_Ta/08_Tantalite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ta","73"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Tantalite.jpg"}]},{kind:"Science",title:"Colorful anodized tantalum sheet",text:"Chemical properties — Colorful anodized tantalum metal sheet. Tantalum forms a highly stable, protective oxide surface layer (Ta2O5) that exhibits iridescent colors under electrochemical anodization. (anodized oxide)",image:"images/elements/073_Ta/07_Anodized_tantalum.jpg",priority:"standard",display_context:"orbital",tags:["science","Ta","73"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Uses",title:"Solid tantalum electrolytic capacitors",text:"Practical application — Solid tantalum electrolytic capacitors on a circuit board. Tantalum capacitors are widely used in smartphones and laptops due to their high capacitance per volume and stability. (tantalum capacitors)",image:"images/elements/073_Ta/04_Tantalum_capacitors.jpg",priority:"core",display_context:"orbital",tags:["uses","Ta","73"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Tantalum_capacitors.jpg"}]},{kind:"Safety",title:"Tantalum dust handling precaution",text:"[Safety Warning] Elemental tantalum is bio-inert and non-toxic. However, fine tantalum dust is a severe fire and explosion hazard. (combustible dust)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Ta","73"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Tantalum discovery timeline",text:"Key milestones of tantalum: from Uppsala mineral studies to naming after King Tantalus.",image:"images/elements/073_Ta/03_Anders_Gustaf_Ekeberg.jpg",priority:"core",display_context:"orbital",tags:["history","Ta","73"],panel:{type:"timeline",items:[{year:"1802",title:"Anders Gustaf Ekeberg discovers tantalum",text:"Swedish chemist Anders Gustaf Ekeberg discovers tantalum in Uppsala while analyzing mineral specimens from Sweden and Finland.",image:"images/elements/073_Ta/03_Anders_Gustaf_Ekeberg.jpg"},{year:"1802",title:"Naming after Tantalus",text:"Ekeberg names the element Tantalum after King Tantalus of Greek mythology, symbolizing the frustration he experienced while trying to dissolve the new oxide in acids.",image:"images/elements/073_Ta/13_Tantalus_Assereto.jpg"}]},sources:[{label:"Wikimedia Commons — Tantalus, Gioacchino Assereto",url:"https://commons.wikimedia.org/wiki/File:Tantalus_Gioacchino_Assereto_circa1640s.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Tantalum emission spectrum",text:"Emission spectrum — Spectral lines of Tantalum (Ta) from the NIST Atomic Spectra Database.",image:"images/elements/073_Ta/12_73_(Ta_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","ta","73"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Tantalum visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of tantalum's characteristic atomic emission lines.",image:"images/elements/073_Ta/02_Tantalum_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Ta","73"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],74:[{kind:"Portrait",title:"Pure tungsten evaporated crystals and cube",text:"Physical state — Pure tungsten evaporated crystals showing facet details next to a 1 cm³ metal cube. Tungsten is extremely dense and has the highest melting point of all metals (3422°C). (tungsten metal)",image:"images/elements/074_W/09_Wolfram_evaporated_crystals_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","W","74"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Wolfram_evaporated_crystals_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Wolframite mineral specimen",text:"Natural occurrence — Wolframite mineral specimen. Wolframite, an iron-manganese tungstate mineral ([Fe,Mn]WO4), is the historic and primary ore source of tungsten. (wolframite mineral)",image:"images/elements/074_W/08_Wolframite.jpg",priority:"standard",display_context:"orbital",tags:["origin","W","74"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Uses",title:"Tungsten carbide drill bit",text:"Practical application — A carbide-tipped drill bit. High-hardness tungsten carbide (WC) is used extensively in drill bits, machining tools, and other wear-resistant cutting equipment. (carbide tools)",image:"images/elements/074_W/07_Tungsten_carbide_cutting_tool.jpg",priority:"core",display_context:"orbital",tags:["uses","W","74"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Safety",title:"Tungsten hot filament safety warning",text:"[Safety Warning] Tungsten metal is non-toxic, but fine dust can irritate eyes and skin. Filaments operate at extremely high temperatures (over 2500°C), presenting severe burn hazards. (hot filament)",image:"images/elements/074_W/02_Tungsten_hot_filament.svg",priority:"standard",display_context:"orbital",tags:["safety","W","74"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Tungsten discovery timeline",text:"Key milestones of tungsten: from Scheele's tungstic acid to the Vergara isolation of wolfram.",image:"images/elements/074_W/03_Elhuyar_brothers.jpg",priority:"core",display_context:"orbital",tags:["history","W","74"],panel:{type:"timeline",items:[{year:"1783",title:"Elhuyar brothers isolate tungsten metal",text:"Spanish mineralogists Fausto and Juan José Elhuyar isolate metallic tungsten by reducing tungstic acid with charcoal in Vergara, naming it wolfram.",image:"images/elements/074_W/03_Elhuyar_brothers.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Tungsten emission spectrum",text:"Emission spectrum — Spectral lines of Tungsten (W) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Tungsten in distant stars.",image:"images/elements/074_W/14_74_(W_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","w","74"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:74_%28W_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Incandescent tungsten filament at operating temperature",text:"Thermal-radiation observation — A tungsten filament glowing inside an incandescent lamp. The bulb's vacuum or inert-gas envelope lets tungsten operate at an extreme temperature without immediately oxidizing; its unusually high melting point makes this controlled blackbody-like emission possible.",image:"images/elements/074_W/15_Incandescent_tungsten_filament.jpg",priority:"standard",display_context:"orbital",tags:["science","thermal radiation","filament","tungsten","74"],sources:[{label:"Wikimedia Commons — tungsten filament in an incandescent light",url:"https://commons.wikimedia.org/wiki/File:Tungsten_filament_in_an_incandescent_light.JPG"}]},{kind:"Science",title:"Tungsten visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of tungsten's characteristic atomic emission lines.",image:"images/elements/074_W/01_Tungsten_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","W","74"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],75:[{kind:"Portrait",title:"Dense silvery rhenium metal pellet",text:"Physical state — A dense, silvery rhenium metal pellet. Rhenium is a rare, heavy transition metal with a very high melting point (3186°C) and density. (rhenium metal)",image:"images/elements/075_Re/05_Rhenium_pellet.jpg",priority:"core",display_context:"orbital",tags:["portrait","Re","75"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Origin",title:"Molybdenite in quartz host rock",text:"Natural occurrence — Silvery molybdenite (MoS2) in quartz. Rhenium is not visibly separate here: it occurs in trace amounts in molybdenite and is recovered as a byproduct of copper–molybdenum ores. (molybdenite host mineral)",image:"images/elements/075_Re/12_Molybdenite_in_quartz_GeoDIL_1076.jpg",priority:"standard",display_context:"orbital",tags:["origin","Re","75"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Molybdenite_in_quartz_(GeoDIL_number_-_1076).jpg"}]},{kind:"Safety",title:"Rhenium compound handling precaution",text:"[Safety Warning] Rhenium metal is non-toxic, but soluble rhenium salts (like perrhenates) are moderate irritants to eyes and skin, requiring careful lab handling. (irritant warning)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Re","75"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Rhenium discovery timeline",text:"Key milestones of rhenium: from columbite detection in Berlin to naming after the Rhine.",image:"images/elements/075_Re/03_Walter_Noddack.jpg",priority:"core",display_context:"orbital",tags:["history","Re","75"],panel:{type:"timeline",items:[{year:"1925",title:"Walter Noddack, Ida Tacke, and Otto Berg discover rhenium",text:"German scientists Walter Noddack, Ida Tacke-Noddack, and Otto Berg discover rhenium in Berlin by detecting it in platinum ores and columbite minerals.",image:"images/elements/075_Re/03_Walter_Noddack.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Rhenium emission spectrum",text:"Emission spectrum — Spectral lines of Rhenium (Re) from the NIST Atomic Spectra Database.",image:"images/elements/075_Re/11_75_(Re_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","re","75"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"}]},{kind:"Science",title:"Rhenium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of rhenium's characteristic atomic emission lines.",image:"images/elements/075_Re/02_Rhenium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Re","75"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],76:[{kind:"Portrait",title:"Lustrous crystalline osmium metal",text:"Physical state — Lustrous bluish-white crystalline osmium metal. Osmium is the densest naturally occurring element. (osmium crystals)",image:"images/elements/076_Os/09_Osmium_crystals.jpg",priority:"core",display_context:"orbital",tags:["portrait","Os","76"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Osmium_crystals.jpg"}]},{kind:"Origin",title:"Stillwater platinum-group sulfide ore",text:"Natural occurrence — Platinum–palladium-bearing sulfide ore from Montana's Stillwater Complex. Osmium is a trace platinum-group metal in such ore systems and is recovered during platinum-group refining; it is not a visible separate phase in this specimen. (platinum-group ore)",image:"images/elements/076_Os/13_Sulfidic_tremolitite_Stillwater_ore.jpg",priority:"standard",display_context:"orbital",tags:["origin","Os","76"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Sulfidic_tremolitite_(platinum-palladium_ore)_Stillwater_mine_MT.jpg"}]},{kind:"Safety",title:"Osmium tetroxide safety warning",text:"[Safety Warning] Osmium metal oxidizes in air to form the highly volatile, toxic, and skin/eye-staining tetroxide (OsO4). (toxic oxide warning)",image:"images/elements/076_Os/02_Osmium_tetroxide_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Os","76"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Osmium discovery timeline",text:"Key milestones of osmium: from insoluble platinum residues to the pungent oxide odor naming.",image:"images/elements/076_Os/03_Smithson_Tennant.jpg",priority:"core",display_context:"orbital",tags:["history","Os","76"],panel:{type:"timeline",items:[{year:"1803",title:"Smithson Tennant discovers osmium",text:"English chemist Smithson Tennant discovers osmium in London by analyzing the insoluble black residue left after dissolving platinum ores in aqua regia.",image:"images/elements/076_Os/03_Smithson_Tennant.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Osmium emission spectrum",text:"Emission spectrum — Spectral lines of Osmium (Os) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Osmium in distant stars.",image:"images/elements/076_Os/12_76_(Os_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","os","76"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:76_%28Os_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Osmium crystals prepared by chemical-vapor deposition",text:"Materials synthesis — Faceted osmium crystals freshly prepared by chemical-vapor deposition (CVD). This controlled laboratory process deposits osmium from a vapor-phase precursor, making the metal's crystalline growth visible at a scale unlike its natural occurrence.",image:"images/elements/076_Os/14_Osmium_crystals_CVD.jpg",priority:"standard",display_context:"orbital",tags:["science","materials synthesis","CVD","osmium crystals","76"],sources:[{label:"Wikimedia Commons — Osmium crystal prepared using CVD method",url:"https://commons.wikimedia.org/wiki/File:Osmium_crystal_prepared_using_CVD_method.webm"}]},{kind:"Science",title:"Osmium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of osmium's characteristic atomic emission lines.",image:"images/elements/076_Os/01_Osmium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Os","76"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],77:[{kind:"Portrait",title:"Silvery pure iridium metal",text:"Physical state — Silvery pure iridium metal sample showing a bright metallic sheen. Iridium is the second-densest element and is extremely corrosion-resistant. (iridium metal)",image:"images/elements/077_Ir/05_Iridium.jpg",priority:"core",display_context:"orbital",tags:["portrait","Ir","77"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Iridium.jpg"}]},{kind:"Origin",title:"Cretaceous-Paleogene boundary layer",text:"Natural occurrence — The Cretaceous-Paleogene (K-Pg) boundary clay layer, displaying a distinct iridium anomaly which provides evidence of a massive asteroid impact that wiped out the dinosaurs. (K-Pg boundary layer)",image:"images/elements/077_Ir/07_K-Pg_boundary.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ir","77"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Uses",title:"High-purity iridium crucible",text:"Practical application — High-purity iridium crucible used for growing single crystals of oxide semiconductors at temperatures up to 2100°C. (iridium crucible)",image:"images/elements/077_Ir/04_Iridium_crucible.jpg",priority:"core",display_context:"orbital",tags:["uses","Ir","77"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Safety",title:"Iridium compound handling precaution",text:"[Safety Warning] Iridium metal is chemically inert and non-toxic, but finely divided iridium powder is flammable, and its soluble salts are eye irritants. (irritant warning)",image:"images/elements/021_Sc/04_GHS-pictogram-exclam.svg",priority:"standard",display_context:"orbital",tags:["safety","Ir","77"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Iridium emission spectrum",text:"Emission spectrum — Spectral lines of Iridium (Ir) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Iridium in distant stars.",image:"images/elements/077_Ir/12_77_(Ir_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ir","77"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:77_%28Ir_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Iridium visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of iridium's characteristic atomic emission lines.",image:"images/elements/077_Ir/02_Iridium_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Ir","77"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],78:[{kind:"Portrait",title:"Pure platinum crystal structure",text:"Physical state — Ultrapure platinum crystals showing bright metallic luster. Platinum is a dense, malleable, and highly unreactive precious metal. (platinum crystals)",image:"images/elements/078_Pt/11_Platinum_crystals.jpg",priority:"core",display_context:"orbital",tags:["portrait","Pt","78"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Platinum_crystals.jpg"}]},{kind:"Science",title:"Cisplatin chemical structure model",text:"Chemical properties — Molecular structure of cisplatin (PtCl2(NH3)2), a platinum-based chemotherapy medication that binds to DNA to inhibit cancer cell division. (cisplatin molecule)",image:"images/elements/078_Pt/07_Cisplatin.jpg",priority:"standard",display_context:"orbital",tags:["science","Pt","78"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Uses",title:"Döbereiner platinum catalytic lighter",text:"Practical application — A Döbereiner lamp uses platinum sponge to catalyze the reaction of hydrogen with oxygen, producing an instant flame. It was an early practical demonstration of platinum catalysis. (hydrogen lighter)",image:"images/elements/078_Pt/14_Dobereiner_fire_gadget.png",priority:"core",display_context:"orbital",tags:["uses","Pt","78"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:D%C3%B6bereiner_fire_gadget.png"}]},{kind:"Safety",title:"Platinum compound toxicity warning",text:"[Safety Warning] While elemental platinum is bio-inert, soluble platinum salts can cause platinum allergy, skin irritation, and toxic side effects. (toxic salts warning)",image:"images/elements/078_Pt/01_Cisplatin_hazard.svg",priority:"standard",display_context:"orbital",tags:["safety","Pt","78"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Platinum emission spectrum",text:"Emission spectrum — Spectral lines of Platinum (Pt) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Platinum in distant stars.",image:"images/elements/078_Pt/13_78_(Pt_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","pt","78"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:78_%28Pt_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Platinum visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of platinum's characteristic atomic emission lines.",image:"images/elements/078_Pt/02_Platinum_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Pt","78"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],79:[{kind:"Portrait",title:"Octahedral native gold crystals",text:"Physical state — Spectacular naturally formed gold crystals displaying distinct octahedron faces and bright yellow metallic luster. Gold is a dense, soft, and highly malleable noble metal. (gold crystals)",image:"images/elements/079_Au/09_Gold-crystals.jpg",priority:"core",display_context:"orbital",tags:["portrait","Au","79"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Gold-crystals.jpg"}]},{kind:"Origin",title:"Native gold vein in quartz",text:"Natural occurrence — Native gold specimen embedded in a white quartz rock matrix, representing the primary geological hydrothermal vein deposit of gold. (native gold vein)",image:"images/elements/079_Au/08_Native_gold.jpg",priority:"standard",display_context:"orbital",tags:["origin","Au","79"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Uses",title:"Gold-plated electronic connector pins",text:"Practical application — Gold-plated computer motherboard pins. Due to its excellent electrical conductivity and complete resistance to oxidation/tarnish, gold is crucial for reliable electronic contacts. (gold contacts)",image:"images/elements/079_Au/06_Gold-plated_connector.jpg",priority:"core",display_context:"orbital",tags:["uses","Au","79"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Safety",title:"Cyanide works at Robinson Gold Mining Co.",text:"[Safety Warning] Historical gold-mining cyanide works. Cyanide-based gold extraction creates acute toxicity and water-contamination hazards that require strictly controlled industrial handling. (cyanidation hazard)",image:"images/elements/079_Au/01_Gold_cyanidation_warning.jpg",priority:"standard",display_context:"orbital",tags:["safety","Au","79"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:ROBINSON_GOLD_MINING_CO._cyanide_works.jpg"}]},{kind:"History",title:"Gold historical timeline",text:"Key milestones of gold: from ancient funerary masks and coinage to alchemical transmutation pursuits.",image:"images/elements/079_Au/03_Ancient_gold_mask.jpg",priority:"core",display_context:"orbital",tags:["history","Au","79"],panel:{type:"timeline",items:[{year:"Antiquity",title:"Early gold metallurgy and coinage",text:"Gold is one of the earliest metals worked by humanity. Ancient civilizations use gold for jewelry, funerary masks, and as a universal currency standard (starting in Lydia around 600 BC).",image:"images/elements/079_Au/03_Ancient_gold_mask.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Gold emission spectrum",text:"Emission spectrum — Spectral lines of Gold (Au) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Gold in distant stars.",image:"images/elements/079_Au/16_79_(Au_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","au","79"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:79_%28Au_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Gold visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of gold's characteristic atomic emission lines.",image:"images/elements/079_Au/02_Gold_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Au","79"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],80:[{kind:"Portrait",title:"Liquid mercury sample sealed in an ampoule",text:"Physical state — A sealed glass ampoule containing liquid mercury metal. Mercury is the only metallic element that exists as a liquid under standard temperature and pressure conditions. (sealed liquid-metal sample)",image:"images/elements/080_Hg/04_Mercury__element_.jpg",priority:"core",display_context:"orbital",tags:["portrait","Hg","80"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Origin",title:"Red cinnabar mineral specimen",text:"Natural occurrence — Cinnabar (mercury sulfide, HgS) mineral specimen. Cinnabar is a bright red, heavy mineral that represents the primary geological source for commercial extraction of mercury. (cinnabar mineral)",image:"images/elements/080_Hg/08_Cinnabar-183512.jpg",priority:"standard",display_context:"orbital",tags:["origin","Hg","80"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Uses",title:"Traditional liquid mercury thermometer",text:"Practical application — A traditional glass mercury-in-glass thermometer, utilizing the uniform thermal expansion of liquid mercury to measure temperature. (thermometer)",image:"images/elements/080_Hg/05_Mercury_thermometer.jpg",priority:"core",display_context:"orbital",tags:["uses","Hg","80"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Safety",title:"Mercury-containing skin cream evidence",text:"[Safety Warning] Mercury exposure can arise from some skin-lightening products. This evidence photograph shows a cream product being handled with protective gloves; mercury-containing products should not be used or handled without appropriate public-health guidance.",image:"images/elements/080_Hg/02_Mercury_poison_warning.jpg",priority:"standard",display_context:"orbital",tags:["safety","Hg","80"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Mercury discovery timeline",text:"Key milestones of mercury: from ancient cinnabar cosmetics to Jabir ibn Hayyan's sulfur-mercury theory of metals.",image:"images/elements/080_Hg/03_Jabir_ibn_Hayyan.jpg",priority:"core",display_context:"orbital",tags:["history","Hg","80"],panel:{type:"timeline",items:[{year:"Antiquity",title:"Ancient Chinese and Egyptian cinnabar mining",text:"Mercury is known to ancient civilizations since at least 1500 BC. Chinese alchemists use cinnabar as a red pigment and seek immortality elixirs using liquid mercury.",image:"images/elements/080_Hg/09_Cinnabar_on_Dolomite.jpg"},{year:"8th Century",title:"Jabir ibn Hayyan defines mercury-sulfur theory",text:"Islamic alchemist Jabir ibn Hayyan formulates the sulfur-mercury theory of metals, positing that all metals are composed of differing ratios of sulfur and mercury.",image:"images/elements/080_Hg/03_Jabir_ibn_Hayyan.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Mercury emission spectrum",text:"Emission spectrum — Spectral lines of Mercury (Hg) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Mercury in distant stars.",image:"images/elements/080_Hg/13_80_(Hg_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","hg","80"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:80_%28Hg_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Mercury dial barometer",text:"Scientific measurement — This 1824 mercury dial barometer converts the height of a mercury column into a readable air-pressure scale. It is a physical application of hydrostatic pressure measurement rather than a decorative mercury sample.",image:"images/elements/080_Hg/14_Mercury_dial_barometer_1824.jpg",priority:"standard",display_context:"orbital",tags:["science","measurement","barometer","Hg","80"],sources:[{label:"Wikimedia Commons — 1824 mercury dial barometer",url:"https://commons.wikimedia.org/wiki/File:Mercury_dial_barometer,_J._Haas,_Lisbon,_1824_-_Museu_da_Ci%C3%AAncia_da_Universidade_de_Coimbra_-_University_of_Coimbra_-_Coimbra,_Portugal_-_DSC09161.jpg"}]},{kind:"Science",title:"Mercury visible emission-line reference",text:"Spectroscopy reference — A compact visible-wavelength rendering of mercury's characteristic atomic emission lines.",image:"images/elements/080_Hg/01_Mercury_spectrum_visible.png",priority:"standard",display_context:"orbital",tags:["science","spectroscopy","Hg","80"],sources:[{label:"NIST Atomic Spectra Database — Lines Form",url:"https://physics.nist.gov/PhysRefData/ASD/lines_form.html"}]}],81:[{kind:"Portrait",title:"Cast thallium metal in a glass vial",text:"Physical state — A silvery cast thallium metal sample kept in a glass vial. Thallium is a very soft, malleable post-transition metal that quickly develops a dark oxide layer in air.",image:"images/elements/081_Tl/15_Thallium_element_sample_in_vial.jpg",priority:"core",display_context:"orbital",tags:["portrait","Tl","81"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Thallium_(Element_-_81)_2.jpg"}]},{kind:"Origin",title:"Crookesite mineral specimen",text:"Natural occurrence — Crookesite mineral specimen. Crookesite is a rare copper-selenium mineral containing thallium and silver, representing a major natural geological source of the element. (crookesite mineral)",image:"images/elements/081_Tl/08_Crookesite.jpg",priority:"standard",display_context:"orbital",tags:["origin","Tl","81"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Crookesite.jpg"}]},{kind:"Uses",title:"KRS-5 thallium bromoiodide infrared-optics crystals",text:"Practical material — Translucent KRS-5 crystal blanks: a solid solution of thallium bromide and thallium iodide, made into infrared-transmitting windows, lenses, and spectroscopic components. (infrared optical material)",image:"images/elements/081_Tl/13_KRS5_thallium_bromoiodide_optical_crystals.jpg",priority:"standard",display_context:"orbital",tags:["uses","infrared","optics","crystal","Tl","81"],sources:[{label:"Wikimedia Commons — KRS5 Tallium Bromide Iodide ingots (CC BY-SA 3.0, Crystaltechno)",url:"https://commons.wikimedia.org/wiki/File:6_KRS5_Tallium_Bromide_Iodide_ingots_Crystaltechno.jpg"}]},{kind:"Safety",title:"Thallium severe toxicity warning",text:"[Safety Warning] Thallium and its soluble compounds are extremely toxic cumulative poisons. It disrupts potassium-dependent enzymes, historically used as a tasteless rodenticide. (potassium antagonist poison)",image:"images/elements/081_Tl/02_Thallium_poison_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Tl","81"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Thallium discovery timeline",text:"Key milestones of thallium: from Crookes' green spectrum line discovery to its naming.",image:"images/elements/081_Tl/03_William_Crookes_1906.jpg",priority:"core",display_context:"orbital",tags:["history","Tl","81"],panel:{type:"timeline",items:[{year:"1861",title:"William Crookes discovers thallium",text:"English chemist Sir William Crookes discovers thallium spectroscopically in sulfuric acid residues, identifying a brilliant new green emission line.",image:"images/elements/081_Tl/03_William_Crookes_1906.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Thallium emission spectrum",text:"Emission spectrum — Spectral lines of Thallium (Tl) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Thallium in distant stars.",image:"images/elements/081_Tl/12_81_(Tl_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","tl","81"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:81_%28Tl_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Thallium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-thallium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/081_Tl/16_Thallium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Tl","81"],sources:[{label:"NIST Atomic Spectra Database — Tl I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Tl+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],82:[{kind:"Portrait",title:"Pure electrolytic lead crystals",text:"Physical state — Pure electrolytic lead crystals showing faceted structure alongside a 1 cm³ metal cube. Lead is a heavy, soft, and highly malleable post-transition metal. (lead crystals)",image:"images/elements/082_Pb/05_Lead_electrolytic_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Pb","82"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Lead_electrolytic_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Galena mineral specimen",text:"Natural occurrence — Galena (lead sulfide, PbS) mineral specimen. Galena is a heavy, metallic, cubic-cleaved mineral representing the primary ore source for lead extraction. (galena mineral)",image:"images/elements/082_Pb/08_Galena-189462.jpg",priority:"standard",display_context:"orbital",tags:["origin","Pb","82"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Lead timeline",text:"Key milestones of lead: from Roman fistulae plumbing pipes to Gutenberg's movable type alloy.",image:"images/elements/082_Pb/03_Roman_lead_pipes.jpg",priority:"core",display_context:"orbital",tags:["history","Pb","82"],panel:{type:"timeline",items:[{year:"Antiquity",title:"Early smelting and Roman plumbing",text:"Lead has been smelted since at least 7000 BC. The Roman Empire mines lead extensively for water pipes (fistulae), glazes, and pewter tablewares, contributing to chronic poisoning.",image:"images/elements/082_Pb/03_Roman_lead_pipes.jpg"},{year:"15th Century",title:"Gutenberg's movable type",text:"Johannes Gutenberg utilizes a durable alloy of lead, tin, and antimony to manufacture metal type for his printing press, revolutionizing book production.",image:"images/elements/082_Pb/11_Metal_movable_type.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Lead emission spectrum",text:"Emission spectrum — Spectral lines of Lead (Pb) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Lead in distant stars.",image:"images/elements/082_Pb/13_82_(Pb_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","pb","82"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:82_%28Pb_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Lead I energy levels",text:"Atomic data — A clean plot of the lowest neutral-lead energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/082_Pb/16_Lead_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Pb","82"],sources:[{label:"NIST Atomic Spectra Database — Pb I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Pb+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],83:[{kind:"Portrait",title:"Iridescent bismuth hopper crystal",text:"Physical state — An iridescent bismuth hopper crystal showing vibrant rainbow oxide layers next to a 1 cm³ metal cube. Bismuth is the heaviest stable element. (iridescent hopper crystal)",image:"images/elements/083_Bi/09_Bismuth_crystals_and_1cm3_cube.jpg",priority:"core",display_context:"orbital",tags:["portrait","Bi","83"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Bismuth_crystals_and_1cm3_cube.jpg"}]},{kind:"Origin",title:"Native bismuth mineral chunk",text:"Natural occurrence — Native bismuth mineral specimen. Bismuth occurs in nature as a free metal in hydrothermal veins, and is also co-extracted from lead and copper ores. (native bismuth metal)",image:"images/elements/083_Bi/08_Native_bismuth.jpg",priority:"standard",display_context:"orbital",tags:["origin","Bi","83"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Bismuth emission spectrum",text:"Emission spectrum — Spectral lines of Bismuth (Bi) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Bismuth in distant stars.",image:"images/elements/083_Bi/12_83_(Bi_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","bi","83"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:83_%28Bi_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Bismuth pressure–temperature phase diagram",text:"Experimental phase data — Measurements of bismuth under pressure reveal several crystalline phases (Bi-I through Bi-V), rather than a single fixed structure. The plotted points and boundary curves also show low-temperature superconducting transitions in different phases.",image:"images/elements/083_Bi/16_Bismuth_pressure_temperature_phase_diagram.png",priority:"standard",display_context:"orbital",tags:["science","phase diagram","experimental data","crystal structure","83"],sources:[{label:"Wikimedia Commons — Bi phase diagram",url:"https://commons.wikimedia.org/wiki/File:Bi_phase_diagram.png"}]}],84:[{kind:"Origin",title:"Uraninite ore from Northern Territory, Australia",text:"Natural occurrence — Polonium is an intermediate decay product of uranium-238 and occurs in uraninite ores only in minute trace quantities. This weathered natural uraninite specimen is from Australia's Northern Territory.",image:"images/elements/084_Po/11_Uraninite_Australia_polonium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Po","84"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Uraninite-218648.jpg"}]},{kind:"Safety",title:"Severe radioactive hazard warning",text:"[Safety Warning] Polonium-210 is a highly dangerous internal alpha emitter. Ingestion or inhalation of microgram amounts causes fatal organ failure (acute radiation syndrome). (extreme radiotoxicity)",image:"images/elements/084_Po/06_Radioactive.svg",priority:"standard",display_context:"orbital",tags:["safety","Po","84"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Radioactive.svg"}]},{kind:"History",title:"Polonium discovery timeline",text:"Key milestones of polonium: from Marie and Pierre Curie's discovery to naming after Poland.",image:"images/elements/084_Po/07_Marie_Curie_c1920.jpg",priority:"core",display_context:"orbital",tags:["history","Po","84"],panel:{type:"timeline",items:[{year:"1898",title:"Marie and Pierre Curie discover polonium",text:"Polish-French physicist Marie Skłodowska-Curie and her husband Pierre Curie discover polonium in Paris while investigating the radioactivity of pitchblende.",image:"images/elements/084_Po/07_Marie_Curie_c1920.jpg"},{year:"1898",title:"Naming in honor of Poland",text:"Marie Curie names the new element Polonium in honor of her native land Poland, to highlight its lack of independence under Russian partition.",image:"images/elements/084_Po/03_Pierre_Curie_1903.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Polonium emission spectrum",text:"Emission spectrum — Spectral lines of Polonium (Po) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Polonium in distant stars.",image:"images/elements/084_Po/12_84_(Po_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","po","84"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:84_%28Po_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Polonium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-polonium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/084_Po/16_Polonium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Po","84"],sources:[{label:"NIST Atomic Spectra Database — Po I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Po+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],85:[{kind:"Portrait",title:"Freshly produced astatine-211 sample",text:"Physical sample — A sealed sample containing 3 gigabecquerels (about 40 ng) of astatine-211, produced and isolated at Forschungszentrum Jülich. The blue glow at the bottom is caused by radiation ionizing the surrounding material.",image:"images/elements/085_At/11_Astatine211_ionisation_glow.jpg",priority:"core",display_context:"orbital",tags:["portrait","radiochemistry","astatine-211","85"],sources:[{label:"NuclearAlex · CC BY 4.0 · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:First_Image_of_Astatine_-_English_Label_(cropped_more).jpg"}]},{kind:"Safety",title:"Astatine radiation warning label",text:"[Safety Warning] Astatine-211 presents extreme radioactive risks and accumulates in thyroid tissues, mimicking iodine. (radiotoxicity risk)",image:"images/elements/085_At/01_Astatine_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","At","85"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",title:"Astatine bromide chemical structure",text:"Chemical properties — Chemical model of astatine mono-bromide (AtBr), demonstrating that astatine behaves as a heavy, metalloid-like halogen. (astatine bromide molecule)",image:"images/elements/085_At/10_Astatine-bromide-2D.svg",priority:"standard",display_context:"orbital",tags:["science","At","85"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",title:"Astatine I energy levels",text:"Atomic data — A clean plot of the lowest neutral-astatine energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/085_At/16_Astatine_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","At","85"],sources:[{label:"NIST Atomic Spectra Database — At I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=At+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],86:[{kind:"Science",display_hint:"spectrum",title:"Radon emission spectrum",text:"Emission spectrum — A visible-wavelength rendering of neutral radon's characteristic atomic emission lines from the NIST Atomic Spectra Database. Each line represents a measured or evaluated electronic transition. (Rn I spectrum)",image:"images/elements/086_Rn/14_86_(Rn_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","rn","86"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:86_%28Rn_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Radon radioactive decay chain",text:"Nuclear science — The measured decay sequence of radon-222 and its solid progeny, proceeding through alpha and beta decays toward stable lead-206. This is distinct from the atomic emission spectrum above. (Rn-222 decay chain)",image:"images/elements/086_Rn/06_Radon_decay_chain.svg",priority:"standard",display_context:"orbital",tags:["science","Rn","86"],sources:[{label:"Wikimedia Commons — Pieter Kuiper (public domain)",url:"https://commons.wikimedia.org/wiki/File:Radon_progeny.svg"}]},{kind:"Safety",title:"Exterior radon-mitigation vent pipe",text:"[Safety measure] The exterior vent pipe of a residential sub-slab radon-mitigation system. Such systems draw soil gas from below a building and exhaust it safely above the roofline to reduce indoor radon accumulation.",image:"images/elements/086_Rn/04_Radon_mitigation.jpg",priority:"core",display_context:"orbital",tags:["safety","Rn","86"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],87:[{kind:"Safety",title:"Francium brief half-life warning",text:"[Safety Warning] Francium-223 is an extreme radiation hazard, decaying with a brief half-life of only 22 minutes. (brief half-life hazard)",image:"images/elements/087_Fr/02_Francium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Fr","87"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Francium discovery timeline",text:"Key milestones of francium: from Perey's actinium purification in Paris to naming after France.",image:"images/elements/087_Fr/03_Marguerite_Perey_at_work.jpg",priority:"core",display_context:"orbital",tags:["history","Fr","87"],panel:{type:"timeline",items:[{year:"1939",title:"Marguerite Perey discovers francium",text:"French physicist Marguerite Perey discovers francium at the Curie Institute in Paris by purifying actinium-227 samples, detecting its beta emissions.",image:"images/elements/087_Fr/03_Marguerite_Perey_at_work.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Francium emission spectrum",text:"Emission spectrum — Visible francium lines plotted from NIST Atomic Spectra Database wavelengths. Because line-intensity data are unavailable for this rendering, every line is shown at the same height; the positions are accurate, but the line heights are not measured intensities.",image:"images/elements/087_Fr/10_Atomic_spectrum_of_francium.webp",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","fr","87"],sources:[{label:"NIST Atomic Spectra Database",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons (CC0)",url:"https://commons.wikimedia.org/wiki/File:Atomic_spectrum_of_francium.svg"}]},{kind:"Science",title:"Francium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-francium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/087_Fr/16_Francium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Fr","87"],sources:[{label:"NIST Atomic Spectra Database — Fr I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Fr+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],88:[{kind:"Origin",title:"Uraninite and gummite from Shinkolobwe",text:"Natural occurrence — Radium is generated in uranium's decay chain and occurs at tiny concentrations in uraninite ores. This naturally weathered uraninite-and-gummite specimen is from the Shinkolobwe mine in the Democratic Republic of the Congo.",image:"images/elements/088_Ra/10_Uraninite_Shinkolobwe_radium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ra","88"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Shinkolobwe_Uraninite_with_Gummite.jpg"}]},{kind:"History",title:"Radium discovery timeline",text:"Key milestones of radium: from the Curies' pitchblende isolations to naming after active rays.",image:"images/elements/088_Ra/07_Pierre_and_Marie_Curie.jpg",priority:"core",display_context:"orbital",tags:["history","Ra","88"],panel:{type:"timeline",items:[{year:"1898",title:"Marie and Pierre Curie discover radium",text:"Marie and Pierre Curie discover radium in Paris, isolating its chloride from pitchblende residues.",image:"images/elements/088_Ra/07_Pierre_and_Marie_Curie.jpg"},{year:"Early 20th century",title:"Radium luminous paint becomes widespread",text:"Radium salts mixed with phosphors were applied to watch and instrument dials so they glowed in the dark, before the severe radiation hazard was understood.",image:"images/elements/088_Ra/04_Radium_watch_dial.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Radium emission spectrum",text:"Emission spectrum — Spectral lines of Radium (Ra) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Radium in distant stars.",image:"images/elements/088_Ra/11_88_(Ra_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ra","88"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:88_%28Ra_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Radium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-radium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/088_Ra/16_Radium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Ra","88"],sources:[{label:"NIST Atomic Spectra Database — Ra I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Ra+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],89:[{kind:"Portrait",title:"Actinium-225 nitrate sample",text:"Physical sample — A vial containing 17 millicuries of actinium-225 nitrate at Oak Ridge National Laboratory produces a blue-violet radioluminescent glow. This is an actinium compound, not elemental actinium metal.",image:"images/elements/089_Ac/09_Actinium-225_glowing_vial.jpg",priority:"core",display_context:"orbital",tags:["portrait","actinium-225","Ac","89"],sources:[{label:"Andrew R. Burgoyne / Oak Ridge National Laboratory · CC BY-SA 4.0 · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:17_mCi_Ac-225(NO3)3_at_ORNL_by_Dr_Andrew_R_Burgoyne.jpg"}]},{kind:"Origin",title:"Uraninite crystal in calcite matrix",text:"Natural occurrence — Actinium is an exceptionally rare natural product of uranium decay and occurs only at trace concentrations in uranium ores. This natural uraninite crystal is embedded in orange calcite from Bancroft, Ontario.",image:"images/elements/089_Ac/10_Uraninite_Bancroft_actinium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Ac","89"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Uraninite-179869.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Actinium emission spectrum",text:"Emission spectrum — Spectral lines of Actinium (Ac) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Actinium in distant stars.",image:"images/elements/089_Ac/10_89_(Ac_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","ac","89"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:89_%28Ac_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Safety",title:"Actinium radiation hazard warning",text:"[Safety Warning] Actinium is extremely dangerous if ingested, depositing in bone structures and destroying tissues with high-energy alpha particles. (internal alpha hazard)",image:"images/elements/089_Ac/01_Actinium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Ac","89"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",title:"Actinium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-actinium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/089_Ac/16_Actinium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Ac","89"],sources:[{label:"NIST Atomic Spectra Database — Ac I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Ac+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],90:[{kind:"Portrait",title:"Pure thorium metal sample",text:"Physical state — Silvery pure thorium metal sample inside a protective gas vial. Thorium is a malleable, silvery-white radioactive actinide metal. (thorium metal sample)",image:"images/elements/090_Th/05_Thorium_sample.jpg",priority:"core",display_context:"orbital",tags:["portrait","Th","90"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Origin",title:"Tabular monazite crystal from Norway",text:"Natural occurrence — Monazite is a rare-earth phosphate mineral that commonly contains several percent thorium, making it one of thorium's principal natural sources. This tabular crystal formed at Rostadheia, Iveland, Norway.",image:"images/elements/090_Th/14_Monazite_Rostadheia_thorium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Th","90"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Monazite_-_Rostadheia,_Iveland,_Norvegia_01.jpg"}]},{kind:"Science",title:"Thorium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-thorium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/090_Th/16_Thorium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Th","90"],sources:[{label:"NIST Atomic Spectra Database — Th I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Th+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]},{kind:"Safety",title:"Thorium dust inhalation warning",text:"[Safety Warning] Thorium is a weak alpha emitter, but inhalation of thorium dust presents severe lung cancer risks. (inhalation dust hazard)",image:"images/elements/090_Th/02_Thorium_radioactivity_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Th","90"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:DECADRY_Warning_-_Radioactive_Materials.svg"}]},{kind:"History",title:"Thorium discovery timeline",text:"Key milestones of thorium: from Berzelius' Swedish discovery to naming after Norse god Thor.",image:"images/elements/090_Th/15_Berzelius_1826.jpg",priority:"core",display_context:"orbital",tags:["history","Th","90"],panel:{type:"timeline",items:[{year:"1829",title:"Jöns Jacob Berzelius discovers thorium",text:"Swedish chemist Jöns Jacob Berzelius discovers thorium in Stockholm while analyzing a rare black mineral from Norway, naming the mineral thorite.",image:"images/elements/090_Th/15_Berzelius_1826.jpg"},{year:"1829",title:"Naming after Norse god Thor",text:"Berzelius names the new element Thorium in honor of Thor, the Norse god of thunder.",image:"images/elements/090_Th/10_Thor_fight_Winge.jpg"}]},sources:[{label:"Nationalmuseum via Wikimedia Commons — Thor's Fight with the Giants, Mårten Winge",url:"https://commons.wikimedia.org/wiki/File:Thor%27s_Fight_with_the_Giants_(M%C3%A5rten_Winge)_-_Nationalmuseum_-_18253.tiff"}]},{kind:"Science",display_hint:"spectrum",title:"Thorium emission spectrum",text:"Emission spectrum — Spectral lines of Thorium (Th) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Thorium in distant stars.",image:"images/elements/090_Th/09_90_(Th_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","th","90"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:90_%28Th_I%29_NIST_ASD_emission_spectrum.png"}]}],91:[{kind:"Portrait",title:"Silvery-grey protactinium metal sample",text:"Physical state — Silvery-grey protactinium metal sample. Protactinium is a dense, highly radioactive actinide metal that is superconducting below 1.4 K. (protactinium metal)",image:"images/elements/091_Pa/04_Protactinium_sample.jpg",priority:"core",display_context:"orbital",tags:["portrait","Pa","91"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Origin",title:"Natural uraninite crystal group from Maine",text:"Natural occurrence — Protactinium-231 is a decay product of uranium-235, occurring in uranium ores only at extremely low concentrations. This natural crystal group is uraninite from a quarry in Topsham, Maine.",image:"images/elements/091_Pa/10_Uraninite_Maine_protactinium_source.jpg",priority:"standard",display_context:"orbital",tags:["origin","Pa","91"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Uraninite-225146.jpg"}]},{kind:"Safety",title:"Protactinium alpha radiation warning",text:"[Safety Warning] Protactinium is highly toxic if ingested or inhaled, representing a serious alpha radiation hazard. (alpha radiation hazard)",image:"images/elements/091_Pa/02_Protactinium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Pa","91"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Protactinium discovery timeline",text:"Key milestones of protactinium: from Karlsruhe discovery of brevium to Berlin isolation of proto-actinium.",image:"images/elements/091_Pa/03_Kasimir_Fajans.jpg",priority:"core",display_context:"orbital",tags:["history","Pa","91"],panel:{type:"timeline",items:[{year:"1913",title:"Fajans and Göhring discover brevium",text:"Kasimir Fajans and Oswald Helmuth Göhring first identify protactinium (isotope Pa-234m) in Karlsruhe, naming it 'brevium' due to its short half-life of 1.17 minutes.",image:"images/elements/091_Pa/03_Kasimir_Fajans.jpg"},{year:"1917",title:"Meitner and Hahn discover stable protactinium",text:"Lise Meitner and Otto Hahn discover the longer-lived isotope Pa-231 in Berlin, which they name 'proto-actinium' as the precursor of actinium.",image:"images/elements/091_Pa/06_Lise_Meitner_1900s.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Protactinium emission spectrum",text:"Emission spectrum — Spectral lines of Protactinium (Pa) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Protactinium in distant stars.",image:"images/elements/091_Pa/09_91_(Pa_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","pa","91"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:91_%28Pa_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Protactinium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-protactinium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/091_Pa/16_Protactinium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Pa","91"],sources:[{label:"NIST Atomic Spectra Database — Pa I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Pa+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],92:[{kind:"Portrait",title:"Metallic uranium bar in a sealed display capsule",text:"Physical form — A solid metallic uranium sample preserved in a sealed display capsule. Uranium is a dense, silvery-white, weakly radioactive actinide metal.",image:"images/elements/092_U/13_Uranium_metal_bar.jpg",priority:"core",display_context:"orbital",tags:["portrait","U","92"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Origin",title:"Uranium minerals on uraninite matrix",text:"Natural occurrence — A natural uranium-mineral assemblage on dark uraninite matrix. The yellow-orange secondary uranium minerals formed as groundwater altered the primary uranium oxide ore; uraninite (pitchblende, chiefly UO₂) remains the principal natural uranium ore. (uraninite mineral assemblage)",image:"images/elements/092_U/14_Uranium_minerals_on_uraninite.jpg",priority:"standard",display_context:"orbital",tags:["origin","U","92"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Fourmarierite,_Becquerelite,_Uranophane,_Studtite,_Uraninite-725214.jpg"}]},{kind:"Uses",title:"Uranium dioxide fuel pellets",text:"Practical material — Sintered uranium dioxide (UO2) fuel pellets used as reactor fuel. Uranium-235 in the fuel can sustain a controlled nuclear chain reaction. (uranium fuel pellets)",image:"images/elements/092_U/04_Uranium_fuel_pellets.jpg",priority:"standard",display_context:"orbital",tags:["uses","U","92"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Uranium discovery timeline",text:"Key milestones of uranium: from Klaproth's pitchblende naming to Berlin nuclear fission discovery.",image:"images/elements/092_U/15_Klaproth_Rijksmuseum.jpg",priority:"core",display_context:"orbital",tags:["history","U","92"],panel:{type:"timeline",items:[{year:"1789",title:"Martin Heinrich Klaproth discovers uranium",text:"German chemist Martin Heinrich Klaproth discovers uranium in Berlin by analyzing pitchblende, naming it after the recently discovered planet Uranus.",image:"images/elements/092_U/15_Klaproth_Rijksmuseum.jpg"},{year:"1938",title:"Hahn, Strassmann, and Meitner discover nuclear fission",text:"Otto Hahn, Fritz Strassmann, and Lise Meitner discover nuclear fission in Berlin, proving that uranium nuclei split when bombarded with neutrons.",image:"images/elements/092_U/16_Hahn_Meitner_1912.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Uranium emission spectrum",text:"Emission spectrum — Spectral lines of Uranium (U) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Uranium in distant stars.",image:"images/elements/092_U/10_92_(U_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","u","92"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:92_%28U_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Uranium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-uranium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/092_U/16_Uranium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","U","92"],sources:[{label:"NIST Atomic Spectra Database — U I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=U+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],93:[{kind:"Portrait",title:"Encapsulated neptunium metal specimen",text:"Physical state — A close-up photograph of a small silvery-grey elemental neptunium specimen contained in a display vial. Neptunium is a dense radioactive actinide metal that tarnishes in air. (neptunium metal specimen)",image:"images/elements/093_Np/10_Neptunium_element_sample.jpg",priority:"core",display_context:"orbital",tags:["portrait","Np","93"],sources:[{label:"Wikimedia Commons — James St. John / Arònel123 (CC BY 2.0)",url:"https://commons.wikimedia.org/wiki/File:Neptunium_(Element_-_93)_3.jpg"}]},{kind:"Safety",title:"Neptunium bone-seeking radiotoxin warning",text:"[Safety Warning] Neptunium is a highly toxic, radioactive heavy metal that accumulates in bones, requiring specialized glovebox containment. (bone-seeking radiotoxin)",image:"images/elements/093_Np/02_Neptunium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Np","93"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Neptunium discovery timeline",text:"Key milestones of neptunium: from Berkeley cyclotron neutron bombardments to naming after Neptune.",image:"images/elements/093_Np/07_Edwin_McMillan.jpg",priority:"core",display_context:"orbital",tags:["history","Np","93"],panel:{type:"timeline",items:[{year:"1940",title:"Edwin McMillan and Philip Abelson synthesize neptunium",text:"American physicists Edwin McMillan and Philip Hauge Abelson synthesize neptunium-239 at UC Berkeley by bombarding uranium-238 with neutrons in a cyclotron.",image:"images/elements/093_Np/07_Edwin_McMillan.jpg"},{year:"1940",title:"Naming after planet Neptune",text:"They name the element Neptunium after the planet Neptune, which lies beyond Uranus, reflecting its position beyond uranium in the periodic table.",image:"images/elements/093_Np/08_Philip_Hauge_Abelson.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Neptunium emission spectrum",text:"Emission spectrum — Spectral lines of Neptunium (Np) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Neptunium in distant stars.",image:"images/elements/093_Np/11_93_(Np_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","np","93"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:93_%28Np_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Neptunium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-neptunium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/093_Np/16_Neptunium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Np","93"],sources:[{label:"NIST Atomic Spectra Database — Np I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Np+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],94:[{kind:"Portrait",title:"Highly polished pure plutonium metal ring",text:"Physical state — A highly polished, electro-refined ring of pure plutonium metal. Plutonium is a dense silvery-grey transition actinide that oxidizes rapidly in air, showing a yellowish tarnish. (plutonium metal ring)",image:"images/elements/094_Pu/04_Plutonium_ring.jpg",priority:"core",display_context:"orbital",tags:["portrait","Pu","94"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Uses",title:"Radioisotope thermoelectric generator radiation measurement",text:"Practical application — Radiation measurement associated with a radioisotope thermoelectric generator (RTG). Plutonium-238 heat sources are used in some RTGs; this image documents measurement equipment, not a spacecraft installation.",image:"images/elements/094_Pu/05_RTG_spacecraft.jpg",priority:"core",display_context:"orbital",tags:["uses","Pu","94"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Safety",title:"Plutonium alpha radiotoxicity warning",text:"[Safety Warning] Plutonium is highly toxic due to its alpha radioactivity and chemical heavy metal toxicity, accumulating in bone marrow if inhaled. (internal alpha emitter)",image:"images/elements/094_Pu/01_Plutonium_radioactivity_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Pu","94"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:S.I._No._132-1995_Warning_-_Radioactive_material.svg"}]},{kind:"History",title:"Plutonium discovery timeline",text:"Key milestones of plutonium: from Berkeley cyclotron deuteron bombardments to the historic Trinity test.",image:"images/elements/094_Pu/02_Glenn_T_Seaborg_1964.jpg",priority:"core",display_context:"orbital",tags:["history","Pu","94"],panel:{type:"timeline",items:[{year:"1940",title:"Glenn Seaborg and team synthesize plutonium",text:"Glenn T. Seaborg, Edwin McMillan, Joseph W. Kennedy, and Arthur Wahl synthesize plutonium-238 at UC Berkeley by bombarding uranium with deuterons.",image:"images/elements/094_Pu/02_Glenn_T_Seaborg_1964.jpg"},{year:"1945",title:"The Trinity Test and Fat Man",text:"The Manhattan Project detonates the first plutonium bomb (Trinity) in New Mexico, followed by the deployment of the Fat Man bomb in Nagasaki, ending World War II.",image:"images/elements/094_Pu/03_Trinity_test_tower_site.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Plutonium emission spectrum",text:"Emission spectrum — Spectral lines of Plutonium (Pu) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Plutonium in distant stars.",image:"images/elements/094_Pu/09_94_(Pu_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","pu","94"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:94_%28Pu_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Plutonium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-plutonium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/094_Pu/16_Plutonium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Pu","94"],sources:[{label:"NIST Atomic Spectra Database — Pu I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Pu+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],95:[{kind:"Portrait",title:"Purified americium metal under microscope",text:"Physical state — Purified americium metal sample viewed under a laboratory microscope. Americium is a silvery, highly radioactive actinide metal that glows faintly in the dark. (americium under microscope)",image:"images/elements/095_Am/09_Americium_microscope.jpg",priority:"core",display_context:"orbital",tags:["portrait","Am","95"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Americium_microscope.jpg"}]},{kind:"Safety",title:"Americium radioactive warning sign",text:"[Safety Warning] While safe in sealed smoke detectors, americium-241 is an extreme internal radiation hazard if inhaled or ingested. (internal radiation warning)",image:"images/elements/095_Am/01_Americium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Am","95"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Americium discovery timeline",text:"Key milestones of americium: from Chicago neutron bombardment synthesis to naming after the Americas.",image:"images/elements/095_Am/11_Glenn_Seaborg_ca_1951.jpg",priority:"core",display_context:"orbital",tags:["history","Am","95"],panel:{type:"timeline",items:[{year:"1944",title:"Glenn Seaborg and team synthesize americium",text:"Glenn T. Seaborg, Leon O. Morgan, Ralph A. James, and Albert Ghiorso synthesize americium-241 at the Chicago Metallurgical Lab by bombarding plutonium-239 with neutrons.",image:"images/elements/095_Am/11_Glenn_Seaborg_ca_1951.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Americium emission spectrum",text:"Emission spectrum — Spectral lines of Americium (Am) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Americium in distant stars.",image:"images/elements/095_Am/10_95_(Am_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","am","95"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:95_%28Am_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Americium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-americium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/095_Am/16_Americium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Am","95"],sources:[{label:"NIST Atomic Spectra Database — Am I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Am+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],96:[{kind:"Portrait",title:"Curium physical display sample",text:"Physical state — A photographed curium sample in a recessed metal holder, showing the minute physical quantity available for this synthetic radioactive actinide. Curium is made by nuclear irradiation rather than found in bulk natural deposits. (curium sample)",image:"images/elements/096_Cm/12_Curium_physical_sample.jpg",priority:"core",display_context:"orbital",tags:["portrait","physical-sample","Cm","96"],sources:[{label:"Wikimedia Commons — Curium (Element 96) physical sample (James St. John, CC BY 2.0)",url:"https://commons.wikimedia.org/wiki/File:Curium_(Element_-_96)_2.jpg"}]},{kind:"Science",title:"Curium oxide target wheel at RIKEN",text:"Nuclear-synthesis experiment — RIKEN's aluminum target wheel carries 16 curium oxide targets. A ²⁴⁸Cm + ⁵¹V reaction on this wheel was used in an attempt to synthesize element 119. (curium oxide targets)",image:"images/elements/096_Cm/10_Curium_oxide_targets.jpg",priority:"core",display_context:"orbital",tags:["science","Cm","96"],sources:[{label:"Wikimedia Commons — Curium oxide targets (RIKEN, CC BY 4.0)",url:"https://commons.wikimedia.org/wiki/File:Curium_oxide_targets.jpg"}]},{kind:"Safety",title:"Curium alpha radiotoxicity warning",text:"[Safety Warning] Curium-244 is highly radiotoxic; it bio-accumulates in bones and lungs, destroying cells with intense alpha radiation. (intense alpha emitter)",image:"images/elements/096_Cm/02_Curium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Cm","96"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Curium discovery timeline",text:"Key milestones of curium: its 1944 synthesis by the Berkeley–Chicago team and its name honoring the Curies' foundational work on radioactivity.",image:"images/elements/096_Cm/11_Glenn_Seaborg_in_laboratory.jpg",priority:"core",display_context:"orbital",tags:["history","Cm","96"],panel:{type:"timeline",items:[{year:"1944",title:"Seaborg, James, and Ghiorso synthesize curium",text:"Glenn T. Seaborg, Ralph A. James, and Albert Ghiorso first produce curium-242 by alpha-particle bombardment of plutonium-239. The work began at Berkeley and the product was chemically identified at the Chicago Metallurgical Laboratory.",image:"images/elements/096_Cm/11_Glenn_Seaborg_in_laboratory.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Seaborg_in_lab_-_restoration.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Curium emission spectrum",text:"Emission spectrum — Spectral lines of Curium (Cm) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Curium in distant stars.",image:"images/elements/096_Cm/09_96_(Cm_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","cm","96"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:96_%28Cm_I%29_NIST_ASD_emission_spectrum.png"}]}],97:[{kind:"Portrait",title:"Berkelium solution prepared for element-117 synthesis",text:"Verified material photograph — Dissolved berkelium-249 produced at Oak Ridge National Laboratory for the international element-117 synthesis campaign. The visible material is a prepared berkelium solution, not a bulk metallic sample.",image:"images/elements/097_Bk/12_Berkelium_solution_ORNL.jpg",priority:"core",display_context:"orbital",tags:["portrait","berkelium-249","solution","Bk","97"],sources:[{label:"Oak Ridge National Laboratory / U.S. Department of Energy · Public domain · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Berkelium.jpg"}]},{kind:"Safety",title:"Berkelium skeletal radiotoxin warning",text:"[Safety Warning] Berkelium is highly radioactive and accumulates in skeletal tissues, requiring strict glovebox handling. (skeletal radiotoxin)",image:"images/elements/097_Bk/01_Berkelium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Bk","97"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Berkelium discovery timeline",text:"Key milestones of berkelium: from Berkeley cyclotron alpha bombardment synthesis to naming after Berkeley.",image:"images/elements/097_Bk/11_Chemist_Glenn_Seaborg.jpg",priority:"core",display_context:"orbital",tags:["history","Bk","97"],panel:{type:"timeline",items:[{year:"1949",title:"Seaborg and team synthesize berkelium",text:"Glenn T. Seaborg, Albert Ghiorso, and Stanley G. Thompson first synthesize berkelium-243 at UC Berkeley by bombarding americium-241 with alpha particles in a cyclotron.",image:"images/elements/097_Bk/11_Chemist_Glenn_Seaborg.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Berkelium emission spectrum",text:"Emission spectrum — Spectral lines of Berkelium (Bk) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Berkelium in distant stars.",image:"images/elements/097_Bk/09_97_(Bk_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","bk","97"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:97_%28Bk_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Berkelium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-berkelium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/097_Bk/16_Berkelium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Bk","97"],sources:[{label:"NIST Atomic Spectra Database — Bk I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Bk+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],98:[{kind:"Portrait",title:"Californium-249 metal disc",text:"Physical sample — A 10-milligram disc of californium-249 metal, approximately 1 millimetre across. The photograph records one of the few macroscopic samples of this synthetic element.",image:"images/elements/098_Cf/10_Californium-249_metal_disc.jpg",priority:"core",display_context:"orbital",tags:["portrait","californium-249","metal","Cf","98"],sources:[{label:"U.S. Department of Energy · Public domain · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Californium.jpg"}]},{kind:"Safety",title:"Californium extreme neutron warning",text:"[Safety Warning] Californium-252 is an intense neutron emitter, presenting an extreme external radiation hazard that requires heavy concrete or water shielding. (extreme neutron radiation)",image:"images/elements/098_Cf/01_Californium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Cf","98"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Californium discovery timeline",text:"Key milestones of californium: from Berkeley alpha bombardments to naming after California.",image:"images/elements/098_Cf/08_Albert_Ghiorso.jpg",priority:"core",display_context:"orbital",tags:["history","Cf","98"],panel:{type:"timeline",items:[{year:"1950",title:"Albert Ghiorso and team synthesize californium",text:"Albert Ghiorso, Stanley G. Thompson, Kenneth Street Jr., and Glenn T. Seaborg synthesize californium-245 at UC Berkeley by bombarding curium-242 with alpha particles.",image:"images/elements/098_Cf/08_Albert_Ghiorso.jpg"},{year:"1950",title:"Naming in honor of California",text:"The discoverers name the new element Californium in honor of the State of California and the University of California.",image:"images/elements/098_Cf/03_Flag_of_California.svg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",display_hint:"spectrum",title:"Californium emission spectrum",text:"Emission spectrum — Spectral lines of Californium (Cf) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Californium in distant stars.",image:"images/elements/098_Cf/09_98_(Cf_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","cf","98"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:98_%28Cf_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Science",title:"Californium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-californium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/098_Cf/16_Californium_I_NIST_ASD_energy_levels.svg",priority:"standard",display_context:"orbital",tags:["science","energy-levels","NIST","Cf","98"],sources:[{label:"NIST Atomic Spectra Database — Cf I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Cf+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],99:[{kind:"Portrait",title:"Einsteinium-253 solid sample",text:"Physical sample — Approximately 300 micrograms of einsteinium-253 solid contained in a 9-millimetre quartz vial. The small, highly radioactive specimen is one of the rare visible samples of einsteinium.",image:"images/elements/099_Es/10_Einsteinium-253_solid_sample.jpg",priority:"core",display_context:"orbital",tags:["portrait","einsteinium-253","solid sample","Es","99"],sources:[{label:"U.S. Department of Energy · Public domain · Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Einsteinium.jpg"}]},{kind:"Science",display_hint:"spectrum",title:"Einsteinium emission spectrum",text:"Emission spectrum — Spectral lines of Einsteinium (Es) from the NIST Atomic Spectra Database. Each bright line marks a unique electron transition. Astronomers use these fingerprints to detect Einsteinium in distant stars.",image:"images/elements/099_Es/09_99_(Es_I)_NIST_ASD_emission_spectrum.png",priority:"standard",display_context:"orbital",tags:["science","spectrum","NIST","es","99"],sources:[{label:"NIST ASD",url:"https://physics.nist.gov/PhysRefData/ASD/"},{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:99_%28Es_I%29_NIST_ASD_emission_spectrum.png"}]},{kind:"Safety",title:"Einsteinium high alpha warning",text:"[Safety Warning] Einsteinium is highly radioactive and emits intense alpha particles and gamma rays, requiring remote glovebox handling. (high alpha activity)",image:"images/elements/099_Es/01_Einsteinium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Es","99"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Einsteinium discovery and namesake",text:"Discovery history — Einsteinium was identified in Ivy Mike fallout and was named for Albert Einstein. This portrait documents the namesake, not an alleged discovery-team photograph.",image:"images/elements/099_Es/07_Einstein_1921_portrait2.jpg",priority:"core",display_context:"orbital",tags:["history","Es","99"],panel:{type:"timeline",items:[{year:"1952",title:"Albert Ghiorso and team discover einsteinium in thermonuclear debris",text:"Albert Ghiorso and co-workers at Berkeley, Argonne, and Los Alamos discover einsteinium-253 in the fallout from the 'Ivy Mike' thermonuclear test in the Pacific.",image:"images/elements/099_Es/08_Ivy_Mike_mushroom_cloud.jpg"},{year:"1952",title:"Naming in honor of Albert Einstein",text:"The discoverers name the new element Einsteinium in honor of physicist Albert Einstein.",image:"images/elements/099_Es/07_Einstein_1921_portrait2.jpg"}]},sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Einstein_1921_portrait2.jpg"}]},{kind:"Science",title:"Einsteinium I energy levels",text:"Atomic data — A clean plot of the lowest neutral-einsteinium energy levels tabulated by NIST; each horizontal line is a measured or evaluated electronic state.",image:"images/elements/099_Es/16_Einsteinium_I_NIST_ASD_energy_levels.svg",priority:"core",display_context:"orbital",tags:["science","energy-levels","NIST","Es","99"],sources:[{label:"NIST Atomic Spectra Database — Es I energy levels",url:"https://physics.nist.gov/cgi-bin/ASD/energy1.pl?spectrum=Es+I&units=1&format=3&output=0&multiplet_ordered=0&conf_out=on&term_out=on&level_out=on&unc_out=1&j_out=on"}]}],100:[{kind:"Science",title:"Fermium–ytterbium alloy for vaporization study",text:"Experimental sample — An Oak Ridge National Laboratory fermium–ytterbium alloy used to measure the enthalpy of vaporization of fermium metal. Fermium makes up only 4 × 10⁻⁵ weight percent, so this is a research specimen rather than a visible pure-fermium portrait. (fermium–ytterbium alloy)",image:"images/elements/100_Fm/10_Fermium_ytterbium_alloy.jpg",priority:"core",display_context:"orbital",tags:["science","Fm","100"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org/wiki/File:Fermium-Ytterbium_Alloy.jpg"}]},{kind:"History",title:"Albert Ghiorso and the discovery of fermium",text:"Discovery history — Albert Ghiorso led the Berkeley group that, with colleagues at Los Alamos and Argonne, identified element 100 in debris from the 1952 Ivy Mike test. The archival cover shows Ghiorso circa 1955; the timeline records the element's namesake, Enrico Fermi.",image:"images/elements/100_Fm/11_Albert_Ghiorso_element_hunter_circa_1955.jpg",priority:"core",display_context:"orbital",tags:["history","discovery","Albert Ghiorso","Fm","100"],panel:{type:"timeline",items:[{year:"1955",title:"The element is named for Enrico Fermi",text:"After the discovery was declassified, element 100 was named fermium in honor of nuclear physicist Enrico Fermi.",image:"images/elements/100_Fm/07_Enrico_Fermi_1943-49.jpg"}]},sources:[{label:"Berkeley Lab — Albert Ghiorso, legendary element hunter",url:"https://newscenter.lbl.gov/2011/01/03/ghiorso-obit/"},{label:"Wikimedia Commons — Enrico Fermi, 1943–1949",url:"https://commons.wikimedia.org/wiki/File:Enrico_Fermi_1943-49.jpg"}]},{kind:"Safety",title:"Fermium severe radiotoxicity warning",text:"[Safety Warning] Fermium is extremely radioactive, presenting an intense alpha and spontaneous fission hazard. (radiotoxicity hazard)",image:"images/elements/100_Fm/01_Fermium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Fm","100"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],101:[{kind:"Science",title:"FIONA instrument used to confirm mendelevium-244",text:"Isotope research — Berkeley Lab's FIONA instrument at the 88-Inch Cyclotron separated and identified ions during the experiment that confirmed the new isotope mendelevium-244. This is the documented apparatus for that specific mendelevium measurement, not a generic laboratory photograph.",image:"images/elements/101_Md/12_FIONA_instrument_mendelevium_244_confirmation.jpg",priority:"core",display_context:"orbital",tags:["science","isotope","FIONA","Md","101"],sources:[{label:"Berkeley Lab — Introducing a New Isotope: Mendelevium-244",url:"https://newscenter.lbl.gov/2020/06/23/introducing-a-new-isotope-mendelevium-244/"}]},{kind:"Safety",title:"Mendelevium radiotoxicity warning",text:"[Safety Warning] Mendelevium is highly radioactive, presenting alpha emission and spontaneous fission hazards. (radiotoxicity hazard)",image:"images/elements/101_Md/01_Mendelevium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Md","101"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Mendelevium discovery timeline",text:"Key milestones of mendelevium: from Berkeley alpha bombardment synthesis to naming after Dmitri Mendeleev.",image:"images/elements/101_Md/10_Mendelevium_25th_anniversary_team.jpg",priority:"core",display_context:"orbital",tags:["history","Md","101"],panel:{type:"timeline",items:[{year:"1955",title:"Naming in honor of Dmitri Mendeleev",text:"The discoverers name the element Mendelevium in honor of Russian chemist Dmitri Mendeleev, the father of the periodic table.",image:"images/elements/101_Md/11_Dmitri_Mendeleev_in_laboratory.jpg"}]},sources:[{label:"Wikimedia Commons — 25th anniversary of the discovery of element 101",url:"https://commons.wikimedia.org/wiki/File:25th_anniversary_celebration_commemorating_the_discovery_of_element-101._G._Choppin,_Glenn_Seaborg,_B.G._Harvey,_and_Albert_Ghiorso._Photograph_taken_March_28,_1980._BBC8807-07139._-_DPLA_-_af8f363d95fee61acde8a270e0bc229c.jpg"},{label:"Wikimedia Commons — Dmitri Mendeleev in laboratory",url:"https://commons.wikimedia.org/wiki/File:Dmitri_Mendeleev_in_laboratory.jpg"}]}],102:[{kind:"Safety",title:"Nobelium intense alpha warning",text:"[Safety Warning] Nobelium-259 has a half-life of 58 minutes, presenting intense alpha decay radiation hazards. (intense alpha activity)",image:"images/elements/102_No/01_Nobelium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","No","102"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"The Berkeley element-102 team at HILAC",text:"Discovery history — Albert Ghiorso, Torbjørn Sikkeland and John R. Walton stand beside HILAC equipment in 1958. Berkeley Lab identifies them as members of the team that produced and reported element 102 that year, after the earlier Swedish claim could not be confirmed.",image:"images/elements/102_No/11_Nobelium_discovery_team_at_HILAC_1958.jpg",priority:"core",display_context:"orbital",tags:["history","No","102"],sources:[{label:"Berkeley Lab — Tributes to Albert Ghiorso",url:"https://newscenter.lbl.gov/2011/01/12/ghiorso-tributes/"}]}],103:[{kind:"History",title:"Berkeley's HILAC element programme",text:"Discovery history — Glenn Seaborg and Albert Ghiorso stand at Berkeley's HILAC in 1969, documenting the laboratory programme that produced lawrencium and other transuranium elements. This later archival photograph is not presented as the exact 1961 exposure.",image:"images/elements/103_Lr/10_Seaborg_and_Ghiorso_at_HILAC_1969.jpg",priority:"core",display_context:"orbital",tags:["history","discovery","HILAC","Lr","103"],panel:{type:"timeline",items:[{year:"1997",title:"The name lawrencium is standardized",text:"IUPAC retained the name honoring cyclotron inventor and Berkeley laboratory founder Ernest O. Lawrence.",image:"images/elements/103_Lr/08_Ernest_Lawrence_at_Bevatron.jpg"}]},sources:[{label:"Berkeley Lab — Tributes to Albert Ghiorso",url:"https://newscenter.lbl.gov/2011/01/12/ghiorso-tributes/"},{label:"Wikimedia Commons — Ernest Lawrence at the Bevatron",url:"https://commons.wikimedia.org/wiki/File:Ernest_Orlando_Lawrence,_William_Brobeck,_Harold_Fidler,_and_Donald_Cooksey_in_the_aperture_of_a_Bevatron_magnet_section_(portrait).jpg"}]},{kind:"Safety",title:"Lawrencium short-lived alpha hazard",text:"[Safety Warning] Lawrencium isotopes are short-lived alpha emitters, requiring strict shielding and micro-scale containment. (short-lived alpha hazard)",image:"images/elements/103_Lr/01_Lawrencium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Lr","103"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],104:[{kind:"Safety",title:"Rutherfordium fission and alpha hazard",text:"[Safety Warning] Rutherfordium isotopes decay within seconds or hours, presenting severe alpha and spontaneous fission hazards. (fission and alpha hazard)",image:"images/elements/104_Rf/01_Rutherfordium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Rf","104"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"Science",title:"Rutherfordium discovery experimental setup",text:"Experimental science — A labelled diagram of the apparatus used in early rutherfordium work, documenting the target, detector and collection geometry rather than depicting the element itself.",image:"images/elements/104_Rf/09_Rutherfordium_experimental_setup.jpeg",priority:"core",display_context:"orbital",tags:["science","experimental setup","Rf","104"],sources:[{label:"Wikimedia Commons — Rutherfordium experimental setup",url:"https://commons.wikimedia.org/wiki/File:Rutherfordium_experimental_setup.jpeg"}]},{kind:"History",title:"Rutherfordium's namesake, Ernest Rutherford",text:"Naming history — IUPAC adopted the name rutherfordium in 1997 to honor Ernest Rutherford, whose experiments established the nuclear model of the atom. The archival portrait shows the namesake, not the element's discovery team.",image:"images/elements/104_Rf/07_Ernest_Rutherford_LOC.jpg",priority:"core",display_context:"orbital",tags:["history","namesake","Rf","104"],sources:[{label:"Royal Society of Chemistry — Rutherfordium",url:"https://periodic-table.rsc.org/element/104/rutherfordium"},{label:"Wikimedia Commons — Ernest Rutherford",url:"https://commons.wikimedia.org/wiki/File:Ernest_Rutherford_LOC.jpg"}]}],105:[{kind:"Safety",title:"Dubnium spontaneous fission warning",text:"[Safety Warning] Dubnium-268 has a half-life of 28 hours, presenting high alpha decay and spontaneous fission hazards. (spontaneous fission hazard)",image:"images/elements/105_Db/01_Dubnium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Db","105"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],106:[{kind:"History",title:"Seaborgium team examines evidence for element 106",text:"Discovery history — Ken Hulet, Glenn T. Seaborg and Albert Ghiorso examine evidence for element 106 at Berkeley's SuperHILAC in 1974. Berkeley Lab's archive identifies the scene and participants directly, making this a discovery record rather than a generic laboratory photograph.",image:"images/elements/106_Sg/10_Seaborgium_106_evidence_team_1974.jpg",priority:"core",display_context:"orbital",tags:["history","discovery","SuperHILAC","Sg","106"],sources:[{label:"Berkeley Lab — Tributes to Albert Ghiorso",url:"https://newscenter.lbl.gov/2011/01/12/ghiorso-tributes/"}]},{kind:"Safety",title:"Seaborgium extreme radiation warning",text:"[Safety Warning] Seaborgium is extremely radioactive with a half-life of seconds, posing severe alpha and spontaneous fission hazards. (extreme short-lived radiation)",image:"images/elements/106_Sg/01_Seaborgium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Sg","106"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],107:[{kind:"History",title:"GSI ceremony for bohrium, hassium and meitnerium",text:"Discovery history — GSI's 1992 naming ceremony for elements 107–109, attended by members of the Darmstadt discovery programme. The ceremony marked the proposed names nielsbohrium, hassium and meitnerium.",image:"images/elements/107_Bh/10_GSI_1992_Bohrium_naming_ceremony.jpg",priority:"core",display_context:"orbital",tags:["history","Bh","107"],panel:{type:"timeline",items:[{year:"1981",title:"GSI's Darmstadt programme synthesizes element 107",text:"A scale model documents the GSI accelerator complex where the bohrium discovery experiment was carried out. It is the discovery institution, not a photograph of the exact irradiation.",image:"images/elements/107_Bh/07_GSI_Helmholtzzentrum.jpg"}]},sources:[{label:"GSI Helmholtzzentrum — Elements 107 to 109",url:"https://www.gsi.de/en/work/forschung/nustarenna/nustarenna_divisions/she_physik/research/super_heavy_elements/element_107_109"},{label:"Wikimedia Commons — GSI Helmholtzzentrum model",url:"https://commons.wikimedia.org/wiki/File:Model_of_GSI_Helmholtzzentrum_f%C3%BCr_Schwerionenforschung.jpg"}]},{kind:"Safety",title:"Bohrium extreme short-lived radiation warning",text:"[Safety Warning] Bohrium isotopes decay within seconds via alpha emission and spontaneous fission, posing extreme radiation hazards. (extreme alpha hazard)",image:"images/elements/107_Bh/01_Bohrium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Bh","107"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],108:[{kind:"History",title:"Peter Armbruster and GSI's hassium discovery programme",text:"Discovery history — Nuclear physicist Peter Armbruster initiated GSI's superheavy-element programme and co-led the team credited with discovering elements 107 through 112, including hassium in 1984. This is an official GSI portrait, not a claimed photograph of the 1984 irradiation.",image:"images/elements/108_Hs/10_Peter_Armbruster_GSI.jpg",priority:"core",display_context:"orbital",tags:["history","discovery","Peter Armbruster","Hs","108"],sources:[{label:"GSI/FAIR — Peter Armbruster",url:"https://www.gsi.de/en/start/news/details/2024/07/08/tod-peter-armbruster"}]},{kind:"Safety",title:"Hassium extreme radiation warning",text:"[Safety Warning] Hassium isotopes decay within seconds, presenting extreme alpha emission and spontaneous fission hazards. (extreme short-lived radiation)",image:"images/elements/108_Hs/01_Hassium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Hs","108"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],109:[{kind:"History",title:"Meitnerium's discoverer and namesake",text:"Discovery history — Meitnerium was synthesized by the GSI SHIP group in 1982 and later named for physicist Lise Meitner. The cover is an IAEA portrait of Meitner; the timeline identifies the discovery group's leader.",image:"images/elements/109_Mt/11_Lise_Meitner_IAEA_1963.jpg",priority:"core",display_context:"orbital",tags:["history","Mt","109"],panel:{type:"timeline",items:[{year:"1982",title:"Gottfried Münzenberg leads the SHIP discovery group",text:"Münzenberg led the GSI SHIP group responsible for the discoveries of elements 107 to 109, including meitnerium.",image:"images/elements/109_Mt/10_Gottfried_Muenzenberg_GSI.jpg"}]},sources:[{label:"Wikimedia Commons — Lise Meitner at the IAEA, 1963",url:"https://commons.wikimedia.org/wiki/File:Lise_Meitner_(cropped).jpg"},{label:"GSI — Gottfried Münzenberg",url:"https://www.gsi.de/en/start/news/details/2024/01/22/trauer-um-gottfried-muenzenberg"}]},{kind:"Safety",title:"Meitnerium extreme alpha hazard",text:"[Safety Warning] Meitnerium isotopes decay within seconds via alpha emission, representing an extreme short-lived radiation hazard. (extreme alpha hazard)",image:"images/elements/109_Mt/01_Meitnerium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Mt","109"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],110:[{kind:"History",title:"Darmstadtium discovery and naming at GSI",text:"Discovery history — GSI marked the official naming of element 110 as darmstadtium in 2003. The timeline preserves the separate 1994 discovery-team photograph and identifies the measured decay chain displayed by the researchers.",image:"images/elements/110_Ds/10_GSI_Darmstadtium_naming_ceremony_2003.jpg",priority:"core",display_context:"orbital",tags:["history","discovery team","GSI","Ds","110"],panel:{type:"timeline",items:[{year:"1994",title:"GSI's SHIP team identifies element 110",text:"The GSI team stands at the SHIP separator after the ²⁰⁸Pb(⁶²Ni,n)²⁶⁹Ds experiment. Their display shows the first observed darmstadtium-269 decay chain.",image:"images/elements/110_Ds/09_GSI_Darmstadtium_discovery_team_1994.jpg"}]},sources:[{label:"GSI Helmholtzzentrum — Element 110",url:"https://www.gsi.de/en/work/forschung/nustarenna/nustarenna_divisions/she_physik/research/super_heavy_elements/element_110"}]},{kind:"Safety",title:"Darmstadtium extreme radiation warning",text:"[Safety Warning] Darmstadtium isotopes decay within seconds via alpha emission, posing extreme radiation hazards. (extreme alpha hazard)",image:"images/elements/110_Ds/01_Darmstadtium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Ds","110"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],111:[{kind:"Science",title:"Measured decay chains of roentgenium-272",text:"Measured decay data — GSI's original record of the three observed ²⁷²Rg decay chains from the December 1994 ⁶⁴Ni + ²⁰⁹Bi experiment at SHIP. This is experimental identification data, not a recreated reaction graphic.",image:"images/elements/111_Rg/10_GSI_roentgenium_decay_chains_1994.gif",priority:"core",display_context:"orbital",tags:["science","Rg","111"],sources:[{label:"GSI Helmholtzzentrum — Element 111",url:"https://www.gsi.de/en/work/forschung/nustarenna/nustarenna_divisions/she_physik/research/super_heavy_elements/element_111"}]},{kind:"History",title:"Roentgenium is named for Wilhelm Röntgen",text:"Naming history — GSI's 1994 discovery was officially given the name roentgenium in honor of Wilhelm Conrad Röntgen, discoverer of X-rays. The portrait documents the namesake, while the separate Science card preserves the original decay-chain evidence.",image:"images/elements/111_Rg/08_Wilhelm_Röntgen.jpg",priority:"core",display_context:"orbital",tags:["history","namesake","Rg","111"],sources:[{label:"Wikimedia Commons — Wilhelm Röntgen",url:"https://commons.wikimedia.org/wiki/File:Wilhelm_R%C3%B6ntgen.jpg"},{label:"GSI Helmholtzzentrum — Element 111",url:"https://www.gsi.de/en/work/forschung/nustarenna/nustarenna_divisions/she_physik/research/super_heavy_elements/element_111"}]},{kind:"Safety",title:"Roentgenium extreme radiation warning",text:"[Safety Warning] Roentgenium isotopes decay within seconds via alpha emission, representing extreme short-lived radiation hazards. (extreme alpha hazard)",image:"images/elements/111_Rg/01_Roentgenium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Rg","111"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],112:[{kind:"History",title:"Copernicium is named for Nicolaus Copernicus",text:"Discovery and naming history — GSI's original measured decay chain documents the first identified element-112 nucleus in 1996, while the Toruń portrait documents the astronomer honored by the name copernicium.",image:"images/elements/112_Cn/08_Torun_portrait_of_Copernicus.jpg",priority:"core",display_context:"orbital",tags:["history","namesake","Cn","112"],sources:[{label:"Wikimedia Commons — Toruń portrait of Nicolaus Copernicus",url:"https://commons.wikimedia.org/wiki/File:Nikolaus_Kopernikus.jpg"},{label:"GSI Helmholtzzentrum — Element 112",url:"https://www.gsi.de/en/work/forschung/nustarenna/nustarenna_divisions/she_physik/research/super_heavy_elements/element_112"}]},{kind:"Safety",title:"Copernicium extreme radiation warning",text:"[Safety Warning] Copernicium isotopes decay within seconds via alpha emission, posing extreme radiation hazards. (extreme alpha hazard)",image:"images/elements/112_Cn/01_Copernicium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Cn","112"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],113:[{kind:"History",title:"Nihonium team announces the official name",text:"Discovery history — Kosuke Morita and colleagues at RIKEN announce the approved name nihonium in 2016. The timeline connects the public naming event with RIKEN Nishina Center, where the element was synthesized, and Morita's own briefing.",image:"images/elements/113_Nh/10_Nihonium_naming_press_conference_2016.jpg",priority:"core",display_context:"orbital",tags:["history","Nh","113"],panel:{type:"timeline",items:[{year:"2004–2012",title:"RIKEN Nishina Center confirms element 113",text:"The RIKEN accelerator complex in Wako is the documented facility where Morita's team produced and confirmed the decay chains assigned to element 113.",image:"images/elements/113_Nh/08_RIKEN_Nishina_Center.jpg"},{year:"2016",title:"Kosuke Morita explains the nihonium result",text:"Morita, leader of the RIKEN discovery team, speaks at the formal press conference following approval of the name nihonium.",image:"images/elements/113_Nh/11_Kosuke_Morita_nihonium_press_conference_2016.jpg"}]},sources:[{label:"Wikimedia Commons — Nihonium naming press conference",url:"https://commons.wikimedia.org/wiki/File:Hideto_Enyo_Kosuke_Morita_Koji_Morimoto_and_Hiroshi_Matsumoto_20161201.jpg"},{label:"Wikimedia Commons — RIKEN Nishina Center",url:"https://commons.wikimedia.org/wiki/File:Riken_src.jpg"},{label:"Wikimedia Commons — Kosuke Morita, 1 December 2016",url:"https://commons.wikimedia.org/wiki/File:Kosuke_Morita_20161201.jpg"}]},{kind:"Safety",title:"Nihonium extreme radiation warning",text:"[Safety Warning] Nihonium isotopes decay within seconds via alpha emission, posing extreme radiation hazards. (extreme alpha hazard)",image:"images/elements/113_Nh/01_Nihonium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Nh","113"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],114:[{kind:"Safety",title:"Flerovium extreme radiation warning",text:"[Safety Warning] Flerovium isotopes decay within seconds via alpha emission, presenting extreme radiation hazards. (extreme alpha hazard)",image:"images/elements/114_Fl/01_Flerovium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Fl","114"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],115:[{kind:"History",title:"Dawn Shaughnessy and LLNL's moscovium collaboration",text:"Discovery history — Dawn Shaughnessy was a co-author of the original element-115 synthesis paper from the JINR–LLNL collaboration. This Department of Energy portrait documents a scientist directly connected to the moscovium discovery experiment; it is not presented as the irradiation itself.",image:"images/elements/115_Mc/10_Dawn_Shaughnessy_LLNL_heavy_element_scientist.jpg",priority:"core",display_context:"orbital",tags:["history","discovery collaboration","LLNL","Mc","115"],sources:[{label:"Wikimedia Commons — Dawn Shaughnessy, Women @ Energy (U.S. DOE public domain)",url:"https://commons.wikimedia.org/wiki/File:Dawn_Shaughnessy_Women_@_Energy.jpg"},{label:"Physical Review C — original element-115 synthesis paper (D. A. Shaughnessy, co-author)",url:"https://doi.org/10.1103/PhysRevC.69.021601"}]},{kind:"Safety",title:"Moscovium extreme radiation warning",text:"[Safety Warning] Moscovium isotopes decay within fractions of a second via alpha emission, posing extreme radiation hazards. (extreme alpha hazard)",image:"images/elements/115_Mc/01_Moscovium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Mc","115"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],116:[{kind:"History",title:"Lawrence Livermore National Laboratory and element 116",text:"Discovery history — Lawrence Livermore National Laboratory was the U.S. partner in the JINR–LLNL collaboration that reported element 116, and livermorium was named for the laboratory and the city of Livermore. This Department of Energy photograph documents the named institution, not the synthesis apparatus or a sample of livermorium.",image:"images/elements/116_Lv/10_Lawrence_Livermore_National_Laboratory_entrance.jpg",priority:"core",display_context:"orbital",tags:["history","discovery collaboration","LLNL","Lv","116"],sources:[{label:"Wikimedia Commons — Lawrence Livermore National Laboratory entrance (U.S. DOE public domain)",url:"https://commons.wikimedia.org/wiki/File:U.S._Department_of_Energy_-_Science_-_392_074_001_(9563189099).jpg"},{label:"Royal Society of Chemistry — Livermorium",url:"https://periodic-table.rsc.org/element/116/livermorium"}]},{kind:"Safety",title:"Livermorium extreme radiation warning",text:"[Safety Warning] Livermorium isotopes decay within milliseconds via alpha emission, posing extreme radiation hazards. (extreme alpha hazard)",image:"images/elements/116_Lv/01_Livermorium_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Lv","116"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],117:[{kind:"Science",title:"Tennessine synthesis reaction",text:"Reaction record — The discovery experiment fused calcium-48 ions with a berkelium-249 target to form tennessine-294 and three neutrons. This diagram documents the synthesis route; it is not an image of tennessine material.",image:"images/elements/117_Ts/09_Tennessine_discovery_reaction.svg",priority:"standard",display_context:"orbital",tags:["science","Ts","117"],sources:[{label:"Royal Society of Chemistry — Tennessine",url:"https://periodic-table.rsc.org/element/117/tennessine"}]},{kind:"History",title:"Julie Ezold and ORNL's contribution to tennessine",text:"Synthesis history — Oak Ridge National Laboratory's isotope programme produced and processed the berkelium-249 target material required for element 117. The cover shows ORNL isotope scientist Julie Ezold in a documented laboratory setting; it is not claimed to be the tennessine irradiation or a photograph of tennessine itself.",image:"images/elements/117_Ts/10_Julie_Ezold_ORNL_isotope_scientist.jpg",priority:"core",display_context:"orbital",tags:["history","synthesis collaboration","ORNL","Ts","117"],panel:{type:"timeline",items:[{year:"2009–2010",title:"ORNL supplies the berkelium-249 target",text:"Oak Ridge National Laboratory in Tennessee produced and processed the rare berkelium-249 used by the international team that synthesized tennessine. The aerial view documents the contributing institution, not the exact target-production room.",image:"images/elements/117_Ts/09_ORNL_aerial_view_2.jpg"}]},sources:[{label:"Wikimedia Commons — Julie Ezold in ORNL Review (ORNL/DOE public domain)",url:"https://commons.wikimedia.org/wiki/File:Julie_Ezold_in_ORNL_Review.jpg"},{label:"Wikimedia Commons — Oak Ridge National Laboratory aerial view (U.S. DOE public domain)",url:"https://commons.wikimedia.org/wiki/File:Oak_Ridge_National_Laboratory_Aerial_View_2.jpg"},{label:"Oak Ridge National Laboratory — element 117 collaboration",url:"https://www.ornl.gov/staff-profile/julie-g-ezold"}]},{kind:"Safety",title:"Tennessine radioactive-material warning",text:"[Safety Warning] Tennessine exists only as a few short-lived atoms made in specialized research facilities; it has no everyday handling or consumer use. (research-only radioactive element)",image:"images/elements/117_Ts/01_Tennessine_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Ts","117"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]}],118:[{kind:"Safety",title:"Oganesson extreme radiation warning",text:"[Safety Warning] Oganesson-294 has a half-life of less than 1 millisecond. Only ~5 atoms have ever existed. Its extreme radioactivity and rarity make it purely a theoretical safety concern. (extreme short-lived radiation)",image:"images/elements/118_Og/01_Oganesson_radiation_warning.svg",priority:"standard",display_context:"orbital",tags:["safety","Og","118"],sources:[{label:"Wikimedia Commons",url:"https://commons.wikimedia.org"}]},{kind:"History",title:"Yuri Oganessian, oganesson’s namesake",text:"Discovery history — Oganesson was first identified in the JINR–LLNL collaboration and named for Yuri Oganessian. This 2022 meeting photograph shows Oganessian with Armenian president Vahagn Khachaturyan; it is not a discovery-team photograph.",image:"images/elements/118_Og/08_Yuri_Oganessian_2022.jpg",priority:"core",display_context:"orbital",tags:["history","Og","118"],sources:[{label:"Wikimedia Commons — President.am, Vahagn Khachaturyan and Yuri Oganessian (CC BY-SA 3.0)",url:"https://commons.wikimedia.org/wiki/File:Vahagn_Khachaturyan_and_Yuri_Oganessian-2.jpg"}]}]},n={26:[{year:"Ancient world",title:"Iron dagger records early metalworking",text:"An iron dagger with an ivory handle documents the long development of ironworking before industrial steel production.",image:"images/elements/026_Fe/16_Ancient_iron_dagger_with_ivory_handle.jpg"},{year:"Iron Age",title:"Iron tools and weapons transform material culture",text:"Archaeological iron artifacts document the transition from bronze to iron metallurgy, enabling durable tools, weapons, and infrastructure across many societies.",image:"images/elements/026_Fe/17_Iron_Age_artifacts_Pattanam.jpg"},{year:"1856",title:"Henry Bessemer patents the Bessemer process",text:"The process made large-scale steel production cheaper by blowing air through molten pig iron to remove impurities.",image:"images/elements/026_Fe/06_Bessemer_converter_Sheffield.jpg"}],61:[{year:"1945",title:"Oak Ridge isolates promethium from fission products",text:"Oak Ridge National Laboratory was the site where the research team isolated promethium while analyzing uranium fission products.",image:"images/elements/061_Pm/03_Oak_Ridge_National_Laboratory.jpg"},{year:"1945",title:"Jacob A. Marinsky and colleagues isolate promethium",text:"Marinsky, Lawrence E. Glendenin, and Charles D. Coryell separated the new element from uranium fission products.",image:"images/elements/061_Pm/07_Jacob_A_Marinsky.jpg"},{year:"1947",title:"Discovery announcement and naming",text:"The team announced the discovery and named the element after Prometheus, the Titan associated with stolen fire.",image:"images/elements/061_Pm/08_Lawrence_E_Glendenin.jpg"}],92:[{year:"1789",title:"Martin Heinrich Klaproth discovers uranium",text:"German chemist Martin Heinrich Klaproth discovers uranium in Berlin by analyzing pitchblende, naming it after the recently discovered planet Uranus.",image:"images/elements/092_U/15_Klaproth_Rijksmuseum.jpg"},{year:"1938",title:"Hahn, Strassmann, and Meitner discover nuclear fission",text:"Otto Hahn, Fritz Strassmann, and Lise Meitner discover nuclear fission in Berlin, proving that uranium nuclei split when bombarded with neutrons.",image:"images/elements/092_U/16_Hahn_Meitner_1912.jpg"}],95:[{year:"1944",title:"Glenn Seaborg and team synthesize americium",text:"Glenn T. Seaborg, Leon O. Morgan, Ralph A. James, and Albert Ghiorso synthesize americium-241 at the Chicago Metallurgical Lab by bombarding plutonium-239 with neutrons.",image:"images/elements/095_Am/11_Glenn_Seaborg_ca_1951.jpg"}],97:[{year:"1949",title:"Seaborg and team synthesize berkelium",text:"Glenn T. Seaborg, Albert Ghiorso, and Stanley G. Thompson first synthesize berkelium-243 at UC Berkeley by bombarding americium-241 with alpha particles in a cyclotron.",image:"images/elements/097_Bk/11_Chemist_Glenn_Seaborg.jpg"}],100:[{year:"1952–1955",title:"Albert Ghiorso helps identify element 100",text:"Ghiorso led the Berkeley group that identified element 100 in debris collected after the 1952 Ivy Mike thermonuclear test.",image:"images/elements/100_Fm/11_Albert_Ghiorso_element_hunter_circa_1955.jpg"},{year:"1955",title:"The element is named for Enrico Fermi",text:"After the discovery was declassified, element 100 was named fermium in honor of nuclear physicist Enrico Fermi.",image:"images/elements/100_Fm/07_Enrico_Fermi_1943-49.jpg"}],101:[{year:"1955",title:"The element is named for Dmitri Mendeleev",text:"The discoverers named element 101 for Dmitri Mendeleev, whose periodic system organized the chemical elements.",image:"images/elements/101_Md/11_Dmitri_Mendeleev_in_laboratory.jpg"},{year:"1980",title:"Discovery team marks mendelevium's 25th anniversary",text:"Glenn Seaborg, Albert Ghiorso, Bernard Harvey, and Gregory Choppin reunite to commemorate the discovery of element 101.",image:"images/elements/101_Md/10_Mendelevium_25th_anniversary_team.jpg"}],102:[{year:"1958",title:"Berkeley's HILAC team reports element 102",text:"Albert Ghiorso, Torbjørn Sikkeland, and John R. Walton stand beside the HILAC equipment used by the Berkeley element-102 programme.",image:"images/elements/102_No/11_Nobelium_discovery_team_at_HILAC_1958.jpg"}],103:[{year:"1961–1969",title:"Berkeley's HILAC programme produces lawrencium",text:"Glenn Seaborg and Albert Ghiorso are shown at HILAC, the accelerator programme associated with Berkeley's transuranium discoveries.",image:"images/elements/103_Lr/10_Seaborg_and_Ghiorso_at_HILAC_1969.jpg"},{year:"1997",title:"The name lawrencium is standardized",text:"IUPAC retained the name honoring cyclotron inventor and Berkeley laboratory founder Ernest O. Lawrence.",image:"images/elements/103_Lr/08_Ernest_Lawrence_at_Bevatron.jpg"}],104:[{year:"1997",title:"IUPAC adopts the name rutherfordium",text:"The approved name honors Ernest Rutherford, whose experiments established the nuclear model of the atom.",image:"images/elements/104_Rf/07_Ernest_Rutherford_LOC.jpg"}],106:[{year:"1974",title:"Berkeley team examines evidence for element 106",text:"Ken Hulet, Glenn T. Seaborg, and Albert Ghiorso examine the experimental evidence at Berkeley's SuperHILAC.",image:"images/elements/106_Sg/10_Seaborgium_106_evidence_team_1974.jpg"}],107:[{year:"1981",title:"GSI's Darmstadt programme synthesizes element 107",text:"The GSI accelerator complex is the documented institution where the bohrium discovery experiment was carried out.",image:"images/elements/107_Bh/07_GSI_Helmholtzzentrum.jpg"},{year:"1992",title:"GSI holds its naming ceremony for elements 107–109",text:"Members of the Darmstadt programme gather as GSI presents its proposed names for bohrium, hassium, and meitnerium.",image:"images/elements/107_Bh/10_GSI_1992_Bohrium_naming_ceremony.jpg"}],108:[{year:"1984",title:"Peter Armbruster co-leads GSI's hassium programme",text:"Armbruster initiated GSI's superheavy-element programme and co-led the team credited with synthesizing hassium.",image:"images/elements/108_Hs/10_Peter_Armbruster_GSI.jpg"}],109:[{year:"1982",title:"Gottfried Münzenberg leads the SHIP discovery group",text:"Münzenberg led the GSI SHIP group responsible for the discovery of meitnerium.",image:"images/elements/109_Mt/10_Gottfried_Muenzenberg_GSI.jpg"},{year:"1997",title:"The name meitnerium honors Lise Meitner",text:"The approved name recognizes physicist Lise Meitner and her contributions to nuclear physics.",image:"images/elements/109_Mt/11_Lise_Meitner_IAEA_1963.jpg"}],110:[{year:"1994",title:"GSI's SHIP team identifies element 110",text:"The discovery team stands at SHIP with a display of the first observed darmstadtium-269 decay chain.",image:"images/elements/110_Ds/09_GSI_Darmstadtium_discovery_team_1994.jpg"},{year:"2003",title:"GSI marks the official name darmstadtium",text:"The naming ceremony records the element's connection to Darmstadt, the German city where it was discovered.",image:"images/elements/110_Ds/10_GSI_Darmstadtium_naming_ceremony_2003.jpg"}],111:[{year:"1895",title:"Wilhelm Röntgen discovers X-rays",text:"The element's later name honors Wilhelm Conrad Röntgen, whose experiments revealed X-rays.",image:"images/elements/111_Rg/08_Wilhelm_Röntgen.jpg"},{year:"2004",title:"Element 111 receives the name roentgenium",text:"GSI's discovery was officially named roentgenium in honor of Röntgen.",image:"images/elements/111_Rg/09_Roentgenium_GSI_presentation.jpg"}],112:[{year:"1996",title:"GSI records the first identified element-112 decay chain",text:"GSI's original experimental figure records the measured alpha energies and decay times from the single ²⁷⁷Cn nucleus observed on 9 February 1996 after zinc-70 fused with lead-208.",image:"images/elements/112_Cn/09_GSI_element112_original_decay_chain_1996.png"},{year:"2010",title:"Copernicium is named for Nicolaus Copernicus",text:"The approved name honors the astronomer whose heliocentric model transformed the description of the Solar System.",image:"images/elements/112_Cn/08_Torun_portrait_of_Copernicus.jpg"}],113:[{year:"2004–2012",title:"RIKEN Nishina Center confirms element 113",text:"The RIKEN accelerator complex in Wako is where Morita's team produced and confirmed the decay chains assigned to element 113.",image:"images/elements/113_Nh/08_RIKEN_Nishina_Center.jpg"},{year:"2016",title:"The team publicly announces the name nihonium",text:"Kosuke Morita and colleagues gather at the official press conference announcing the approved name.",image:"images/elements/113_Nh/10_Nihonium_naming_press_conference_2016.jpg"},{year:"2016",title:"Kosuke Morita explains the nihonium result",text:"Morita, leader of the RIKEN discovery team, speaks at the formal press briefing after the name was approved.",image:"images/elements/113_Nh/11_Kosuke_Morita_nihonium_press_conference_2016.jpg"}],115:[{year:"2003",title:"Dawn Shaughnessy joins the element-115 collaboration",text:"Shaughnessy was a co-author of the original synthesis paper from the Joint Institute for Nuclear Research and Lawrence Livermore collaboration.",image:"images/elements/115_Mc/10_Dawn_Shaughnessy_LLNL_heavy_element_scientist.jpg"}],116:[{year:"2012",title:"Livermorium is named for Lawrence Livermore",text:"The approved name recognizes Lawrence Livermore National Laboratory and the city of Livermore.",image:"images/elements/116_Lv/10_Lawrence_Livermore_National_Laboratory_entrance.jpg"}],117:[{year:"2009–2010",title:"Julie Ezold and ORNL prepare the berkelium target",text:"ORNL's isotope programme produced and processed the rare berkelium-249 required for the element-117 experiment.",image:"images/elements/117_Ts/10_Julie_Ezold_ORNL_isotope_scientist.jpg"},{year:"2009–2010",title:"Oak Ridge supplies berkelium-249",text:"Oak Ridge National Laboratory in Tennessee supplied the target material used by the international synthesis team.",image:"images/elements/117_Ts/09_ORNL_aerial_view_2.jpg"}],118:[{year:"2016",title:"Oganesson is named for Yuri Oganessian",text:"The approved name honors physicist Yuri Oganessian for his work on superheavy elements.",image:"images/elements/118_Og/08_Yuri_Oganessian_2022.jpg"}]};for(const[a,s]of Object.entries(n)){const t=o[a],i=t.filter(e=>e.kind==="History"),r=i.find(e=>e.panel?.type==="timeline")??i[0];if(r){r.image||(r.image=s.find(e=>e.image)?.image??""),r.panel={type:"timeline",items:s};for(let e=t.length-1;e>=0;e-=1)t[e].kind==="History"&&t[e]!==r&&t.splice(e,1)}}for(const a of Object.values(o)){const s=a.findIndex(i=>i.kind==="Science"),t=a.findIndex(i=>i.kind==="Science"&&i.tags?.includes("spectrum"));if(s!==-1&&t>s){const[i]=a.splice(t,1);a.splice(s,0,i)}}export{o as elementArchives};
